import React, { useState, useMemo, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useStore } from '../store/useStore';
import type { User, ToastMessage, Profile, ProfileTransaction, CompanySettings, Customer } from '../types';
import { SearchIcon, PencilIcon, TrashIcon, ChevronDownIcon, WarehouseIcon, CloudUploadIcon, UserPlusIcon, UserIcon } from '../components/Icon';
import AddProfileModal from '../components/AddProfileModal'; // Import the reusable AddProfileModal
import CustomerModal from '../components/CustomerModal'; // Import the new CustomerModal component

declare const XLSX: any;
declare const jspdf: any;

interface ProfileSectionProps {
    addToast: (message: string, type: ToastMessage['type']) => void;
}

type Tab = 'Stock' | 'Planning' | 'Production' | 'Dispatch' | 'Scrap' | 'Quotations' | 'Profiles' | 'Customers';

// --- PORTAL COMPONENT ---
const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};

// --- TABLE COMPONENTS ---
const StockTable: React.FC<any> = ({ stockData, onEditProfile, getBrandBadge }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700"><tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Name</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Stock</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-right no-print">Edit</th></tr></thead>
        <tbody>{stockData.map((p: any) => (<tr key={p.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
            <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4 font-medium">{p.sku}</td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{p.name}</td><td className="px-6 py-4 text-xs">{p.length}m | {p.weight}kg</td><td className="px-6 py-4 text-right"><span className="font-bold text-blue-600 text-lg">{p.currentStock}</span> {p.reservedStock > 0 && <span className="text-xs text-orange-500 block">(-{p.reservedStock} Rsrvd)</span>}</td><td className="px-6 py-4 text-center">{p.currentStock < (p.reorderPoint || 0) ? <span className="text-red-500 font-bold">Low</span> : <span className="text-green-500">OK</span>}</td>
            <td className="px-6 py-4 text-right no-print"><button onClick={() => onEditProfile(p)} className="text-blue-500 hover:underline">Edit</button></td>
        </tr>))}</tbody>
    </table>
);

const PlanningTable: React.FC<any> = ({ planningData, getBrandBadge, planningTimeFilter }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Profile Name</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Current Stock</th><th className="px-6 py-3 text-right">{planningTimeFilter === 'ALL' ? 'All Time Sales' : `Sales (${planningTimeFilter})`}</th><th className="px-6 py-3 text-right">Share %</th></tr>
        </thead>
        <tbody>
            {planningData.map((p: any) => (
                <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                    <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4 font-medium">{p.sku}</td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{p.name}</td><td className="px-6 py-4 text-xs text-gray-500">{p.length}m | {p.weight}kg</td>
                    <td className="px-6 py-4 text-right font-bold text-gray-800 dark:text-gray-200">{p.currentStock}</td>
                    <td className="px-6 py-4 text-right text-blue-600 dark:text-blue-400">{p.periodSales}</td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex flex-col items-end">
                            <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{p.sharePercentage.toFixed(1)}%</span>
                            <div className="w-24 h-1.5 bg-gray-200 dark:bg-gray-600 rounded-full mt-1"><div className="h-1.5 bg-blue-500 rounded-full" style={{ width: `${Math.min(p.sharePercentage, 100)}%` }}></div></div>
                        </div>
                    </td>
                </tr>
            ))}
        </tbody>
    </table>
);

const TransactionTable: React.FC<any> = ({ transactions, getProfileName, getProfileSpecs, onEdit, onDelete, type, getBrandBadge, getProfile }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Quantity</th>{type === 'DISPATCH' && <th className="px-6 py-3">Customer</th>}{type === 'SCRAP' && <><th className="px-6 py-3">Machine</th><th className="px-6 py-3">Die</th></>}<th className="px-6 py-3 text-right">Actions</th></tr>
        </thead>
        <tbody>
            {transactions.map((t: any) => (
                <tr key={t.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                    <td className="px-6 py-4">{getBrandBadge(getProfile(t.profileId)?.brand)}</td>
                    <td className="px-6 py-4">{new Date(t.date).toLocaleDateString()}</td><td className="px-6 py-4 font-medium">{t.refNo}</td><td className="px-6 py-4">{getProfileName(t.profileId)}</td><td className="px-6 py-4 text-xs text-gray-500">{getProfileSpecs(t.profileId)}</td>
                    <td className={`px-6 py-4 text-right font-semibold ${type === 'PRODUCTION' ? 'text-green-600' : 'text-red-600'}`}>
                        {t.quantity} {t.type === 'SCRAP' ? (t.uom || 'Pcs') : ''}
                    </td>
                    {type === 'DISPATCH' && <td className="px-6 py-4">{t.customer}</td>}{type === 'SCRAP' && <><td className="px-6 py-4">{t.machine}</td><td className="px-6 py-4">{t.die}</td></>}<td className="px-6 py-4 text-right space-x-3"><button onClick={() => onEdit(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => onDelete(t.id)} className="text-red-500 hover:underline">Delete</button></td>
                </tr>
            ))}
        </tbody>
    </table>
);

const QuotationTable: React.FC<any> = ({ transactions, getProfileName, getProfileSpecs, onAction, onEdit, onDelete, getBrandBadge, getProfile }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Customer</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Qty</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-center">Confirm</th><th className="px-6 py-3 text-right">Actions</th></tr>
        </thead>
        <tbody>
            {transactions.map((t: any) => (
                <tr key={t.id} className={`border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 ${t.status === 'CANCELLED' ? 'opacity-50' : ''}`}>
                    <td className="px-6 py-4">{getBrandBadge(getProfile(t.profileId)?.brand)}</td>
                    <td className="px-6 py-4">{new Date(t.date).toLocaleDateString()}</td><td className="px-6 py-4 font-medium">{t.refNo}</td><td className="px-6 py-4">{t.customer}</td><td className="px-6 py-4">{getProfileName(t.profileId)}</td><td className="px-6 py-4 text-xs text-gray-500">{getProfileSpecs(t.profileId)}</td><td className="px-6 py-4 text-right text-orange-600 font-semibold">{t.quantity}</td>
                    <td className="px-6 py-4 text-center"><span className={`px-2 py-1 rounded-full text-xs ${t.status === 'PENDING' ? 'bg-yellow-100 text-yellow-800' : t.status === 'COMPLETED' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{t.status}</span></td>
                    <td className="px-6 py-4 text-center space-x-2">{t.status === 'PENDING' && <><button onClick={() => onAction(t.id, 'CONFIRM')} className="text-green-600 hover:text-green-800 font-bold">✓</button><button onClick={() => onAction(t.id, 'CANCEL')} className="text-red-500 hover:text-red-700 font-bold">✕</button></>}</td>
                    <td className="px-6 py-4 text-right space-x-2"><button onClick={() => onEdit(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => onDelete(t.id)} className="text-red-500 hover:underline">Del</button></td>
                </tr>
            ))}
        </tbody>
    </table>
);

const ProfileListTable: React.FC<any> = ({ profiles, onEdit, onDelete, getBrandBadge }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Name</th><th className="px-6 py-3">UOM</th><th className="px-6 py-3">Length (m)</th><th className="px-6 py-3">Length Weight</th><th className="px-6 py-3">Price</th><th className="px-6 py-3 text-right">Actions</th></tr>
        </thead>
        <tbody>
            {profiles.map((p: any) => (
                <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                    <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4">{p.sku}</td><td className="px-6 py-4">{p.name}</td><td className="px-6 py-4">{p.uom}</td><td className="px-6 py-4">{p.length || '-'}</td><td className="px-6 py-4">{p.weight || '-'}</td><td className="px-6 py-4">{p.price?.toLocaleString()}</td>
                    <td className="px-6 py-4 text-right space-x-3"><button onClick={() => onEdit(p)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => onDelete(p.id)} className="text-red-500 hover:underline">Delete</button></td>
                </tr>
            ))}
        </tbody>
    </table>
);

const CustomerTable: React.FC<any> = ({ customers, onEdit, onDelete }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700"><tr><th className="px-6 py-3">Customer Name</th><th className="px-6 py-3">Phone</th><th className="px-6 py-3">GSTIN</th><th className="px-6 py-3">Address</th><th className="px-6 py-3 text-right">Actions</th></tr></thead>
        <tbody>
            {customers.map((c: any) => (
                <tr key={c.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                    <td className="px-6 py-4 font-medium text-gray-900 dark:text-white flex items-center gap-2"><UserIcon className="w-4 h-4 text-gray-400"/> {c.name}</td><td className="px-6 py-4">{c.phone || '-'}</td><td className="px-6 py-4">{c.gstin || '-'}</td><td className="px-6 py-4 text-xs max-w-xs truncate">{c.address || '-'}</td>
                    <td className="px-6 py-4 text-right space-x-3"><button onClick={() => onEdit(c)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => onDelete(c.id)} className="text-red-500 hover:underline">Delete</button></td>
                </tr>
            ))}
        </tbody>
    </table>
);

// --- MODAL IMPLEMENTATIONS (FULL) ---
const TransactionModal: React.FC<any> = ({ isOpen, onClose, type, profiles, onAdd, addToast, customers, addCustomer }) => {
    const [form, setForm] = useState({ profileId: profiles[0]?.id || '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' });
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    const selectedProfile = useMemo(() => profiles.find((p:any) => p.id === form.profileId), [profiles, form.profileId]);
    const totalWeight = useMemo(() => (!selectedProfile || !form.quantity) ? 0 : (selectedProfile.weight || 0) * parseFloat(form.quantity), [selectedProfile, form.quantity]);

    useEffect(() => { 
        if(isOpen) { 
            const firstProfileId = profiles[0]?.id || '';
            setForm(prev => ({...prev, profileId: firstProfileId, quantity: '', uom: 'Pcs', refNo: '', machine: '', die: ''})); 
            setPosition({ x: 0, y: 0 }); 
        } 
    }, [isOpen, profiles]);

    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;

    const filteredCustomers = customers.filter((c:any) => c.name.toLowerCase().includes(customerSearch.toLowerCase()) && !c.deletedAt);
    const selectCustomer = (c: any) => { setForm(prev => ({ ...prev, customer: c.name, customerAddress: c.address || '', customerGST: c.gstin || '', customerPhone: c.phone || '' })); setCustomerSearch(c.name); setShowSuggestions(false); };
    const handleSaveCustomer = () => { if (!form.customer) return; addCustomer({ name: form.customer, address: form.customerAddress, gstin: form.customerGST, phone: form.customerPhone }); addToast('Customer saved', 'success'); };
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); onAdd({ ...form, quantity: parseFloat(form.quantity), type }); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md flex flex-col max-h-[90vh] my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={onMouseDownHeader} className="px-6 py-4 bg-gray-900 text-white rounded-t-xl border-b border-gray-700 flex justify-between items-center shrink-0 cursor-move select-none relative z-10 min-h-[60px]">
                    <h2 className="text-xl font-bold">{type === 'QUOTATION' ? 'Create Quotation' : type === 'DISPATCH' ? 'Record Dispatch' : type === 'SCRAP' ? 'Record Scrap' : 'Record Production'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl leading-none">&times;</button>
                </div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0">
                    <form onSubmit={handleSubmit} className="space-y-3">
                        <div><label className="block text-xs font-medium dark:text-gray-300">Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required /></div>
                        <div><label className="block text-xs font-medium dark:text-gray-300">Profile</label><select value={form.profileId} onChange={e => setForm({...form, profileId: e.target.value})} className={inputClass}>{profiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select>{selectedProfile && <div className="mt-2 p-2 bg-gray-5 dark:bg-gray-700/50 rounded border dark:border-gray-600 text-xs space-y-1"><div className="flex justify-between"><span>Specs:</span> <span className="font-medium">{selectedProfile.length}m / {selectedProfile.weight}kg</span></div><div className="flex justify-between"><span>Est. Total Weight:</span> <span className="font-bold text-blue-600 dark:text-blue-400">{totalWeight.toLocaleString()} kg</span></div></div>}</div>
                        <div><label className="block text-xs font-medium dark:text-gray-300">Ref No.</label><input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} required /></div>
                        <div className="flex gap-2">
                            <div className="flex-1"><label className="block text-xs font-medium dark:text-gray-300">Quantity</label><input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} required /></div>
                            {type === 'SCRAP' && (
                                <div className="w-24">
                                    <label className="block text-xs font-medium dark:text-gray-300">Unit</label>
                                    <select value={form.uom} onChange={e => setForm({...form, uom: e.target.value})} className={inputClass}>
                                        <option value="Pcs">Pcs</option>
                                        <option value="Kgs">Kgs</option>
                                    </select>
                                </div>
                            )}
                        </div>
                        {type === 'SCRAP' && <div className="grid grid-cols-2 gap-2"><div><label className="block text-xs font-medium dark:text-gray-300">Machine No.</label><input value={form.machine} onChange={e => setForm({...form, machine: e.target.value})} className={inputClass} /></div><div><label className="block text-xs font-medium dark:text-gray-300">Die No.</label><input value={form.die} onChange={e => setForm({...form, die: e.target.value})} className={inputClass} /></div></div>}
                        {(type === 'QUOTATION' || type === 'DISPATCH') && <><div className="relative"><label className="block text-xs font-medium dark:text-gray-300">Customer Name (Search)</label><input value={form.customer} onChange={e => { setForm({...form, customer: e.target.value}); setCustomerSearch(e.target.value); setShowSuggestions(true); }} onFocus={() => setShowSuggestions(true)} className={inputClass} required placeholder="Type to search..." />{showSuggestions && customerSearch && filteredCustomers.length > 0 && (<div className="absolute z-20 w-full bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">{filteredCustomers.map((c:any) => (<div key={c.id} onClick={() => selectCustomer(c)} className="px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-600 cursor-pointer text-sm"><div className="font-medium">{c.name}</div><div className="text-xs text-gray-500">{c.phone}</div></div>))}</div>)}</div><div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded border dark:border-gray-700 space-y-2"><div className="flex justify-between items-center"><p className="text-xs font-bold text-gray-500">Customer Details</p><button type="button" onClick={handleSaveCustomer} className="text-xs text-blue-600 hover:underline flex items-center gap-1"><UserPlusIcon className="w-3 h-3"/> Save Customer</button></div><input placeholder="Address" value={form.customerAddress} onChange={e => setForm({...form, customerAddress: e.target.value})} className={inputClass}/><div className="grid grid-cols-2 gap-2"><input placeholder="GSTIN" value={form.customerGST} onChange={e => setForm({...form, customerGST: e.target.value})} className={inputClass}/><input placeholder="Mobile" value={form.customerPhone} onChange={e => setForm({...form, customerPhone: e.target.value})} className={inputClass}/></div></div></>}
                        <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save</button></div>
                    </form>
                </div>
            </div>
        </div>
    );
};

const EditTransactionModal: React.FC<any> = ({ isOpen, onClose, transaction, onUpdate }) => {
    const [form, setForm] = useState(transaction);
    useEffect(() => setForm(transaction), [transaction]);
    if(!isOpen) return null;
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); onUpdate({...transaction, ...form, quantity: parseFloat(form.quantity)}); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none";
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
                <h2 className="text-xl font-bold mb-4 dark:text-white">Edit</h2>
                <form onSubmit={handleSubmit} className="space-y-3">
                    <input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} placeholder="Ref No"/>
                    <input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} placeholder="Qty"/>
                    {transaction.type === 'SCRAP' && <div className="grid grid-cols-2 gap-2"><input value={form.machine || ''} onChange={e => setForm({...form, machine: e.target.value})} className={inputClass} placeholder="Machine"/><input value={form.die || ''} onChange={e => setForm({...form, die: e.target.value})} className={inputClass} placeholder="Die"/></div>}
                    <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded">Update</button>
                </form>
            </div>
        </div>
    );
};

const ManageBrandsModal: React.FC<any> = ({ isOpen, onClose, brands, addBrand, deleteBrand, addToast }) => {
    const [newB, setNewB] = useState('');
    if (!isOpen) return null;
    const handleAdd = () => { if (newB.trim() && !brands.includes(newB.trim())) { addBrand(newB.trim()); setNewB(''); } else { addToast('Brand already exists or is empty.', 'error'); } };
    const handleDelete = (e: React.MouseEvent, brand: string) => { e.stopPropagation(); deleteBrand(brand); };
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-sm" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">Manage Brands</h3>
                <div className="flex gap-2 mb-4"><input value={newB} onChange={e => setNewB(e.target.value)} className="border p-2 flex-1 rounded dark:bg-gray-700 dark:text-white dark:border-gray-600"/><button onClick={handleAdd} className="bg-blue-600 text-white px-4 rounded">Add</button></div>
                <div className="max-h-48 overflow-y-auto border rounded dark:border-gray-600">
                    {brands.map((b:string) => <div key={b} className="flex justify-between p-2 border-b dark:border-gray-700 dark:text-gray-200"><span>{b}</span><button onClick={(e) => handleDelete(e, b)} className="text-red-500">Del</button></div>)}
                </div>
                <button onClick={onClose} className="mt-4 w-full border p-2 rounded dark:text-white">Close</button>
            </div>
        </div>
    );
};

const CompanySettingsModal: React.FC<any> = ({ isOpen, onClose, settings, updateSettings, addToast }) => {
    const [form, setForm] = useState(settings);
    const [logoPreview, setLogoPreview] = useState(settings.logoUrl || '');
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { if(isOpen) { setForm(settings); setLogoPreview(settings.logoUrl || ''); setPosition({ x: 0, y: 0 }); } }, [isOpen, settings]);
    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;
    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (file) { const reader = new FileReader(); reader.onloadend = () => { const result = reader.result as string; setForm({ ...form, logoUrl: result }); setLogoPreview(result); }; reader.readAsDataURL(file); } };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white p-2 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none";
    const labelClass = "block text-xs font-medium mb-1 text-gray-700 dark:text-gray-300";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={onMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]"><h2 className="text-xl font-bold flex items-center gap-2"><WarehouseIcon className="w-6 h-6 text-blue-400"/> Company Settings</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button></div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                    <div className="flex flex-col items-center p-6 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 mb-6">
                        <div className="w-48 h-32 bg-white dark:bg-black/20 border border-gray-300 dark:border-gray-600 rounded-lg flex items-center justify-center overflow-hidden mb-4 shadow-sm">{logoPreview ? <img src={logoPreview} alt="Logo" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-400 text-xs">No Logo</span>}</div>
                        <label className="cursor-pointer bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-bold hover:bg-blue-700 flex gap-2"><CloudUploadIcon className="w-4 h-4"/> Upload Logo <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" /></label>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">General Info</h3><div><label className={labelClass}>Company Name</label><input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>GSTIN</label><input value={form.gstin} onChange={e => setForm({...form, gstin: e.target.value})} className={inputClass} /></div><div className="grid grid-cols-2 gap-3"><div><label className={labelClass}>Phone</label><input value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Email</label><input value={form.email} onChange={e => setForm({...form, email: e.target.value})} className={inputClass} /></div></div></div>
                        <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">Address</h3><div><label className={labelClass}>Address Line 1</label><input value={form.addressLine1} onChange={e => setForm({...form, addressLine1: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Address Line 2</label><input value={form.addressLine2} onChange={e => setForm({...form, addressLine2: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>City, State, Zip</label><input value={form.cityStateZip} onChange={e => setForm({...form, cityStateZip: e.target.value})} className={inputClass} /></div></div>
                    </div>
                    <div className="mt-6 space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">Bank & Terms</h3><div className="grid grid-cols-2 gap-4"><div><label className={labelClass}>Bank Name</label><input value={form.bankName} onChange={e => setForm({...form, bankName: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Account No</label><input value={form.accountNo} onChange={e => setForm({...form, accountNo: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>IFSC</label><input value={form.ifsc} onChange={e => setForm({...form, ifsc: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Branch</label><input value={form.branch} onChange={e => setForm({...form, branch: e.target.value})} className={inputClass} /></div></div><div><label className={labelClass}>Terms</label><textarea value={form.terms} onChange={e => setForm({...form, terms: e.target.value})} className={inputClass} rows={2} /></div></div>
                </div>
                <div className="p-4 bg-gray-100 dark:bg-gray-700 rounded-b-xl flex justify-end gap-3 shrink-0 border-t border-gray-200 dark:border-gray-600"><button onClick={onClose} className="px-5 py-2 bg-white dark:bg-gray-600 border rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 text-gray-700 dark:text-white transition-colors">Cancel</button><button onClick={() => { updateSettings(form); addToast('Settings Saved', 'success'); onClose(); }} className="px-6 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 shadow transition-colors">Save Settings</button></div>
            </div>
        </div>
    );
};

const EditProfileModal: React.FC<{ isOpen: boolean; onClose: () => void; profile: Profile | null; brands: string[]; onUpdate: (p: Profile) => void; addToast: any; }> = ({ isOpen, onClose, profile, brands, onUpdate, addToast }) => {
    const [form, setForm] = useState({ sku: '', name: '', brand: '', uom: 'Pcs', length: '', piecesPerPacket: '', weight: '', price: '', reorderPoint: '' });

    useEffect(() => {
        if (profile) {
            setForm({
                sku: profile.sku || '',
                name: profile.name || '',
                brand: profile.brand || (brands[0] || ''),
                uom: profile.uom || 'Pcs',
                length: String(profile.length || ''),
                piecesPerPacket: String(profile.piecesPerPacket || ''),
                weight: String(profile.weight || ''),
                price: String(profile.price || ''),
                reorderPoint: String(profile.reorderPoint || ''),
            });
        }
    }, [profile, brands]);

    if (!isOpen || !profile) return null;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setForm(f => ({ ...f, [e.target.name]: e.target.value }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onUpdate({ 
            ...profile, 
            ...form, 
            length: parseFloat(form.length) || undefined, 
            piecesPerPacket: parseFloat(form.piecesPerPacket) || undefined,
            weight: parseFloat(form.weight) || undefined, 
            price: parseFloat(form.price) || undefined,
            reorderPoint: parseFloat(form.reorderPoint) || undefined
        });
        onClose();
    };

    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";

    return (
         <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">Edit Profile</h3>
                <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-4">
                    <input placeholder="SKU" name="sku" value={form.sku} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Name" name="name" value={form.name} onChange={handleChange} className={inputClass}/>
                    <select name="brand" value={form.brand} onChange={handleChange} className={inputClass}>{brands.map((b:string) => <option key={b} value={b}>{b}</option>)}</select>
                    <select name="uom" value={form.uom} onChange={handleChange} className={inputClass}><option value="Pcs">Pcs</option><option value="Mtrs">Meters</option><option value="Kgs">Kgs</option></select>
                    <input placeholder="Length (m)" type="number" name="length" value={form.length} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Pack" type="number" name="piecesPerPacket" value={form.piecesPerPacket} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Length Weight" type="number" name="weight" value={form.weight} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Price" type="number" name="price" value={form.price} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Reorder" type="number" name="reorderPoint" value={form.reorderPoint} onChange={handleChange} className={inputClass}/>
                    <div className="col-span-2 flex justify-end gap-2 mt-4">
                        <button type="button" onClick={onClose} className="px-4 py-2 border rounded dark:text-white">Cancel</button>
                        <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">Save Changes</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const store = useStore();
    const { 
        profiles, profileTransactions, brands, companySettings, customers,
        addProfile, updateProfile, deleteProfile, 
        addProfileTransaction, deleteProfileTransaction, updateProfileTransaction,
        addBrand, updateBrand, deleteBrand, resolveQuotation, updateCompanySettings,
        addCustomer, updateCustomer, deleteCustomer
    } = store;

    const [activeTab, setActiveTab] = useState<Tab>('Stock');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState<string>('All');
    const [planningTimeFilter, setPlanningTimeFilter] = useState<'1M' | '3M' | '6M' | 'ALL'>('3M');
    const [isDownloadMenuOpen, setIsDownloadMenuOpen] = useState(false);
    const downloadMenuRef = useRef<HTMLDivElement>(null);

    // --- State for Modals ---
    const [isAddProfileModalOpen, setIsAddProfileModalOpen] = useState(false);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [isManageBrandsModalOpen, setIsManageBrandsModalOpen] = useState(false);
    const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);

    const [transactionType, setTransactionType] = useState<'PRODUCTION' | 'DISPATCH' | 'QUOTATION' | 'SCRAP'>('PRODUCTION');

    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [editingTransaction, setEditingTransaction] = useState<ProfileTransaction | null>(null);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    const tabs: { id: Tab; label: string }[] = [
        { id: 'Stock', label: 'Profile Stock' },
        { id: 'Planning', label: 'Planning & Analysis' },
        { id: 'Production', label: 'Production (In)' },
        { id: 'Dispatch', label: 'Dispatch (Out)' },
        { id: 'Scrap', label: 'Scrap (Waste)' },
        { id: 'Quotations', label: 'Quotations' },
        { id: 'Profiles', label: 'Profile List' },
        { id: 'Customers', label: 'Customers' },
    ];

    const canManage = true; 

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
                setIsDownloadMenuOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    useEffect(() => {
        if (brandFilter !== 'All' && !brands.includes(brandFilter)) {
            setBrandFilter('All');
        }
    }, [brands, brandFilter]);

    // --- Derived Data ---
    const activeProfiles = useMemo(() => profiles.filter(p => !p.deletedAt), [profiles]);
    const activeTransactions = useMemo(() => profileTransactions.filter(t => !t.deletedAt), [profileTransactions]);
    const activeCustomers = useMemo(() => customers.filter(c => !c.deletedAt), [customers]);

    const brandFilteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return activeProfiles;
        return activeProfiles.filter(p => p.brand === brandFilter);
    }, [activeProfiles, brandFilter]);

    const getProfile = useCallback((id: string) => activeProfiles.find(p => p.id === id), [activeProfiles]);

    const stockData = useMemo(() => {
        return brandFilteredProfiles.map(p => {
            const production = activeTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = activeTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);

            // Advanced Scrap Calculation (Handle Kgs vs Pcs)
            const scrap = activeTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP').reduce((sum, t) => {
                if (t.uom === 'Kgs' && p.weight && p.weight > 0) {
                    return sum + (t.quantity / p.weight); // Convert Kg to Pcs
                }
                return sum + t.quantity;
            }, 0);

            const reserved = activeTransactions.filter(t => t.profileId === p.id && t.type === 'QUOTATION' && t.status === 'PENDING').reduce((sum, t) => sum + t.quantity, 0);
            const currentStock = production - dispatch - scrap; 
            return { ...p, currentStock: Math.floor(currentStock), reservedStock: reserved, availableStock: currentStock - reserved };
        }).filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [brandFilteredProfiles, activeTransactions, searchTerm]);

    const planningData = useMemo(() => {
        const now = new Date();
        let thresholdDate: Date | null = null;

        if (planningTimeFilter === '1M') { thresholdDate = new Date(); thresholdDate.setMonth(now.getMonth() - 1); } 
        else if (planningTimeFilter === '3M') { thresholdDate = new Date(); thresholdDate.setMonth(now.getMonth() - 3); } 
        else if (planningTimeFilter === '6M') { thresholdDate = new Date(); thresholdDate.setMonth(now.getMonth() - 6); }

        const periodDispatches = activeTransactions.filter(t => t.type === 'DISPATCH' && (!thresholdDate || new Date(t.date) >= thresholdDate));
        const totalPeriodVolume = periodDispatches.reduce((sum, t) => sum + t.quantity, 0);

        return brandFilteredProfiles.map(p => {
            const production = activeTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = activeTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const scrap = activeTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP').reduce((sum, t) => sum + t.quantity, 0);
            const currentStock = production - dispatch - scrap;

            const periodSales = periodDispatches.filter(t => t.profileId === p.id).reduce((sum, t) => sum + t.quantity, 0);
            const sharePercentage = totalPeriodVolume > 0 ? (periodSales / totalPeriodVolume) * 100 : 0;

            return { ...p, currentStock, periodSales, sharePercentage };
        })
        .filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase()))
        .sort((a, b) => b.sharePercentage - a.sharePercentage);
    }, [brandFilteredProfiles, activeTransactions, searchTerm, planningTimeFilter]);

    // Converted to Custom Hook to comply with rules of hooks
    const useFilteredTransactions = (type: 'PRODUCTION' | 'DISPATCH' | 'SCRAP' | 'QUOTATION' | 'RETURN') => {
        return useMemo(() => {
            // Filter by brand first
            const validProfileIds = new Set(brandFilteredProfiles.map(p => p.id));
            let data;

            if (type === 'PRODUCTION') { 
                 data = activeTransactions.filter(t => (t.type === 'PRODUCTION' || t.type === 'RETURN') && validProfileIds.has(t.profileId));
            } else {
                 data = activeTransactions.filter(t => t.type === type && validProfileIds.has(t.profileId));
            }

            if (searchTerm) {
                const lowerSearch = searchTerm.toLowerCase();
                data = data.filter(t => {
                    const profile = getProfile(t.profileId);
                    return t.refNo.toLowerCase().includes(lowerSearch) ||
                           (profile && profile.name.toLowerCase().includes(lowerSearch)) ||
                           (t.customer && t.customer.toLowerCase().includes(lowerSearch));
                });
            }

            return data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        }, [activeTransactions, brandFilteredProfiles, searchTerm, getProfile, type]);
    };

    const productionData = useFilteredTransactions('PRODUCTION');
    const dispatchData = useFilteredTransactions('DISPATCH');
    const scrapData = useFilteredTransactions('SCRAP');
    const quotationData = useFilteredTransactions('QUOTATION');

    const filteredProfiles = useMemo(() => brandFilteredProfiles.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [brandFilteredProfiles, searchTerm]);
    const filteredCustomers = useMemo(() => activeCustomers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())), [activeCustomers, searchTerm]);

    const handleOpenTransactionModal = (type: 'PRODUCTION' | 'DISPATCH' | 'QUOTATION' | 'SCRAP') => { setTransactionType(type); setIsTransactionModalOpen(true); };
    const handleQuotationAction = (id: string, action: 'CONFIRM' | 'CANCEL') => { resolveQuotation(id, action); if (action === 'CONFIRM') addToast('Quotation Confirmed & Dispatch created!', 'success'); else addToast('Quotation Cancelled', 'info'); };
    const getProfileName = (id: string) => getProfile(id)?.name || 'Unknown';
    const getProfileSpecs = (id: string) => { const p = getProfile(id); return p ? `${p.length || '-'}m / ${p.weight || '-'}kg` : '-'; };

    const getBrandBadge = (brand?: string) => {
        if (!brand) return <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">-</span>;
        const colors = ['bg-blue-100 text-blue-800', 'bg-purple-100 text-purple-800', 'bg-green-100 text-green-800', 'bg-indigo-100 text-indigo-800', 'bg-pink-100 text-pink-800'];
        return <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${colors[brand.length % colors.length]}`}>{brand}</span>;
    };

    const getActiveTableId = () => `profile-${activeTab.toLowerCase()}-table`;

    const handleExport = (type: 'PDF' | 'Excel') => {
        const tableId = getActiveTableId();
        const tableElement = document.getElementById(tableId)?.querySelector('table');
        if (!tableElement) {
            addToast('No data to export', 'error');
            return;
        }

        const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
        const headers = Array.from(clonedTable.querySelectorAll('thead th'));

        const actionIndices = headers
          .map((th, index) => (th.textContent || '').toLowerCase().indexOf('action') !== -1 || (th.textContent || '').toLowerCase().indexOf('edit') !== -1 || (th.textContent || '').toLowerCase().indexOf('confirm') !== -1 ? index : -1)
          .filter(index => index !== -1);

        actionIndices.sort((a, b) => b - a).forEach(index => {
            Array.from(clonedTable.rows).forEach(row => {
                if (row.cells[index]) row.deleteCell(index);
            });
        });

        if (type === 'Excel') {
            const wb = XLSX.utils.table_to_book(clonedTable, { sheet: "Sheet1" });
            XLSX.writeFile(wb, `Profile_${activeTab}.xlsx`);
        } else {
            const { jsPDF } = jspdf;
            const doc = new jsPDF({ orientation: 'landscape' });
            doc.autoTable({ html: clonedTable });
            doc.save(`Profile_${activeTab}.pdf`);
        }
        setIsDownloadMenuOpen(false);
    };

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                 <div className="flex items-center gap-2 flex-wrap">
                     {canManage && <button onClick={() => setIsSettingsModalOpen(true)} className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 px-3 py-2 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 border border-gray-300 dark:border-gray-600 shadow-sm flex items-center gap-2"><WarehouseIcon className="w-4 h-4" /><span className="hidden sm:inline text-sm font-medium">Settings</span></button>}
                    <div className="relative" ref={downloadMenuRef}>
                        <button onClick={() => setIsDownloadMenuOpen(p => !p)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2">Download<ChevronDownIcon className={`w-4 h-4 transition-transform ${isDownloadMenuOpen ? 'rotate-180' : ''}`} /></button>
                        {isDownloadMenuOpen && (<div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-20 ring-1 ring-black ring-opacity-5 border dark:border-gray-700"><button onClick={() => handleExport('PDF')} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">Download as PDF</button><button onClick={() => handleExport('Excel')} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">Download as Excel</button></div>)}
                    </div>
                    <div className="flex bg-gray-200 dark:bg-gray-700 rounded-lg p-1 mr-2 items-center">
                         {activeTab === 'Planning' && (<select value={planningTimeFilter} onChange={(e) => setPlanningTimeFilter(e.target.value as any)} className="mr-2 bg-white dark:bg-gray-600 border-none rounded-md text-xs font-medium px-2 py-1.5 focus:ring-0 cursor-pointer"><option value="1M">Last 1 Month</option><option value="3M">Last 3 Months</option><option value="6M">Last 6 Months</option><option value="ALL">All Time</option></select>)}
                        <button onClick={() => setBrandFilter('All')} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === 'All' ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>All</button>
                        {brands.map(brand => <button key={brand} onClick={() => setBrandFilter(brand)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === brand ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>{brand}</button>)}
                        {canManage && <button onClick={() => setIsManageBrandsModalOpen(true)} className="ml-1 px-2 py-1 text-gray-500" title="Manage Brands"><PencilIcon className="w-3 h-3" /></button>}
                    </div>
                    {activeTab === 'Production' && canManage && <button onClick={() => handleOpenTransactionModal('PRODUCTION')} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-green-700 shadow">+ Production</button>}
                    {activeTab === 'Dispatch' && canManage && <button onClick={() => handleOpenTransactionModal('DISPATCH')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow">- Dispatch</button>}
                    {activeTab === 'Scrap' && canManage && <button onClick={() => handleOpenTransactionModal('SCRAP')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow flex items-center gap-1"><TrashIcon className="w-4 h-4"/> Record Scrap</button>}
                    {activeTab === 'Quotations' && canManage && <button onClick={() => handleOpenTransactionModal('QUOTATION')} className="bg-orange-500 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-orange-600 shadow">+ Add Item</button>}
                    {activeTab === 'Profiles' && canManage && <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">+ Profile</button>}
                    {activeTab === 'Customers' && canManage && <button onClick={() => setIsCustomerModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2"><UserPlusIcon className="w-4 h-4"/> Add Customer</button>}
                 </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {tabs.map(tab => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}>{tab.label}</button>)}
                </nav>
                 <div className="mb-2 relative hidden sm:block"><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-1 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md w-64" /><SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" /></div>
            </div>

            <div className="animate-fade-in-right">
                {activeTab === 'Stock' && <div id="profile-stock-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><StockTable stockData={stockData} onEditProfile={setEditingProfile} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Planning' && <div id="profile-planning-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><PlanningTable planningData={planningData} getBrandBadge={getBrandBadge} planningTimeFilter={planningTimeFilter} /></div>}
                {activeTab === 'Production' && <div id="profile-production-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><TransactionTable transactions={productionData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} type="PRODUCTION" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Dispatch' && <div id="profile-dispatch-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><TransactionTable transactions={dispatchData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} type="DISPATCH" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Scrap' && <div id="profile-scrap-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><TransactionTable transactions={scrapData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} type="SCRAP" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Quotations' && <div id="profile-quotation-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><QuotationTable transactions={quotationData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onAction={handleQuotationAction} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Profiles' && <div id="profile-list-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><ProfileListTable profiles={filteredProfiles} onEdit={setEditingProfile} onDelete={deleteProfile} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Customers' && <div id="customer-list-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><CustomerTable customers={filteredCustomers} onEdit={setEditingCustomer} onDelete={deleteCustomer} /></div>}
            </div>

            <Portal><TransactionModal isOpen={isTransactionModalOpen} onClose={() => setIsTransactionModalOpen(false)} type={transactionType} profiles={brandFilteredProfiles} onAdd={addProfileTransaction} addToast={addToast} customers={activeCustomers} addCustomer={addCustomer}/></Portal>
            <Portal>{editingProfile && <EditProfileModal isOpen={!!editingProfile} onClose={() => setEditingProfile(null)} profile={editingProfile} onUpdate={updateProfile} brands={brands} addToast={addToast} />}</Portal>
            <Portal>{editingTransaction && <EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} onUpdate={updateProfileTransaction} addToast={addToast} />}</Portal>
            <Portal><AddProfileModal isOpen={isAddProfileModalOpen} onClose={() => setIsAddProfileModalOpen(false)} onAdd={addProfile} brands={brands} addToast={addToast} /></Portal>
            <Portal>
                <CustomerModal 
                    isOpen={isCustomerModalOpen || !!editingCustomer} 
                    onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} 
                    customer={editingCustomer} 
                    onSave={(c) => { 
                        if (editingCustomer) {
                            updateCustomer({ ...editingCustomer, ...c });
                        } else {
                            addCustomer(c);
                        }
                    }} 
                    addToast={addToast} 
                />
            </Portal>
            <Portal><ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
            <Portal><CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} addToast={addToast} /></Portal>
        </div>
    );
};

export default ProfileSection;

import React, { useState, useMemo, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import type { Die, ProductionPlan, Profile, ToastMessage, ProcessLogSheetData, TempParam } from '../types';
import { SearchIcon, PencilIcon, TrashIcon } from '../components/Icon';
import AddProfileModal from '../components/AddProfileModal'; // Import the reusable AddProfileModal

declare const jspdf: any;

interface DiesAndPlanningProps {
    dies: Die[];
    productionPlans: ProductionPlan[];
    profiles: Profile[];
    addToast: (message: string, type: ToastMessage['type']) => void;
    addDie: (die: Omit<Die, 'id' | 'createdAt' | 'brand'>) => void;
    updateDie: (die: Die) => void;
    deleteDie: (id: string) => void;
    addProductionPlan: (plan: Omit<ProductionPlan, 'id' | 'createdAt'>) => void;
    updateProductionPlan: (plan: ProductionPlan) => void;
    deleteProductionPlan: (id: string) => void;
    brands: string[];
    addBrand: (brand: string) => void;
    updateBrand: (oldB: string, newB: string) => void;
    deleteBrand: (brand: string) => void;
    addProfile: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile; // Pass addProfile for sub-modal
}

type Tab = 'dies' | 'planning';

const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};

// --- Helper Components defined OUTSIDE the main component to prevent re-creation and focus loss ---
// This is the critical fix for the "single character entry" bug.
const TempInput: React.FC<{ group: keyof ProcessLogSheetData, param: string, label: string, data: ProcessLogSheetData, onChange: (g: any, p: any, t: any, v: any) => void, focusInput: (id: string) => void, inputRefs: React.MutableRefObject<Record<string, HTMLInputElement | HTMLTextAreaElement>> }> = ({ group, param, label, data, onChange, focusInput, inputRefs }) => (
    <tr className="border-b dark:border-gray-700">
        <td className="px-2 py-1 font-semibold cursor-pointer hover:text-blue-500" onClick={() => focusInput(`log-${group}-${param}-act`)}>{label}</td>
        <td className="p-1">
            <input 
                id={`log-${group}-${param}-act`} 
                key={`log-${group}-${param}-act`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group}-${param}-act`] = el!)}
                type="text" 
                value={(data as any)[group]?.[param]?.act || ''} 
                onChange={(e) => onChange(group, param, 'act', e.target.value)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-center text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
        <td className="p-1">
            <input 
                id={`log-${group}-${param}-set`} 
                key={`log-${group}-${param}-set`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group}-${param}-set`] = el!)}
                type="text" 
                value={(data as any)[group]?.[param]?.set || ''} 
                onChange={(e) => onChange(group, param, 'set', e.target.value)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-center text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
    </tr>
);

const ParamInput: React.FC<{ group?: keyof ProcessLogSheetData, param: string, label: string, sNo: string, data: ProcessLogSheetData, onChange: (g: any, p: any, v: any) => void, onHeaderChange: (e:any) => void, focusInput: (id: string) => void, inputRefs: React.MutableRefObject<Record<string, HTMLInputElement | HTMLTextAreaElement>> }> = ({ group, param, label, sNo, data, onChange, onHeaderChange, focusInput, inputRefs }) => (
    <tr className="border-b dark:border-gray-700">
        <td className="px-2 py-1 text-center font-semibold">{sNo}</td>
        <td className="px-2 py-1 font-semibold cursor-pointer hover:text-blue-500" onClick={() => focusInput(`log-${group || ''}-${param}`)}>{label}</td>
        <td className="p-1" colSpan={2}>
            <input 
                id={`log-${group || ''}-${param}`} 
                key={`log-${group || ''}-${param}`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group || ''}-${param}`] = el!)}
                type="text" 
                value={group ? (data as any)[group]?.[param] || '' : (data as any)[param] || ''} 
                onChange={(e) => group ? onChange(group, param, e.target.value) : onHeaderChange({ target: { name: param, value: e.target.value } } as any)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
    </tr>
);

interface ProcessLogSheetModalProps {
    isOpen: boolean;
    onClose: () => void;
    die: Die | null;
    onSave: (die: Die) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
}

const ProcessLogSheetModal: React.FC<ProcessLogSheetModalProps> = ({ isOpen, onClose, die, onSave, addToast }) => {
    // IMPORTANT: Use deep copy to initialize state to prevent mutation of original die object before saving
    const [formData, setFormData] = useState<ProcessLogSheetData>({});
    const inputRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement>>({});

    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => {
        if (isOpen && die) {
            setFormData(die.processLog || {});
            setPosition({ x: 0, y: 0 }); // Reset position on open
        }
    }, [isOpen, die]);

    useEffect(() => {
        const handleEsc = (event: KeyboardEvent) => {
            if (event.key === 'Escape') onClose();
        };
        if (isOpen) window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    const handleMouseDownHeader = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        setIsDragging(true);
        dragStart.current = { x: e.clientX, y: e.clientY };
        startPos.current = { ...position };
    };

    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                e.preventDefault();
                setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) });
            }
        };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) {
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }
        return () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [isDragging]);

    if (!isOpen || !die) return null;

    const handleTempParamChange = (group: keyof ProcessLogSheetData, param: string, type: 'act' | 'set', value: string) => {
        setFormData(prev => ({
            ...prev,
            [group]: {
                ...(prev[group] || {}),
                [param]: {
                    ...((prev[group] as any)?.[param] || {}), // Cast to any to access dynamic property
                    [type]: value
                }
            }
        }));
    };

    const handleParamChange = (group: keyof ProcessLogSheetData, param: string, value: string) => {
        setFormData(prev => ({
            ...prev,
            [group]: {
                ...(prev[group] || {}),
                [param]: value
            }
        }));
    };

    // For direct header fields (not grouped)
    const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const focusInput = useCallback((id: string) => {
        inputRefs.current[id]?.focus();
    }, []);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave({ ...die, processLog: formData });
        addToast('Process Log Saved!', 'success');
        onClose();
    };

    const inputStyle = "w-full bg-gray-50 dark:bg-gray-700 text-sm p-1 rounded border dark:border-gray-600 focus:outline-none focus:ring-1 focus:ring-blue-500";
    const modalStyle = { transform: `translate(${position.x}px, ${position.y}px)` };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={modalStyle} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={handleMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]">
                    <h2 className="text-xl font-bold flex items-center gap-2">Process Log Sheet: {die.dieNo}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button>
                </div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        {/* Header Info */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div><label className="block text-xs font-medium mb-1">Date</label><input type="date" name="date" value={formData.date || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Machine No.</label><input type="text" name="machineNo" value={formData.machineNo || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Tool ID</label><input type="text" name="toolId" value={formData.toolId || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Tool Man</label><input type="text" name="toolMan" value={formData.toolMan || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Profile Speed</label><input type="text" name="profileSpeed" value={formData.profileSpeed || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Output Per Hour</label><input type="text" name="outputPerHour" value={formData.outputPerHour || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Profile Colour</label><input type="text" name="profileColour" value={formData.profileColour || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                        </div>

                        {/* Temperatures */}
                        <div className="border rounded-md dark:border-gray-700">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="bg-gray-100 dark:bg-gray-700"><th className="px-2 py-1 text-left font-semibold" colSpan={1}>Barrel/Tooling Temp</th><th className="px-2 py-1 text-center font-semibold">ACT</th><th className="px-2 py-1 text-center font-semibold">SET</th></tr>
                                </thead>
                                <tbody>
                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={3} className="px-2 py-1 font-semibold">Barrel Zones</td></tr>
                                    <TempInput group="barrelTemp" param="bz1" label="BZ-1" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz2" label="BZ-2" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz3" label="BZ-3" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz4" label="BZ-4" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz5" label="BZ-5" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz6" label="BZ-6" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="ch1" label="CH-1" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="ch2" label="CH-2" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={3} className="px-2 py-1 font-semibold">Tooling Zones</td></tr>
                                    <TempInput group="toolingTemp" param="dz1" label="DZ-1" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz2" label="DZ-2" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz3" label="DZ-3" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz4" label="DZ-4" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                </tbody>
                            </table>
                        </div>

                        {/* Other Parameters */}
                        <div className="border rounded-md dark:border-gray-700">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="bg-gray-100 dark:bg-gray-700"><th className="px-2 py-1 text-center font-semibold" colSpan={2}>S.No.</th><th className="px-2 py-1 text-left font-semibold" colSpan={2}>Parameters</th></tr>
                                </thead>
                                <tbody>
                                    <ParamInput sNo="1" param="extruderRpm" label="Extruder RPM" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="2" param="screwTorque" label="Screw Torque" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="3" param="feederBlend" label="Feeder Blend" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="4" param="haulOffRpm" label="Haul Off RPM" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="5" param="meltTemp" label="Melt Temp" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="6" param="meltPressure" label="Melt Pressure" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="7" param="degasing" label="Degasing" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />

                                    <tr className="bg-gray-5 dark:bg-gray-700/50"><td colSpan={4} className="px-2 py-1 font-semibold">Calibrator</td></tr>
                                    <ParamInput sNo="8" group="calibrator" param="vacuum1" label="Vacuum 1" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="9" group="calibrator" param="vacuum2" label="Vacuum 2" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="10" group="calibrator" param="vacuum3" label="Vacuum 3" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="11" group="calibrator" param="vacuum4" label="Vacuum 4" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="12" group="calibrator" param="vacuum5" label="Vacuum 5" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="13" group="calibrator" param="waterTemp" label="Water Temp" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="14" group="calibrator" param="waterPressure" label="Water Pressure" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />

                                    <tr className="bg-gray-5 dark:bg-gray-700/50"><td colSpan={4} className="px-2 py-1 font-semibold">Cooling Tank</td></tr>
                                    <ParamInput sNo="15" group="coolingTank" param="vacuumLR1" label="Vacuum LR 1" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="16" group="coolingTank" param="vacuumLR2" label="Vacuum LR 2" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="17" group="coolingTank" param="vacuumLR3" label="Vacuum LR 3" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />

                                    <ParamInput sNo="18" param="haulOffPressure" label="Haul Off Pressure" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="19" param="counter" label="Counter" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="20" param="cutterClamping" label="Cutter Clamping" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="21" param="timeOfTripping" label="Time of Tripping" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                </tbody>
                            </table>
                        </div>

                        {/* Signatures & Remarks */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><label className="block text-xs font-medium mb-1">Signature Operator</label><input type="text" name="signatureOperator" value={formData.signatureOperator || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Signature Engineer</label><input type="text" name="signatureEngineer" value={formData.signatureEngineer || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                        </div>
