import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import type { ToastMessage, ConfirmationState, Page, User } from './types';
import { useStore } from './store/useStore';
import { SearchIcon, UserIcon, ChevronDownIcon, SpinnerIcon, CloudCheckIcon, CloudOffIcon, CloudAlertIcon } from './components/Icon';
import Dashboard from './pages/Dashboard';
import RMSection from './pages/RMSection';
import ProfileSection from './pages/ProfileSection';
import DiesAndPlanning from './pages/DiesAndPlanning';
import ImportExcel from './pages/ImportExcel';
import Trash from './pages/Trash';
import LoginPage from './pages/Login';
import { ToastContainer, ConfirmModal } from './components/Notifications';
import History from './pages/History';
import Storage from './pages/Storage';
import type { Item, InflowTransaction, ConsumptionTransaction, Formula, ReportCorrection } from './types';

// Use global XLSX from CDN
declare const XLSX: any;

const ALL_NAV_ITEMS: { name: Page, shortcut: string }[] = [
    { name: 'Dashboard', shortcut: '1' },
    { name: 'RM Section', shortcut: '2' },
    { name: 'Profile Section', shortcut: '6' },
    { name: 'Dies & Planning', shortcut: '7' },
    { name: 'History', shortcut: '3' },
    { name: 'Storage', shortcut: '4' },
    { name: 'Import', shortcut: '5' },
    { name: 'Trash', shortcut: '0' },
];

function debounce<F extends (...args: any[]) => any>(func: F, waitFor: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  const debounced = (...args: Parameters<F>) => {
    if (timeout !== null) {
      clearTimeout(timeout);
    }
    timeout = setTimeout(() => func(...args), waitFor);
  };
  return debounced;
}

export default function App() {
  const store = useStore();
  const { currentUser, login, logout, resetData } = store;
  const setLastSync = useStore(state => state.setLastSync);

  const [currentPage, setCurrentPage] = useState<Page>('Dashboard');

  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'pending' | 'error'>('synced');
  const [confirmation, setConfirmation] = useState<ConfirmationState>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });
  const [remountKey, setRemountKey] = useState(0);

  const [authLoading, setAuthLoading] = useState(true);

  // --- NOTIFICATION & CONFIRMATION SYSTEM ---
  const addToast = useCallback((message: string, type: ToastMessage['type'] = 'info') => {
    setToasts(prev => [...prev, { id: Date.now(), message, type }]);
  }, []);

  const confirmAction = useCallback((title: string, message: string, onConfirm: () => void) => {
    setConfirmation({
        isOpen: true,
        title,
        message,
        onConfirm: () => {
            onConfirm();
            setConfirmation(prev => ({ ...prev, isOpen: false }));
        }
    });
  }, []);

  // --- NAVIGATION ---
  const navigate = useCallback((page: Page) => {
    setCurrentPage(page);
    setIsMobileMenuOpen(false);
  }, []);

  // --- BACKEND AUTH & API ---

  useEffect(() => {
    const checkUserSession = async () => {
        try {
            const response = await fetch('/api/user/me');
            if (response.ok) {
                const user = await response.json();
                login(user);
            }
        } catch (error) {
            console.warn('User not logged in or API not available.');
        } finally {
            setAuthLoading(false);
        }
    };
    checkUserSession();
  }, [login]);

  const handleGoogleLogin = () => {
    // Redirect to backend OAuth endpoint
    window.location.href = '/api/auth/google';
  };

  const handleLogout = async () => {
      try {
        await fetch('/api/auth/logout', { method: 'POST' });
      } catch (error) {
        console.error('Logout failed:', error);
      } finally {
        logout();
        setIsUserMenuOpen(false);
        addToast('You have been signed out.', 'info');
      }
  };

  const handleGuestLogin = () => {
    login({
        id: 'guest_user',
        name: 'Offline User',
        isGuest: true,
        role: 'ADMIN', // Assign admin role for full local access
    });
    addToast('Working in offline mode. Your data is saved automatically.', 'info');
  };

  const saveToCloud = useCallback(async () => {
    if (!currentUser || currentUser.isGuest || !currentUser.isDriveConnected) {
        addToast('Not connected to Google Drive.', 'error');
        return;
    }
    addToast('Syncing data to Google Drive...', 'info');
    setSyncStatus('syncing');

    const stateToExport = useStore.getState();
    const data: Record<string, any> = {};
    Object.entries(stateToExport).forEach(([key, value]) => {
        if (!['currentUser', 'login', 'logout', 'resetData', 'loadData'].includes(key) && typeof value !== 'function') {
            data[key] = value;
        }
    });
    const fileContent = JSON.stringify(data, null, 2);

    try {
        const response = await fetch('/api/drive/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: fileContent
        });

        if (!response.ok) {
            const errorData = await response.json();
            throw new Error(errorData.message || `Server responded with ${response.status}`);
        }

        const syncTime = new Date().toISOString();
        setLastSync(syncTime);
        addToast('Data successfully saved to Google Drive.', 'success');
        setSyncStatus('synced');
    } catch (error: any) {
        console.error('Error saving to drive', error);
        addToast(`Save failed: ${error.message || 'Unknown error'}`, 'error');
        setSyncStatus('error');
    }
}, [currentUser, addToast, setLastSync]);


const loadFromCloud = useCallback(async (confirm = true) => {
    if (!currentUser || currentUser.isGuest || !currentUser.isDriveConnected) {
        addToast('Not connected to Google Drive.', 'error');
        return;
    }

    const loadAction = async () => {
        addToast('Loading data from Google Drive...', 'info');
        setSyncStatus('syncing');
        try {
            const response = await fetch('/api/drive/load');
            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.message || `Server responded with ${response.status}`);
            }
            const data = await response.json();
            if (Object.keys(data).length === 0) {
                 addToast('No data found in Google Drive. Saving current state as new file.', 'info');
                 await saveToCloud();
                 return;
            }

            store.loadData(data);
            const syncTime = new Date().toISOString();
            setLastSync(syncTime);
            addToast('Data loaded successfully from Google Drive.', 'success');
            setSyncStatus('synced');
            setRemountKey(prev => prev + 1);
        } catch (error: any) {
            console.error('Error loading from drive', error);
            addToast(`Load failed: ${error.message || 'Unknown error'}`, 'error');
            setSyncStatus('error');
        }
    };

    if (confirm) {
        confirmAction(
            'Load from Google Drive?',
            'This will replace all current local data with the version from your Google Drive. Unsaved local changes will be lost.',
            loadAction
        );
    } else {
        await loadAction();
    }
}, [currentUser, addToast, confirmAction, store, setLastSync, saveToCloud]);

  // --- AUTO SYNC ---
  const autoSaveToCloud = useCallback(async () => {
    if (!currentUser || currentUser.isGuest || !currentUser.isDriveConnected) return;
    setSyncStatus('syncing');

    const stateToExport = useStore.getState();
    const data: Record<string, any> = {};
    Object.entries(stateToExport).forEach(([key, value]) => {
        if (!['currentUser', 'login', 'logout', 'resetData', 'loadData'].includes(key) && typeof value !== 'function') {
            data[key] = value;
        }
    });

    try {
        const response = await fetch('/api/drive/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data, null, 2)
        });
        if (!response.ok) throw new Error('Auto-sync failed');

        setLastSync(new Date().toISOString());
        setSyncStatus('synced');
    } catch (error: any) {
        console.error('Error auto-saving to drive', error);
        // Don't toast on auto-save error to avoid annoyance, just set status
        setSyncStatus('error');
    }
  }, [currentUser, setLastSync]);


  const debouncedAutoSave = useMemo(() => debounce(autoSaveToCloud, 5000), [autoSaveToCloud]);

  useEffect(() => {
      if (syncStatus !== 'pending' && currentUser && !currentUser.isGuest && currentUser.isDriveConnected) {
        debouncedAutoSave();
      }
  }, [store.items, store.inflowTransactions, store.consumptionTransactions, store.formulas, store.reportCorrections, store.profiles, store.profileTransactions, store.brands, store.dies, store.productionPlans, debouncedAutoSave, currentUser, syncStatus]);


  // --- EXPORT / IMPORT ---
  const exportData = useCallback(async () => {
        const state = useStore.getState();
        const dataToExport = {
            items: state.items,
            inflow: state.inflowTransactions,
            consumption: state.consumptionTransactions,
            formulas: state.formulas,
            reportCorrections: state.reportCorrections,
            profiles: state.profiles,
            profileTransactions: state.profileTransactions,
            brands: state.brands
        };

        const wb = XLSX.utils.book_new();

        const addToSheet = (name: string, data: any[]) => {
            if (data.length) {
                const ws = XLSX.utils.json_to_sheet(data);
                XLSX.utils.book_append_sheet(wb, ws, name);
            }
        };

        addToSheet("Raw Materials", dataToExport.items);
        addToSheet("Inflow Log", dataToExport.inflow);
        addToSheet("Consumption Log", dataToExport.consumption);
        addToSheet("Formulas", dataToExport.formulas.map(f => ({...f, ingredients: JSON.stringify(f.ingredients)})));
        addToSheet("Reports", dataToExport.reportCorrections);
        addToSheet("Profiles", dataToExport.profiles);
        addToSheet("Profile Log", dataToExport.profileTransactions);

        const date = new Date().toISOString().split('T')[0];
        const filename = `ERP_Backup_${date}.xlsx`;

        try {
            if ((window as any).showSaveFilePicker) {
                 const handle = await (window as any).showSaveFilePicker({
                    suggestedName: filename,
                    types: [{
                        description: 'Excel File',
                        accept: {'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx']},
                    }],
                });
                const writable = await handle.createWritable();
                const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
                await writable.write(wbout);
                await writable.close();
                addToast('Backup saved successfully.', 'success');
                return;
            }
        } catch (err: any) {
             if (err.name !== 'AbortError') {
                 console.warn('File System Access API failed, falling back to download.', err);
             } else {
                 return; // User cancelled the save dialog
             }
        }

        XLSX.writeFile(wb, filename);
        addToast('Backup downloaded.', 'success');
  }, [addToast]);

  const exportDataJSON = () => {
      const state = useStore.getState();
       const data = {};
       Object.entries(state).forEach(([key, value]) => {
        if (!['currentUser', 'login', 'logout', 'resetData', 'loadData'].includes(key) && typeof value !== 'function') {
            // @ts-ignore
            data[key] = value;
        }
       });
      const dataStr = JSON.stringify(data, null, 2);
      const blob = new Blob([dataStr], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `erp_system_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      addToast('System backup (JSON) downloaded.', 'success');
  };

  const importData = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);
          store.loadData(data);
          addToast('Data imported successfully.', 'success');
          setRemountKey(prev => prev + 1);
        } catch (error) {
          console.error("Import error:", error);
          addToast('Failed to import data. Invalid JSON file.', 'error');
        }
      };
      reader.readAsText(file);
    };
    input.click();
  };

  // --- KEYBOARD SHORTCUTS ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.altKey && !e.ctrlKey && !e.shiftKey && !e.metaKey) {
            const item = ALL_NAV_ITEMS.find(i => i.shortcut === e.key);
            if (item) {
                e.preventDefault();
                navigate(item.name);
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [navigate]);

  // --- STATS CALCULATION (Memoized for performance & correctness) ---
  const dashboardData = useMemo(() => {
    const activeItems = store.items.filter(i => !i.deletedAt);
    const activeInflow = store.inflowTransactions.filter(t => !t.deletedAt);
    const activeConsumption = store.consumptionTransactions.filter(t => !t.deletedAt);
    const activeFormulas = store.formulas.filter(f => !f.deletedAt);
    const activeItemsMap = new Map(activeItems.map(i => [i.id, i]));

    const stockLevels = activeItems.reduce((acc, item) => {
        acc[item.id] = 0;
        return acc;
    }, {} as Record<string, number>);

    activeInflow.forEach(t => {
        if (stockLevels[t.itemId] !== undefined && t.txnDate && !isNaN(new Date(t.txnDate).getTime())) {
            stockLevels[t.itemId] += t.quantity;
        }
    });
    activeConsumption.forEach(t => {
        if (stockLevels[t.itemId] !== undefined && t.txnDate && !isNaN(new Date(t.txnDate).getTime())) {
            stockLevels[t.itemId] -= t.quantity;
        }
    });

    const totalItems = activeItems.length;

    const lowStockItems = activeItems
      .map(item => ({ ...item, currentStock: stockLevels[item.id] || 0 }))
      .filter(item => item.currentStock < item.reorderPoint);

    const totalInventoryValue = activeItems
      .reduce((sum, item) => sum + ((stockLevels[item.id] || 0) * ((item as Item).costPrice || 0)), 0); // FIX: Added type assertion for item.costPrice

    const inventoryValueDistribution = activeItems
       .filter(i => (stockLevels[i.id] || 0) > 0)
       .map(item => ({ name: item.name, value: (stockLevels[item.id] || 0) * ((item as Item).costPrice || 0) })) // FIX: Added type assertion for item.costPrice
       .sort((a, b) => b.value - a.value);

    const monthlyOperations = (() => {
       const data: any = {};
       const process = (date: string, val: number, type: 'inflow' | 'consumption') => {
           if (!date || isNaN(new Date(date).getTime())) return;
           const month = date.substring(0, 7);
           if (!data[month]) data[month] = { inflow: 0, consumption: 0 };
           data[month][type] += val;
       };
       activeInflow.forEach(t => process(t.txnDate, t.totalCost, 'inflow'));

       activeConsumption.forEach(t => {
           const item = activeItemsMap.get(t.itemId);
           if(item) process(t.txnDate, t.quantity * ((item as Item).costPrice || 0), 'consumption');
       });

       for (let i = 5; i >= 0; i--) {
           const d = new Date();
           d.setMonth(d.getMonth() - i);
           const m = d.toISOString().substring(0, 7);
           if (!data[m]) data[m] = { inflow: 0, consumption: 0 };
       }
       return Object.keys(data).sort().reduce((obj: any, key) => { obj[key] = data[key]; return obj; }, {});
    })();

    let totalBatches = 0;
    if (activeFormulas.length > 0) {
        const f = activeFormulas[0];
        const batches = f.ingredients.map(ing => {
             const stock = stockLevels[ing.itemId] || 0;
             return ing.quantity > 0 ? Math.floor(stock / ing.quantity) : Infinity;
        });
        totalBatches = Math.min(...batches);
        if(totalBatches === Infinity) totalBatches = 0;
    }

    return {
        stockLevels,
        stats: { totalItems, lowStockItems, totalInventoryValue, inventoryValueDistribution, monthlyOperations, totalBatches }
    };

  }, [store.items, store.inflowTransactions, store.consumptionTransactions, store.formulas]);

  if (authLoading) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-100 dark:bg-gray-900">
              <SpinnerIcon className="w-10 h-10 animate-spin text-blue-600" />
          </div>
      );
  }

  if (!currentUser) {
    return (
        <>
            <LoginPage onGoogleLogin={handleGoogleLogin} onGuestLogin={handleGuestLogin} />
            <ToastContainer toasts={toasts} dismissToast={(id) => setToasts(prev => prev.filter(t => t.id !== id))} />
        </>
    );
  }

  return (
    <div key={remountKey} className="min-h-screen bg-gray-100 dark:bg-gray-900 transition-colors duration-200 font-sans text-gray-900 dark:text-gray-100">

      {/* Navigation Bar */}
      <nav className="bg-[#2D3E50] text-white shadow-md sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            {/* Mobile menu button */}
            <div className="flex items-center sm:hidden">
                 <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="inline-flex items-center justify-center p-2 rounded-md hover:bg-gray-700 focus:outline-none">
                    <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        {isMobileMenuOpen ? (
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        ) : (
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                        )}
                    </svg>
                </button>
            </div>

            {/* Desktop Nav Links */}
            <div className="hidden sm:flex items-center space-x-4">
               <div className="flex-shrink-0 font-bold text-xl tracking-wider mr-8 flex items-center gap-2">
                  <span>📦</span> Inventory Hub
               </div>
               {ALL_NAV_ITEMS.map(item => (
                   <button
                        key={item.name}
                        onClick={() => navigate(item.name)}
                        className={`px-3 py-2 rounded-md text-sm font-medium transition-colors duration-150 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-white ${currentPage === item.name ? 'bg-gray-900 text-white' : 'text-gray-300 hover:bg-gray-700 hover:text-white'}`}
                   >
                       {item.name}
                   </button>
               ))}
            </div>

            {/* User Dropdown & Status */}
            <div className="flex items-center space-x-4">
                 {/* Sync Status Icon */}
                 <div className="hidden md:flex items-center" title={syncStatus === 'synced' ? 'Saved to Drive' : syncStatus === 'syncing' ? 'Syncing...' : 'Not Synced'}>
                    {syncStatus === 'syncing' && <SpinnerIcon className="w-5 h-5 text-blue-400 animate-spin" />}
                    {syncStatus === 'synced' && <CloudCheckIcon className="w-5 h-5 text-green-400" />}
                    {syncStatus === 'error' && <CloudAlertIcon className="w-5 h-5 text-red-400" />}
                 </div>

                 <div className="relative ml-3">
                    <div>
                        <button onClick={() => setIsUserMenuOpen(!isUserMenuOpen)} className="max-w-xs bg-gray-800 rounded-full flex items-center text-sm focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-white" id="user-menu-button" aria-expanded="false" aria-haspopup="true">
                            <span className="sr-only">Open user menu</span>
                            {currentUser.picture ? (
                                <img className="h-8 w-8 rounded-full" src={currentUser.picture} alt="" />
                            ) : (
                                <div className="h-8 w-8 rounded-full bg-indigo-500 flex items-center justify-center text-white font-bold">
                                    {currentUser.name ? currentUser.name.charAt(0).toUpperCase() : <UserIcon className="h-5 w-5"/>}
                                </div>
                            )}
                        </button>
                    </div>
                    {isUserMenuOpen && (
                        <div className="origin-top-right absolute right-0 mt-2 w-48 rounded-md shadow-lg py-1 bg-white dark:bg-gray-700 ring-1 ring-black ring-opacity-5 focus:outline-none z-50">
                            <div className="px-4 py-2 border-b dark:border-gray-600">
                                <p className="text-sm text-gray-900 dark:text-white font-medium">{currentUser.name}</p>
                                <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{currentUser.email}</p>
                            </div>
                            <button onClick={saveToCloud} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-600">
                                Sync Now
                            </button>
                            <button onClick={() => loadFromCloud(true)} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-600">
                                Reload from Cloud
                            </button>
                            <button onClick={handleLogout} className="block w-full text-left px-4 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-gray-100 dark:hover:bg-gray-600">
                                Sign out
                            </button>
                        </div>
                    )}
                 </div>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
            <div className="sm:hidden bg-gray-800">
                <div className="px-2 pt-2 pb-3 space-y-1">
                    {ALL_NAV_ITEMS.map(item => (
                        <button
                            key={item.name}
                            onClick={() => navigate(item.name)}
                            className={`block w-full text-left px-3 py-2 rounded-md text-base font-medium ${currentPage === item.name ? 'bg-gray-900 text-white' : 'text-gray-300 hover:bg-gray-700 hover:text-white'}`}
                        >
                            {item.name}
                        </button>
                    ))}
                </div>
            </div>
        )}
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <div className="px-4 py-4 sm:px-0">
            <div className="animate-fade-in-right">
                {currentPage === 'Dashboard' && (
                    <Dashboard 
                        items={store.items.filter(i => !i.deletedAt)} 
                        stockLevels={dashboardData.stockLevels}
                        stats={dashboardData.stats}
                        formulas={store.formulas.filter(f => !f.deletedAt)}
                        addToast={addToast}
                    />
                )}
                {currentPage === 'RM Section' && (
                    <RMSection
                        items={store.items.filter(i => !i.deletedAt)}
                        stockLevels={dashboardData.stockLevels}
                        inflowTransactions={store.inflowTransactions.filter(t => !t.deletedAt)}
                        consumptionTransactions={store.consumptionTransactions.filter(t => !t.deletedAt)}
                        formulas={store.formulas.filter(f => !f.deletedAt)}
                        addToast={addToast}
                        totalBatches={dashboardData.stats.totalBatches}

                        addItem={store.addItem}
                        updateItem={store.updateItem}
                        deleteItem={store.deleteItem}

                        addInflowTransaction={store.addInflowTransaction}
                        createItemAndInflow={store.createItemAndInflow}
                        updateInflowTransaction={store.updateInflowTransaction}
                        deleteInflowTransaction={store.deleteInflowTransaction}

                        addMultipleConsumptionTransactions={store.addMultipleConsumptionTransactions}
                        updateConsumptionTransaction={store.updateConsumptionTransaction}
                        deleteConsumptionTransaction={store.deleteConsumptionTransaction}

                        addFormula={store.addFormula}
                        updateFormula={store.updateFormula}
                        deleteFormula={store.deleteFormula}
                    />
                )}
                {currentPage === 'Profile Section' && (
                    <ProfileSection
                        addToast={addToast}
                    />
                )}
                {currentPage === 'Dies & Planning' && (
                    <DiesAndPlanning
                        dies={store.dies.filter(d => !d.deletedAt)}
                        productionPlans={store.productionPlans.filter(p => !p.deletedAt)}
                        profiles={store.profiles.filter(p => !p.deletedAt)}
                        items={store.items.filter(i => !i.deletedAt)} // Passed for stock calculations
                        stockLevels={dashboardData.stockLevels} // Passed for stock calculations
                        addToast={addToast}
                        addDie={store.addDie}
                        updateDie={store.updateDie}
                        deleteDie={store.deleteDie}
                        addProductionPlan={store.addProductionPlan}
                        updateProductionPlan={store.updateProductionPlan}
                        deleteProductionPlan={store.deleteProductionPlan}
                        brands={store.brands}
                        addBrand={store.addBrand}
                        updateBrand={store.updateBrand}
                        deleteBrand={store.deleteBrand}
                        addProfile={store.addProfile}
                    />
                )}
                {currentPage === 'Import' && (
                    <ImportExcel 
                        addMultipleInflowTransactions={store.addMultipleInflowTransactions}
                        addToast={addToast}
                    />
                )}
                {currentPage === 'History' && (
                    <History 
                        items={store.items.filter(i => !i.deletedAt)}
                        inflowTransactions={store.inflowTransactions.filter(t => !t.deletedAt)}
                        consumptionTransactions={store.consumptionTransactions.filter(t => !t.deletedAt)}
                        reportCorrections={store.reportCorrections}
                        profiles={store.profiles.filter(p => !p.deletedAt)}
                        profileTransactions={store.profileTransactions.filter(t => !t.deletedAt)}
                        addOrUpdateReportCorrection={store.addOrUpdateReportCorrection}
                        brands={store.brands}
                    />
                )}
                {currentPage === 'Storage' && (
                     <Storage
                        syncToDrive={saveToCloud}
                        loadFromDrive={() => loadFromCloud(true)}
                        logout={handleLogout}
                        currentUser={currentUser}
                        exportData={exportData}
                        exportDataJSON={exportDataJSON}
                        importData={importData}
                        resetData={() => confirmAction('Reset All Data', 'Are you sure? This will wipe all local data.', store.resetData)}
                        connectToDrive={handleGoogleLogin}
                     />
                )}
                 {currentPage === 'Trash' && (
                    <Trash
                        items={store.items}
                        inflowTransactions={store.inflowTransactions}
                        consumptionTransactions={store.consumptionTransactions}
                        formulas={store.formulas}
                        profiles={store.profiles}
                        profileTransactions={store.profileTransactions}
                        dies={store.dies}
                        productionPlans={store.productionPlans}

                        restoreItem={store.restoreItem}
                        permanentlyDeleteItem={(id) => confirmAction('Delete Item Forever?', 'This cannot be undone.', () => store.permanentlyDeleteItem(id))}
                        restoreTransaction={store.restoreTransaction}
                        permanentlyDeleteTransaction={(id, type) => confirmAction('Delete Transaction Forever?', 'This cannot be undone.', () => store.permanentlyDeleteTransaction(id, type))}
                        restoreFormula={store.restoreFormula}
                        permanentlyDeleteFormula={(id) => confirmAction('Delete Formula Forever?', 'This cannot be undone.', () => store.permanentlyDeleteFormula(id))}

                        restoreProfile={store.restoreProfile}
                        permanentlyDeleteProfile={(id) => confirmAction('Delete Profile Forever?', 'This cannot be undone.', () => store.permanentlyDeleteProfile(id))}
                        restoreProfileTransaction={store.restoreProfileTransaction}
                        permanentlyDeleteProfileTransaction={(id) => confirmAction('Delete Log Forever?', 'This cannot be undone.', () => store.permanentlyDeleteProfileTransaction(id))}

                        restoreDie={store.restoreDie}
                        permanentlyDeleteDie={(id) => confirmAction('Delete Die Forever?', 'This cannot be undone.', () => store.permanentlyDeleteDie(id))}
                        restoreProductionPlan={store.restoreProductionPlan}
                        permanentlyDeleteProductionPlan={(id) => confirmAction('Delete Plan Forever?', 'This cannot be undone.', () => store.permanentlyDeleteProductionPlan(id))}
                    />
                )}
            </div>
        </div>
      </main>

      <ToastContainer toasts={toasts} dismissToast={(id) => setToasts(prev => prev.filter(t => t.id !== id))} />

      <ConfirmModal
        isOpen={confirmation.isOpen}
        title={confirmation.title}
        message={confirmation.message}
        onConfirm={confirmation.onConfirm}
        onCancel={() => setConfirmation(prev => ({ ...prev, isOpen: false }))}
      />
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import type { Die, ProductionPlan, Profile, ToastMessage, ProcessLogSheetData, TempParam, Item } from '../types';
import { SearchIcon, PencilIcon, TrashIcon } from '../components/Icon';
import AddProfileModal from '../components/AddProfileModal'; // Import the reusable AddProfileModal

declare const jspdf: any;

interface DiesAndPlanningProps {
    dies: Die[];
    productionPlans: ProductionPlan[];
    profiles: Profile[];
    items: Item[]; // New prop for Raw Materials
    stockLevels: Record<string, number>; // New prop for Inventory Levels
    addToast: (message: string, type: ToastMessage['type']) => void;
    addDie: (die: Omit<Die, 'id' | 'createdAt' | 'brand'>) => void;
    updateDie: (die: Die) => void;
    deleteDie: (id: string) => void;
    addProductionPlan: (plan: Omit<ProductionPlan, 'id' | 'createdAt'>) => void;
    updateProductionPlan: (plan: ProductionPlan) => void;
    deleteProductionPlan: (id: string) => void;
    brands: string[];
    addBrand: (brand: string) => void;
    updateBrand: (oldB: string, newB: string) => void;
    deleteBrand: (brand: string) => void;
    addProfile: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile; // Pass addProfile for sub-modal
}

type Tab = 'dies' | 'planning';

const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};

// --- Helper Components defined OUTSIDE the main component to prevent re-creation and focus loss ---
// Optimized with React.memo and explicit props to prevent re-renders of the whole form on single field change.

interface TempInputProps {
    group: keyof ProcessLogSheetData;
    param: string;
    label: string;
    actValue: string;
    setValue: string;
    onChange: (group: keyof ProcessLogSheetData, param: string, type: 'act' | 'set', value: string) => void;
    focusInput: (id: string) => void;
    inputRefs: React.MutableRefObject<Record<string, HTMLInputElement | HTMLTextAreaElement>>;
}

const TempInput: React.FC<TempInputProps> = React.memo(({ group, param, label, actValue, setValue, onChange, focusInput, inputRefs }) => (
    <tr className="border-b dark:border-gray-700">
        <td className="px-2 py-1 font-semibold cursor-pointer hover:text-blue-500" onClick={() => focusInput(`log-${group}-${param}-act`)}>{label}</td>
        <td className="p-1">
            <input 
                id={`log-${group}-${param}-act`} 
                key={`log-${group}-${param}-act`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group}-${param}-act`] = el!)}
                type="text" 
                value={actValue} 
                onChange={(e) => onChange(group, param, 'act', e.target.value)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-center text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
        <td className="p-1">
            <input 
                id={`log-${group}-${param}-set`} 
                key={`log-${group}-${param}-set`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group}-${param}-set`] = el!)}
                type="text" 
                value={setValue} 
                onChange={(e) => onChange(group, param, 'set', e.target.value)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-center text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
    </tr>
));

interface ParamInputProps {
    group?: keyof ProcessLogSheetData;
    param: string;
    label: string;
    sNo: string;
    value: string;
    onChange: (group: keyof ProcessLogSheetData, param: string, value: string) => void;
    onHeaderChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
    focusInput: (id: string) => void;
    inputRefs: React.MutableRefObject<Record<string, HTMLInputElement | HTMLTextAreaElement>>;
}

const ParamInput: React.FC<ParamInputProps> = React.memo(({ group, param, label, sNo, value, onChange, onHeaderChange, focusInput, inputRefs }) => (
    <tr className="border-b dark:border-gray-700">
        <td className="px-2 py-1 text-center font-semibold">{sNo}</td>
        <td className="px-2 py-1 font-semibold cursor-pointer hover:text-blue-500" onClick={() => focusInput(`log-${group || ''}-${param}`)}>{label}</td>
        <td className="p-1" colSpan={2}>
            <input 
                id={`log-${group || ''}-${param}`} 
                key={`log-${group || ''}-${param}`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group || ''}-${param}`] = el!)}
                type="text" 
                value={value} 
                onChange={(e) => group ? onChange(group, param, e.target.value) : onHeaderChange(e)} 
                name={!group ? param : undefined}
                className="w-full bg-gray-50 dark:bg-gray-700 text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
    </tr>
));

interface ProcessLogSheetModalProps {
    isOpen: boolean;
    onClose: () => void;
    die: Die | null;
    onSave: (die: Die) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
}

const ProcessLogSheetModal: React.FC<ProcessLogSheetModalProps> = ({ isOpen, onClose, die, onSave, addToast }) => {
    // IMPORTANT: Use deep copy to initialize state to prevent mutation of original die object before saving
    const [formData, setFormData] = useState<ProcessLogSheetData>({});
    const inputRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement>>({});

    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => {
        if (isOpen && die) {
            setFormData(die.processLog || {});
            setPosition({ x: 0, y: 0 }); // Reset position on open
        }
    }, [isOpen, die]);

    useEffect(() => {
        const handleEsc = (event: KeyboardEvent) => {
            if (event.key === 'Escape') onClose();
        };
        if (isOpen) window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    const handleMouseDownHeader = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        setIsDragging(true);
        dragStart.current = { x: e.clientX, y: e.clientY };
        startPos.current = { ...position };
    };

    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                e.preventDefault();
                setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) });
            }
        };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) {
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }
        return () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [isDragging]);

    // Stable callbacks for input handlers
    const handleTempParamChange = useCallback((group: keyof ProcessLogSheetData, param: string, type: 'act' | 'set', value: string) => {
        setFormData(prev => ({
            ...prev,
            [group]: {
                ...(prev[group] || {}),
                [param]: {
                    ...((prev[group] as any)?.[param] || {}), // Cast to any to access dynamic property
                    [type]: value
                }
            }
        }));
    }, []);

    const handleParamChange = useCallback((group: keyof ProcessLogSheetData, param: string, value: string) => {
        setFormData(prev => ({
            ...prev,
            [group]: {
                ...(prev[group] || {}),
                [param]: value
            }
        }));
    }, []);

    // For direct header fields (not grouped)
    const handleHeaderChange = useCallback((e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    }, []);

    const focusInput = useCallback((id: string) => {
        inputRefs.current[id]?.focus();
    }, []);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if(die) {
            onSave({ ...die, processLog: formData });
            addToast('Process Log Saved!', 'success');
            onClose();
        }
    };

    if (!isOpen || !die) return null;

    const inputStyle = "w-full bg-gray-50 dark:bg-gray-700 text-sm p-1 rounded border dark:border-gray-600 focus:outline-none focus:ring-1 focus:ring-blue-500";
    const modalStyle = { transform: `translate(${position.x}px, ${position.y}px)` };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={modalStyle} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={handleMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]">
                    <h2 className="text-xl font-bold flex items-center gap-2">Process Log Sheet: {die.dieNo}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button>
                </div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        {/* Header Info */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div><label className="block text-xs font-medium mb-1">Date</label><input type="date" name="date" value={formData.date || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Machine No.</label><input type="text" name="machineNo" value={formData.machineNo || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Tool ID</label><input type="text" name="toolId" value={formData.toolId || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Tool Man</label><input type="text" name="toolMan" value={formData.toolMan || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Profile Speed</label><input type="text" name="profileSpeed" value={formData.profileSpeed || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Output Per Hour</label><input type="text" name="outputPerHour" value={formData.outputPerHour || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Profile Colour</label><input type="text" name="profileColour" value={formData.profileColour || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                        </div>

                        {/* Temperatures */}
                        <div className="border rounded-md dark:border-gray-700">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="bg-gray-100 dark:bg-gray-700"><th className="px-2 py-1 text-left font-semibold" colSpan={1}>Barrel/Tooling Temp</th><th className="px-2 py-1 text-center font-semibold">ACT</th><th className="px-2 py-1 text-center font-semibold">SET</th></tr>
                                </thead>
                                <tbody>
                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={3} className="px-2 py-1 font-semibold">Barrel Zones</td></tr>
                                    <TempInput group="barrelTemp" param="bz1" label="BZ-1" actValue={formData.barrelTemp?.bz1?.act || ''} setValue={formData.barrelTemp?.bz1?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz2" label="BZ-2" actValue={formData.barrelTemp?.bz2?.act || ''} setValue={formData.barrelTemp?.bz2?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz3" label="BZ-3" actValue={formData.barrelTemp?.bz3?.act || ''} setValue={formData.barrelTemp?.bz3?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz4" label="BZ-4" actValue={formData.barrelTemp?.bz4?.act || ''} setValue={formData.barrelTemp?.bz4?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz5" label="BZ-5" actValue={formData.barrelTemp?.bz5?.act || ''} setValue={formData.barrelTemp?.bz5?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz6" label="BZ-6" actValue={formData.barrelTemp?.bz6?.act || ''} setValue={formData.barrelTemp?.bz6?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="ch1" label="CH-1" actValue={formData.barrelTemp?.ch1?.act || ''} setValue={formData.barrelTemp?.ch1?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="ch2" label="CH-2" actValue={formData.barrelTemp?.ch2?.act || ''} setValue={formData.barrelTemp?.ch2?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={3} className="px-2 py-1 font-semibold">Tooling Zones</td></tr>
                                    <TempInput group="toolingTemp" param="dz1" label="DZ-1" actValue={formData.toolingTemp?.dz1?.act || ''} setValue={formData.toolingTemp?.dz1?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz2" label="DZ-2" actValue={formData.toolingTemp?.dz2?.act || ''} setValue={formData.toolingTemp?.dz2?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz3" label="DZ-3" actValue={formData.toolingTemp?.dz3?.act || ''} setValue={formData.toolingTemp?.dz3?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz4" label="DZ-4" actValue={formData.toolingTemp?.dz4?.act || ''} setValue={formData.toolingTemp?.dz4?.set || ''} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                </tbody>
                            </table>
                        </div>

                        {/* Other Parameters */}
                        <div className="border rounded-md dark:border-gray-700">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="bg-gray-100 dark:bg-gray-700"><th className="px-2 py-1 text-center font-semibold" colSpan={2}>S.No.</th><th className="px-2 py-1 text-left font-semibold" colSpan={2}>Parameters</th></tr>
                                </thead>
                                <tbody>
