                        <p className="text-xs text-gray-500 mt-2 text-center">Select multiple dies to run simultaneously on this machine.</p>
                    </div>

                    <div className="col-span-2 flex justify-end gap-2 mt-2"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save Plan</button></div>
                </form>
            </div>
        </div>
    );
};

const ManageBrandsModal: React.FC<any> = ({ isOpen, onClose, brands, addBrand, deleteBrand, addToast }) => {
    const [newB, setNewB] = useState('');
    if (!isOpen) return null;
    const handleAdd = () => { if (newB.trim() && !brands.includes(newB.trim())) { addBrand(newB.trim()); setNewB(''); } else { addToast('Brand already exists or is empty.', 'error'); } };
