// ... ProfileDashboard (reused)
const ProfileDashboard: React.FC<{ 
    profiles: Profile[], 
    transactions: ProfileTransaction[], 
    stockData: any[] 
}> = ({ profiles, transactions, stockData }) => {
    const chartRef1 = useRef<HTMLCanvasElement>(null);
    const chartRef2 = useRef<HTMLCanvasElement>(null);
    const chartInstance1 = useRef<any>(null);
    const chartInstance2 = useRef<any>(null);

    const [isListOpen, setIsListOpen] = useState(false);
    const [isLowStockOpen, setIsLowStockOpen] = useState(false);
    const [isValueOpen, setIsValueOpen] = useState(false);

    const totalProfiles = profiles.length;
    const lowStockItems = useMemo(() => stockData.filter(p => p.currentStock < (p.reorderPoint || 0)), [stockData]);
    const lowStockCount = lowStockItems.length;
    const totalStockValue = stockData.reduce((acc, p) => acc + (p.currentStock * (p.price || 0)), 0);
    const currentMonth = new Date().toISOString().slice(0, 7);
    const currentMonthDispatch = transactions
        .filter(t => t.type === 'DISPATCH' && t.date.startsWith(currentMonth))
        .reduce((sum, t) => sum + t.quantity, 0);

    useEffect(() => {
        if (typeof Chart === 'undefined') return;
        const isDarkMode = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        const textColor = isDarkMode ? '#E5E7EB' : '#374151';
        const gridColor = isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)';

        const topValueProfiles = [...stockData].sort((a, b) => (b.currentStock * b.price) - (a.currentStock * a.price)).slice(0, 5);

        if (chartRef1.current) {
            if (chartInstance1.current) chartInstance1.current.destroy();
            const ctx1 = chartRef1.current.getContext('2d');
            if (ctx1) {
                chartInstance1.current = new Chart(ctx1, {
                    type: 'doughnut',
                    data: {
                        labels: topValueProfiles.map(p => p.name),
                        datasets: [{
                            data: topValueProfiles.map(p => (p.currentStock * p.price)),
                            backgroundColor: ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'],
                            borderColor: isDarkMode ? '#1F2937' : '#FFFFFF',
                            borderWidth: 2
                        }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'right', labels: { color: textColor } }, title: { display: false } } }
                });
            }
        }

        const last6Months = [];
        for (let i = 5; i >= 0; i--) {
            const d = new Date();
            d.setMonth(d.getMonth() - i);
            last6Months.push(d.toISOString().slice(0, 7));
        }
        const labels = last6Months.map(m => new Date(m + '-01').toLocaleString('default', { month: 'short' }));
        const productionData = last6Months.map(month => transactions.filter(t => (t.type === 'PRODUCTION' || t.type === 'RETURN') && t.date.startsWith(month)).reduce((sum, t) => sum + t.quantity, 0));
        const dispatchData = last6Months.map(month => transactions.filter(t => t.type === 'DISPATCH' && t.date.startsWith(month)).reduce((sum, t) => sum + t.quantity, 0));

        if (chartRef2.current) {
            if (chartInstance2.current) chartInstance2.current.destroy();
            const ctx2 = chartRef2.current.getContext('2d');
            if (ctx2) {
                chartInstance2.current = new Chart(ctx2, {
                    type: 'bar',
                    data: {
                        labels: labels,
                        datasets: [
                            { label: 'Production', data: productionData, backgroundColor: '#10B981' },
                            { label: 'Dispatch', data: dispatchData, backgroundColor: '#EF4444' }
                        ]
                    },
                    options: { responsive: true, maintainAspectRatio: false, scales: { y: { ticks: { color: textColor }, grid: { color: gridColor } }, x: { ticks: { color: textColor }, grid: { color: gridColor } } }, plugins: { legend: { position: 'top', labels: { color: textColor } } } }
                });
            }
        }
        return () => { if(chartInstance1.current) chartInstance1.current.destroy(); if(chartInstance2.current) chartInstance2.current.destroy(); };
    }, [stockData, transactions]);

    return (
        <div className="space-y-6 animate-fade-in-right">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <button onClick={() => setIsListOpen(true)} className="text-left focus:outline-none hover:scale-105 transition-transform duration-200">
                    <Card className="h-full">
                        <div className="flex items-center justify-between">
                            <div><p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Profiles</p><p className="text-3xl font-bold text-gray-900 dark:text-white mt-1">{totalProfiles}</p></div>
                            <div className="p-3 bg-blue-100 dark:bg-blue-900/30 rounded-full"><WarehouseIcon className="w-6 h-6 text-blue-600 dark:text-blue-400" /></div>
                        </div>
                    </Card>
                </button>
                <button onClick={() => setIsLowStockOpen(true)} className="text-left focus:outline-none hover:scale-105 transition-transform duration-200">
                    <Card className="h-full border-l-4 border-l-transparent hover:border-l-red-500">
                        <div className="flex items-center justify-between">
                            <div><p className="text-sm font-medium text-gray-500 dark:text-gray-400">Low Stock Alerts</p><p className={`text-3xl font-bold mt-1 ${lowStockCount > 0 ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}>{lowStockCount}</p></div>
                            <div className={`p-3 rounded-full ${lowStockCount > 0 ? 'bg-red-100 dark:bg-red-900/30' : 'bg-gray-100 dark:bg-gray-700'}`}><WarningIcon className={`w-6 h-6 ${lowStockCount > 0 ? 'text-red-500' : 'text-gray-400'}`} /></div>
                        </div>
                    </Card>
                </button>
                <button onClick={() => setIsValueOpen(true)} className="text-left focus:outline-none hover:scale-105 transition-transform duration-200">
                    <Card className="h-full">
                        <div className="flex items-center justify-between">
                            <div><p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Stock Value</p><p className="text-3xl font-bold text-green-600 dark:text-green-400 mt-1">{totalStockValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })}</p></div>
                            <div className="p-3 bg-green-100 dark:bg-green-900/30 rounded-full"><SparklesIcon className="w-6 h-6 text-green-600 dark:text-green-400" /></div>
                        </div>
                    </Card>
                </button>
                <Card className="h-full">
                    <div className="flex items-center justify-between">
                        <div><p className="text-sm font-medium text-gray-500 dark:text-gray-400">Dispatch (This Month)</p><p className="text-3xl font-bold text-purple-600 dark:text-purple-400 mt-1">{currentMonthDispatch.toLocaleString()}</p></div>
                        <div className="p-3 bg-purple-100 dark:bg-purple-900/30 rounded-full"><UserIcon className="w-6 h-6 text-purple-600 dark:text-purple-400" /></div>
                    </div>
                </Card>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <Card className="h-96"><h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Production vs Dispatch (6 Months)</h3><div className="h-72 w-full"><canvas ref={chartRef2}></canvas></div></Card>
                <Card className="h-96"><h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Top 5 Profiles by Stock Value</h3><div className="h-72 w-full"><canvas ref={chartRef1}></canvas></div></Card>
            </div>
            <Portal><DashboardListModal isOpen={isListOpen} onClose={() => setIsListOpen(false)} items={stockData} title="All Profiles" type="list" /></Portal>
            <Portal><DashboardListModal isOpen={isLowStockOpen} onClose={() => setIsLowStockOpen(false)} items={lowStockItems} title="Low Stock Profiles" type="lowstock" /></Portal>
            <Portal><DashboardListModal isOpen={isValueOpen} onClose={() => setIsValueOpen(false)} items={stockData} title="Profile Stock Value" type="value" /></Portal>
        </div>
    );
};

