// ... Main ProfileSection ...
const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const { profiles, profileTransactions, customers, brands, addProfile, updateProfile, deleteProfile, addProfileTransaction, updateProfileTransaction, deleteProfileTransaction, resolveQuotation, addCustomer, updateCustomer, deleteCustomer } = useStore();

    const [activeTab, setActiveTab] = useState<Tab>('Dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState('All');

    // Modals
    const [isAddProfileOpen, setIsAddProfileOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);

    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    // Calculated Stock
    const stockData = useMemo(() => {
        return profiles.map(p => {
            const production = profileTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = profileTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const scrap = profileTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP').reduce((sum, t) => {
                if (t.uom === 'Kgs' && p.weight && p.weight > 0) return sum + (t.quantity / p.weight);
                return sum + t.quantity;
            }, 0);
            return { ...p, currentStock: production - dispatch - scrap };
        });
    }, [profiles, profileTransactions]);

    const filteredStock = useMemo(() => {
        let data = stockData;
        if (brandFilter !== 'All') data = data.filter(p => p.brand === brandFilter);
        if (searchTerm) data = data.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase()));
        return data;
    }, [stockData, brandFilter, searchTerm]);

    const filteredCustomers = useMemo(() => {
        if (!searchTerm) return customers;
        return customers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [customers, searchTerm]);

    const tabs: {id: Tab, label: string}[] = [
        {id: 'Dashboard', label: 'Dashboard'},
        {id: 'Stock', label: 'Stock List'},
        {id: 'Production', label: 'Production'},
        {id: 'Dispatch', label: 'Dispatch'},
        {id: 'Scrap', label: 'Scrap'},
        {id: 'Quotations', label: 'Quotations'},
        {id: 'Customers', label: 'Customers'},
    ];

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                <div className="flex gap-2">
                    {activeTab === 'Stock' && <button onClick={() => setIsAddProfileOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded shadow hover:bg-blue-700">+ Add Profile</button>}
                    {activeTab === 'Customers' && <button onClick={() => setIsCustomerModalOpen(true)} className="bg-green-600 text-white px-4 py-2 rounded shadow hover:bg-green-700">+ Add Customer</button>}
                </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end overflow-x-auto">
                <nav className="-mb-px flex space-x-4">
                    {tabs.map(tab => (
                        <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}>
                            {tab.label}
                        </button>
                    ))}
                </nav>
                {(activeTab === 'Stock' || activeTab === 'Dashboard') && (
                    <div className="flex items-center gap-2 mb-2">
                        <select value={brandFilter} onChange={e => setBrandFilter(e.target.value)} className="border rounded p-1 text-sm dark:bg-gray-700 dark:border-gray-600">
                            <option value="All">All Brands</option>
                            {brands.map(b => <option key={b} value={b}>{b}</option>)}
                        </select>
                        <input placeholder="Search..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="border rounded p-1 text-sm dark:bg-gray-700 dark:border-gray-600 w-40" />
                    </div>
                )}
