                                    <td className="px-6 py-4 text-right space-x-2"><button onClick={() => { setEditingCustomer(c); setIsCustomerModalOpen(true); }} className="text-blue-600 hover:underline"><PencilIcon className="w-4 h-4 inline"/></button><button onClick={() => deleteCustomer(c.id)} className="text-red-600 hover:underline"><TrashIcon className="w-4 h-4 inline"/></button></td>
                                </tr>
                            ))}
