            )}

            {/* Placeholder for other tabs that usually require separate complex components */}
            {(activeTab === 'Production' || activeTab === 'Dispatch' || activeTab === 'Scrap' || activeTab === 'Quotations') && (
                <div className="p-8 text-center bg-gray-50 dark:bg-gray-800 rounded-lg border border-dashed border-gray-300 dark:border-gray-700">
                    <p className="text-gray-500">Transaction management for <strong>{activeTab}</strong> is available in the Dies & Planning section or specialized modals. (Simplified for this view).</p>
                </div>
            )}

            <Portal>
                <AddProfileModal isOpen={isAddProfileOpen} onClose={() => { setIsAddProfileOpen(false); setEditingProfile(null); }} onAdd={(p) => { if(editingProfile) updateProfile({...editingProfile, ...p}); else addProfile(p); }} brands={brands} addToast={addToast} />
            </Portal>
            <Portal>
                <CustomerModal isOpen={isCustomerModalOpen} onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} customer={editingCustomer} onSave={(c) => { if(editingCustomer) updateCustomer({...editingCustomer, ...c}); else addCustomer(c); }} addToast={addToast} />
            </Portal>
        </div>
    );
};

