                <div className="p-6 overflow-y-auto flex-1 min-h-0">
                    <form onSubmit={handleSubmit} className="space-y-3">
                        <div><label className="block text-xs font-medium dark:text-gray-300">Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required /></div>
                        <div><label className="block text-xs font-medium dark:text-gray-300">Profile</label><select value={form.profileId} onChange={e => setForm({...form, profileId: e.target.value})} className={inputClass}>{profiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select>{selectedProfile && <div className="mt-2 p-2 bg-gray-5 dark:bg-gray-700/50 rounded border dark:border-gray-600 text-xs space-y-1"><div className="flex justify-between"><span>Specs:</span> <span className="font-medium">{selectedProfile.length}m / {selectedProfile.weight}kg</span></div><div className="flex justify-between"><span>Est. Total Weight:</span> <span className="font-bold text-blue-600 dark:text-blue-400">{totalWeight.toLocaleString()} kg</span></div></div>}</div>
                        <div><label className="block text-xs font-medium dark:text-gray-300">Ref No.</label><input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} required /></div>
                        <div className="flex gap-2">
                            <div className="flex-1"><label className="block text-xs font-medium dark:text-gray-300">Quantity</label><input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} required /></div>
                            {type === 'SCRAP' && (
                                <div className="w-24">
                                    <label className="block text-xs font-medium dark:text-gray-300">Unit</label>
                                    <select value={form.uom} onChange={e => setForm({...form, uom: e.target.value})} className={inputClass}>
                                        <option value="Pcs">Pcs</option>
                                        <option value="Kgs">Kgs</option>
                                    </select>
                                </div>
                            )}
                        </div>
                        {type === 'SCRAP' && <div className="grid grid-cols-2 gap-2"><div><label className="block text-xs font-medium dark:text-gray-300">Machine No.</label><input value={form.machine} onChange={e => setForm({...form, machine: e.target.value})} className={inputClass} /></div><div><label className="block text-xs font-medium dark:text-gray-300">Die No.</label><input value={form.die} onChange={e => setForm({...form, die: e.target.value})} className={inputClass} /></div></div>}
                        {(type === 'QUOTATION' || type === 'DISPATCH') && <><div className="relative"><label className="block text-xs font-medium dark:text-gray-300">Customer Name (Search)</label><input value={form.customer} onChange={e => { setForm({...form, customer: e.target.value}); setCustomerSearch(e.target.value); setShowSuggestions(true); }} onFocus={() => setShowSuggestions(true)} className={inputClass} required placeholder="Type to search..." />{showSuggestions && customerSearch && filteredCustomers.length > 0 && (<div className="absolute z-20 w-full bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">{filteredCustomers.map((c:any) => (<div key={c.id} onClick={() => selectCustomer(c)} className="px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-600 cursor-pointer text-sm"><div className="font-medium">{c.name}</div><div className="text-xs text-gray-500">{c.phone}</div></div>))}</div>)}</div><div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded border dark:border-gray-700 space-y-2"><div className="flex justify-between items-center"><p className="text-xs font-bold text-gray-500">Customer Details</p><button type="button" onClick={handleSaveCustomer} className="text-xs text-blue-600 hover:underline flex items-center gap-1"><UserPlusIcon className="w-3 h-3"/> Save Customer</button></div><input placeholder="Address" value={form.customerAddress} onChange={e => setForm({...form, customerAddress: e.target.value})} className={inputClass}/><div className="grid grid-cols-2 gap-2"><input placeholder="GSTIN" value={form.customerGST} onChange={e => setForm({...form, customerGST: e.target.value})} className={inputClass}/><input placeholder="Mobile" value={form.customerPhone} onChange={e => setForm({...form, customerPhone: e.target.value})} className={inputClass}/></div></div></>}
                        <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save</button></div>
                    </form>
                </div>
            </div>
        </div>
    );
};

