const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const store = useStore();
    const { profiles, profileTransactions, brands, addProfile, updateProfile, deleteProfile, customers, addCustomer, updateCustomer } = store;

    const [activeTab, setActiveTab] = useState<Tab>('Dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState('All');

    const [isAddProfileModalOpen, setIsAddProfileModalOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [isAddCustomerModalOpen, setIsAddCustomerModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    const tabs: { id: Tab; label: string }[] = [
        { id: 'Dashboard', label: 'Dashboard' },
        { id: 'Stock', label: 'All Profiles' },
        { id: 'Customers', label: 'Customers' },
    ];

    const stockData = useMemo(() => {
        let filtered = profiles.filter(p => !p.deletedAt);
        if (brandFilter !== 'All') filtered = filtered.filter(p => p.brand === brandFilter);
        if (searchTerm && activeTab !== 'Customers') {
            const lower = searchTerm.toLowerCase();
            filtered = filtered.filter(p => p.name.toLowerCase().includes(lower) || p.sku.toLowerCase().includes(lower));
        }

        return filtered.map(p => {
            const production = profileTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN') && !t.deletedAt).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = profileTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH' && !t.deletedAt).reduce((sum, t) => sum + t.quantity, 0);
            const scrap = profileTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP' && !t.deletedAt).reduce((sum, t) => {
                // If scrap is in Kgs, convert to Pcs based on profile weight
                if (t.uom === 'Kgs' && p.weight && p.weight > 0) {
                    return sum + (t.quantity / p.weight);
                }
                return sum + t.quantity;
            }, 0);
            return {
                ...p,
                currentStock: production - dispatch - scrap
            };
        });
    }, [profiles, profileTransactions, brandFilter, searchTerm, activeTab]);

    const filteredCustomers = useMemo(() => {
        let filtered = customers.filter(c => !c.deletedAt);
        if (searchTerm && activeTab === 'Customers') {
            const lower = searchTerm.toLowerCase();
            filtered = filtered.filter(c => c.name.toLowerCase().includes(lower) || (c.phone && c.phone.includes(lower)));
        }
        return filtered;
    }, [customers, searchTerm, activeTab]);

    const getBrandBadge = (brand: string) => {
        if (brand === 'Scraft') return "bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300";
        if (brand === 'Smart') return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300";
        return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300";
    };

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                <div className="flex gap-2">
                    {activeTab === 'Stock' && (
                        <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2">
                            <CloudUploadIcon className="w-4 h-4"/> Add Profile
                        </button>
                    )}
                    {activeTab === 'Customers' && (
                        <button onClick={() => setIsAddCustomerModalOpen(true)} className="bg-purple-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-purple-700 shadow flex items-center gap-2">
                            <UserPlusIcon className="w-4 h-4"/> Add Customer
                        </button>
                    )}
                </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex flex-col sm:flex-row justify-between items-end gap-4">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {tabs.map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none transition-colors duration-200`}
                        >
                            {tab.label}
                        </button>
                    ))}
                </nav>

                <div className="flex items-center gap-4 mb-2">
                    {activeTab === 'Stock' && (
                        <div className="flex bg-gray-200 dark:bg-gray-700 rounded-lg p-1 items-center">
                            <button onClick={() => setBrandFilter('All')} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === 'All' ? 'bg-white dark:bg-gray-600 shadow' : 'text-gray-500 dark:text-gray-400'}`}>All</button>
                            {brands.map(brand => (
                                <button key={brand} onClick={() => setBrandFilter(brand)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === brand ? 'bg-white dark:bg-gray-600 shadow' : 'text-gray-500 dark:text-gray-400'}`}>
                                    {brand}
                                </button>
                            ))}
                        </div>
                    )}
                    {(activeTab === 'Stock' || activeTab === 'Customers') && (
                        <div className="relative">
                            <input 
                                type="text" 
                                placeholder="Search..." 
                                value={searchTerm} 
                                onChange={(e) => setSearchTerm(e.target.value)} 
                                className="pl-8 pr-4 py-1.5 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md focus:ring-blue-500 focus:border-blue-500 w-64 dark:text-white" 
                            />
                            <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        </div>
                    )}
                </div>
            </div>

            <div className="animate-fade-in-right">
                {activeTab === 'Dashboard' && <ProfileDashboard profiles={profiles} transactions={profileTransactions} stockData={stockData} />}

                {activeTab === 'Stock' && (
                    <StockTable stockData={stockData} onEditProfile={setEditingProfile} getBrandBadge={getBrandBadge} />
                )}

                {activeTab === 'Customers' && (
                    <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr>
                                    <th className="px-6 py-3">Customer Name</th>
                                    <th className="px-6 py-3">Phone</th>
                                    <th className="px-6 py-3">GSTIN</th>
                                    <th className="px-6 py-3">Address</th>
                                    <th className="px-6 py-3 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredCustomers.map(c => (
                                    <tr key={c.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700">
                                        <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{c.name}</td>
                                        <td className="px-6 py-4">{c.phone || '-'}</td>
                                        <td className="px-6 py-4">{c.gstin || '-'}</td>
                                        <td className="px-6 py-4 truncate max-w-xs">{c.address || '-'}</td>
                                        <td className="px-6 py-4 text-right">
                                            <button onClick={() => setEditingCustomer(c)} className="text-blue-600 hover:text-blue-900 dark:text-blue-400 mr-3">Edit</button>
                                        </td>
                                    </tr>
                                ))}
                                {filteredCustomers.length === 0 && <tr><td colSpan={5} className="text-center py-4">No customers found.</td></tr>}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Modals */}
            <Portal>
                <AddProfileModal 
                    isOpen={isAddProfileModalOpen || !!editingProfile} 
                    onClose={() => { setIsAddProfileModalOpen(false); setEditingProfile(null); }} 
                    onAdd={(p) => { 
                        if(editingProfile) { updateProfile({...editingProfile, ...p}); addToast('Profile updated!', 'success'); }
                        else { addProfile(p); addToast('Profile added!', 'success'); }
                    }}
                    brands={brands}
                    addToast={addToast}
                />
            </Portal>
            <Portal>
                <CustomerModal
                    isOpen={isAddCustomerModalOpen || !!editingCustomer}
                    onClose={() => { setIsAddCustomerModalOpen(false); setEditingCustomer(null); }}
                    customer={editingCustomer}
                    onSave={(c) => {
                        if(editingCustomer) { updateCustomer({...editingCustomer, ...c}); addToast('Customer updated!', 'success'); }
                        else { addCustomer(c); addToast('Customer added!', 'success'); }
                    }}
                    addToast={addToast}
                />
            </Portal>
        </div>
    );
};

