const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const store = useStore();
    const { profiles, profileTransactions, brands, addProfile, updateProfile, deleteProfile, customers, addCustomer, updateCustomer, addProfileTransaction } = store;

    const [activeTab, setActiveTab] = useState<Tab>('Dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState('All');

    const [isAddProfileModalOpen, setIsAddProfileModalOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [isAddCustomerModalOpen, setIsAddCustomerModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [transactionType, setTransactionType] = useState<'PRODUCTION' | 'DISPATCH' | 'QUOTATION' | 'SCRAP'>('PRODUCTION');

    const tabs: { id: Tab; label: string }[] = [
        { id: 'Dashboard', label: 'Dashboard' },
        { id: 'Stock', label: 'All Profiles' },
        { id: 'Customers', label: 'Customers' },
    ];

    // Calculated Stock for all active profiles (for Modal)
    const profilesWithStock = useMemo(() => {
        let filtered = profiles.filter(p => !p.deletedAt);
        if (brandFilter !== 'All') filtered = filtered.filter(p => p.brand === brandFilter);

        return filtered.map(p => {
            const production = profileTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN') && !t.deletedAt).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = profileTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH' && !t.deletedAt).reduce((sum, t) => sum + t.quantity, 0);
            const scrap = profileTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP' && !t.deletedAt).reduce((sum, t) => {
                if (t.uom === 'Kgs' && p.weight && p.weight > 0) return sum + (t.quantity / p.weight);
                return sum + t.quantity;
            }, 0);
            return {
                ...p,
                currentStock: production - dispatch - scrap
            };
        });
    }, [profiles, profileTransactions, brandFilter]);

    // Filtered Stock for Table (Search + Stock)
    const stockData = useMemo(() => {
        let data = profilesWithStock;
        if (searchTerm && activeTab !== 'Customers') {
            const lower = searchTerm.toLowerCase();
            data = data.filter(p => p.name.toLowerCase().includes(lower) || p.sku.toLowerCase().includes(lower));
        }
        return data;
    }, [profilesWithStock, searchTerm, activeTab]);

    const filteredCustomers = useMemo(() => {
        let filtered = customers.filter(c => !c.deletedAt);
        if (searchTerm && activeTab === 'Customers') {
            const lower = searchTerm.toLowerCase();
            filtered = filtered.filter(c => c.name.toLowerCase().includes(lower) || (c.phone && c.phone.includes(lower)));
        }
        return filtered;
    }, [customers, searchTerm, activeTab]);

    const handleOpenTransactionModal = (type: 'PRODUCTION' | 'DISPATCH' | 'QUOTATION' | 'SCRAP') => {
        setTransactionType(type);
        setIsTransactionModalOpen(true);
    };

    const getBrandBadge = (brand: string) => {
        if (brand === 'Scraft') return "bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300";
        if (brand === 'Smart') return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300";
        return "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300";
