                    <button onClick={() => handleOpenTransactionModal('DISPATCH')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow">- Dispatch</button>
                    {activeTab === 'Stock' && (
                        <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2">
                            <CloudUploadIcon className="w-4 h-4"/> Add Profile
                        </button>
                    )}
                    {activeTab === 'Customers' && (
                        <button onClick={() => setIsAddCustomerModalOpen(true)} className="bg-purple-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-purple-700 shadow flex items-center gap-2">
