import React, { useState, useEffect, useRef } from 'react';
import type { Profile, ToastMessage } from '../types';

interface AddProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile; // Modified to return the created profile
  brands: string[];
  addToast: (message: string, type: ToastMessage['type']) => void;
}

const AddProfileModal: React.FC<AddProfileModalProps> = ({ isOpen, onClose, onAdd, brands, addToast }) => {
    const getInitialState = () => ({ sku: '', name: '', brand: brands[0]||'', uom: 'Pcs', length: '', piecesPerPacket: '', weight: '', price: '', reorderPoint: '' });
    const [form, setForm] = useState(getInitialState());

    useEffect(() => {
        if (isOpen) {
            setForm(getInitialState());
            // Ensure brand is set if brands array becomes available after modal mount
            if (!form.brand && brands.length > 0) {
                setForm(prev => ({ ...prev, brand: brands[0] }));
            }
        }
    }, [isOpen, brands]);

    useEffect(() => {
        const handleEsc = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
        if (isOpen) window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    if(!isOpen) return null;

    const handleSubmit = (e: React.FormEvent) => { 
        e.preventDefault(); 
        const newProfile = {
            ...form, 
            length: parseFloat(form.length) || undefined, 
            piecesPerPacket: parseFloat(form.piecesPerPacket) || undefined,
            weight: parseFloat(form.weight) || undefined, 
            price: parseFloat(form.price) || undefined, 
            reorderPoint: parseFloat(form.reorderPoint) || undefined
        };

        if(!newProfile.sku || !newProfile.name) {
            addToast('SKU and Name are required.', 'error');
            return;
        }

        onAdd(newProfile); 
        onClose(); 
    };
    const inputClass = "w-full border p-2 rounded dark:bg-gray-700 dark:text-white dark:border-gray-600 outline-none focus:ring-2 focus:ring-blue-500";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 text-xl dark:text-white">Add New Profile</h3>
                <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-4">
                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">SKU</label>
                        <input value={form.sku} onChange={e => setForm({...form, sku: e.target.value})} className={inputClass} required/>
                    </div>
                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Profile Name</label>
                        <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inputClass} required/>
                    </div>

                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Brand</label>
                        <select value={form.brand} onChange={e => setForm({...form, brand: e.target.value})} className={inputClass}>{brands.map((b:string) => <option key={b} value={b}>{b}</option>)}</select>
                    </div>
                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Unit of Measure</label>
                        <select value={form.uom} onChange={e => setForm({...form, uom: e.target.value})} className={inputClass}><option value="Pcs">Pcs</option><option value="Mtrs">Meters</option><option value="Kgs">Kgs</option></select>
                    </div>

                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Length (m)</label>
                        <input type="number" value={form.length} onChange={e => setForm({...form, length: e.target.value})} className={inputClass}/>
                    </div>
                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Pieces / Pack</label>
                        <input type="number" value={form.piecesPerPacket} onChange={e => setForm({...form, piecesPerPacket: e.target.value})} className={inputClass}/>
                    </div>

                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Weight (kg/length)</label>
                        <input type="number" value={form.weight} onChange={e => setForm({...form, weight: e.target.value})} className={inputClass}/>
                    </div>
                    <div className="col-span-1">
                        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Price</label>
                        <input type="number" value={form.price} onChange={e => setForm({...form, price: e.target.value})} className={inputClass}/>
                    </div>

                    <div className="col-span-2">
                        <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-1">Reorder Point (Low Stock Alert)</label>
                        <input type="number" value={form.reorderPoint} onChange={e => setForm({...form, reorderPoint: e.target.value})} className={inputClass} placeholder="e.g. 50"/>
                    </div>

                    <div className="col-span-2 flex justify-end gap-2 mt-4">
                        <button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-700 dark:text-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700">Cancel</button>
                        <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Add Profile</button>
                    </div>
                </form>
            </div>
        </div>
    );
};
