const EditProfileModal: React.FC<{ isOpen: boolean; onClose: () => void; profile: Profile | null; brands: string[]; onUpdate: (p: Profile) => void; addToast: any; }> = ({ isOpen, onClose, profile, brands, onUpdate, addToast }) => {
    const [form, setForm] = useState({ sku: '', name: '', brand: '', uom: 'Pcs', length: '', piecesPerPacket: '', weight: '', price: '', reorderPoint: '' });

    useEffect(() => {
        if (profile) {
            setForm({
                sku: profile.sku || '',
                name: profile.name || '',
                brand: profile.brand || (brands[0] || ''),
                uom: profile.uom || 'Pcs',
                length: String(profile.length || ''),
                piecesPerPacket: String(profile.piecesPerPacket || ''),
                weight: String(profile.weight || ''),
                price: String(profile.price || ''),
                reorderPoint: String(profile.reorderPoint || ''),
            });
        }
    }, [profile, brands]);

    if (!isOpen || !profile) return null;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setForm(f => ({ ...f, [e.target.name]: e.target.value }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onUpdate({ 
            ...profile, 
            ...form, 
            length: parseFloat(form.length) || undefined, 
            piecesPerPacket: parseFloat(form.piecesPerPacket) || undefined,
            weight: parseFloat(form.weight) || undefined, 
            price: parseFloat(form.price) || undefined,
            reorderPoint: parseFloat(form.reorderPoint) || undefined
        });
        onClose();
    };

    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";

    return (
         <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">Edit Profile</h3>
                <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-4">
                    <input placeholder="SKU" name="sku" value={form.sku} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Name" name="name" value={form.name} onChange={handleChange} className={inputClass}/>
                    <select name="brand" value={form.brand} onChange={handleChange} className={inputClass}>{brands.map((b:string) => <option key={b} value={b}>{b}</option>)}</select>
                    <select name="uom" value={form.uom} onChange={handleChange} className={inputClass}><option value="Pcs">Pcs</option><option value="Mtrs">Meters</option><option value="Kgs">Kgs</option></select>
                    <input placeholder="Length (m)" type="number" name="length" value={form.length} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Pack" type="number" name="piecesPerPacket" value={form.piecesPerPacket} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Length Weight" type="number" name="weight" value={form.weight} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Price" type="number" name="price" value={form.price} onChange={handleChange} className={inputClass}/>
                    <input placeholder="Reorder" type="number" name="reorderPoint" value={form.reorderPoint} onChange={handleChange} className={inputClass}/>
                    <div className="col-span-2 flex justify-end gap-2 mt-4">
                        <button type="button" onClick={onClose} className="px-4 py-2 border rounded dark:text-white">Cancel</button>
                        <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">Save Changes</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
