        addProfileTransaction, deleteProfileTransaction, updateProfileTransaction,
        addBrand, updateBrand, deleteBrand, resolveQuotation, updateCompanySettings,
        addCustomer, updateCustomer, deleteCustomer
    } = store;

    const [activeTab, setActiveTab] = useState<Tab>('Dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState<string>('All');
    const [planningTimeFilter, setPlanningTimeFilter] = useState<'1M' | '3M' | '6M' | 'ALL'>('3M');
    const [showLowStockOnly, setShowLowStockOnly] = useState(false);
    const [isDownloadMenuOpen, setIsDownloadMenuOpen] = useState(false);
    const downloadMenuRef = useRef<HTMLDivElement>(null);

    // --- State for Modals ---
    const [isAddProfileModalOpen, setIsAddProfileModalOpen] = useState(false);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [isManageBrandsModalOpen, setIsManageBrandsModalOpen] = useState(false);
    const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);

    const [transactionType, setTransactionType] = useState<'PRODUCTION' | 'DISPATCH' | 'QUOTATION' | 'SCRAP'>('PRODUCTION');

    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [editingTransaction, setEditingTransaction] = useState<ProfileTransaction | null>(null);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    const tabs: { id: Tab; label: string }[] = [
        { id: 'Dashboard', label: 'Dashboard' },
        { id: 'Stock', label: 'Profile Stock' },
        { id: 'Planning', label: 'Planning & Analysis' },
        { id: 'Production', label: 'Production (In)' },
        { id: 'Dispatch', label: 'Dispatch (Out)' },
        { id: 'Scrap', label: 'Scrap (Waste)' },
        { id: 'Quotations', label: 'Quotations' },
        { id: 'Profiles', label: 'Profile List' },
        { id: 'Customers', label: 'Customers' },
    ];

    const canManage = true; 

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
                setIsDownloadMenuOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    useEffect(() => {
        if (brandFilter !== 'All' && !brands.includes(brandFilter)) {
            setBrandFilter('All');
        }
    }, [brands, brandFilter]);

    // --- Derived Data ---
    const activeProfiles = useMemo(() => profiles.filter(p => !p.deletedAt), [profiles]);
    const activeTransactions = useMemo(() => profileTransactions.filter(t => !t.deletedAt), [profileTransactions]);
    const activeCustomers = useMemo(() => customers.filter(c => !c.deletedAt), [customers]);

    const brandFilteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return activeProfiles;
        return activeProfiles.filter(p => p.brand === brandFilter);
    }, [activeProfiles, brandFilter]);

    const getProfile = useCallback((id: string) => activeProfiles.find(p => p.id === id), [activeProfiles]);

    const stockData = useMemo(() => {
        let filtered = brandFilteredProfiles.map(p => {
            const production = activeTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = activeTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const scrap = activeTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP').reduce((sum, t) => {
                if (t.uom === 'Kgs' && p.weight && p.weight > 0) {
                    return sum + (t.quantity / p.weight);
                }
                return sum + t.quantity;
            }, 0);

            const reserved = activeTransactions.filter(t => t.profileId === p.id && t.type === 'QUOTATION' && t.status === 'PENDING').reduce((sum, t) => sum + t.quantity, 0);
            const currentStock = production - dispatch - scrap; 
            return { ...p, currentStock: Math.floor(currentStock), reservedStock: reserved, availableStock: currentStock - reserved };
        });

        if (showLowStockOnly) {
            filtered = filtered.filter(p => p.currentStock < (p.reorderPoint || 0));
        }

        return filtered.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [brandFilteredProfiles, activeTransactions, searchTerm, showLowStockOnly]);

    const planningData = useMemo(() => {
        const now = new Date();
        let thresholdDate: Date | null = null;

        if (planningTimeFilter === '1M') { thresholdDate = new Date(); thresholdDate.setMonth(now.getMonth() - 1); } 
        else if (planningTimeFilter === '3M') { thresholdDate = new Date(); thresholdDate.setMonth(now.getMonth() - 3); } 
        else if (planningTimeFilter === '6M') { thresholdDate = new Date(); thresholdDate.setMonth(now.getMonth() - 6); }

        const periodDispatches = activeTransactions.filter(t => t.type === 'DISPATCH' && (!thresholdDate || new Date(t.date) >= thresholdDate));
        const totalPeriodVolume = periodDispatches.reduce((sum, t) => sum + t.quantity, 0);

        return brandFilteredProfiles.map(p => {
            const production = activeTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = activeTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const scrap = activeTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP').reduce((sum, t) => sum + t.quantity, 0);
            const currentStock = production - dispatch - scrap;

            const periodSales = periodDispatches.filter(t => t.profileId === p.id).reduce((sum, t) => sum + t.quantity, 0);
            const sharePercentage = totalPeriodVolume > 0 ? (periodSales / totalPeriodVolume) * 100 : 0;

            return { ...p, currentStock, periodSales, sharePercentage };
        })
        .filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase()))
        .sort((a, b) => b.sharePercentage - a.sharePercentage);
    }, [brandFilteredProfiles, activeTransactions, searchTerm, planningTimeFilter]);

    const productionData = useFilteredTransactions(activeTransactions, brandFilteredProfiles, searchTerm, getProfile, 'PRODUCTION');
    const dispatchData = useFilteredTransactions(activeTransactions, brandFilteredProfiles, searchTerm, getProfile, 'DISPATCH');
    const scrapData = useFilteredTransactions(activeTransactions, brandFilteredProfiles, searchTerm, getProfile, 'SCRAP');
    const quotationData = useFilteredTransactions(activeTransactions, brandFilteredProfiles, searchTerm, getProfile, 'QUOTATION');

    const filteredProfiles = useMemo(() => brandFilteredProfiles.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [brandFilteredProfiles, searchTerm]);
    const filteredCustomers = useMemo(() => activeCustomers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())), [activeCustomers, searchTerm]);

    const handleOpenTransactionModal = (type: 'PRODUCTION' | 'DISPATCH' | 'QUOTATION' | 'SCRAP') => { setTransactionType(type); setIsTransactionModalOpen(true); };
    const handleQuotationAction = (id: string, action: 'CONFIRM' | 'CANCEL') => { resolveQuotation(id, action); if (action === 'CONFIRM') addToast('Quotation Confirmed & Dispatch created!', 'success'); else addToast('Quotation Cancelled', 'info'); };
    const getProfileName = (id: string) => getProfile(id)?.name || 'Unknown';
    const getProfileSpecs = (id: string) => { const p = getProfile(id); return p ? `${p.length || '-'}m / ${p.weight || '-'}kg` : '-'; };

    const getBrandBadge = (brand?: string) => {
        if (!brand) return <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">-</span>;
        const colors = ['bg-blue-100 text-blue-800', 'bg-purple-100 text-purple-800', 'bg-green-100 text-green-800', 'bg-indigo-100 text-indigo-800', 'bg-pink-100 text-pink-800'];
        return <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${colors[brand.length % colors.length]}`}>{brand}</span>;
    };

    const getActiveTableId = () => `profile-${activeTab.toLowerCase()}-table`;

    const handleExport = (type: 'PDF' | 'Excel') => {
        const tableId = getActiveTableId();
        const tableContainer = document.getElementById(tableId);
        const tableElement = tableContainer?.querySelector('table');
        if (!tableElement) {
            addToast('No data to export', 'error');
            return;
        }

        const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
        const headers = Array.from(clonedTable.querySelectorAll('thead th'));

        const actionIndices = headers
          .map((th, index) => 
            th.classList.contains('no-print') ||
            (th.textContent || '').toLowerCase().indexOf('action') !== -1 || 
            (th.textContent || '').toLowerCase().indexOf('edit') !== -1 || 
            (th.textContent || '').toLowerCase().indexOf('confirm') !== -1 
            ? index : -1
          )
          .filter(index => index !== -1);

        actionIndices.sort((a, b) => b - a).forEach(index => {
            Array.from(clonedTable.rows).forEach(row => {
                if (row.cells[index]) row.deleteCell(index);
            });
        });

        if (type === 'Excel') {
            const wb = XLSX.utils.table_to_book(clonedTable, { sheet: "Sheet1" });
            XLSX.writeFile(wb, `Profile_${activeTab}.xlsx`);
        } else {
            const { jsPDF } = jspdf;
            const doc = new jsPDF({ orientation: 'landscape' });

            const title = `Profile ${activeTab} Report`;
            const date = new Date().toLocaleDateString();
            doc.text(`${title} - ${date}`, 14, 15);

            doc.autoTable({ 
                html: clonedTable,
                startY: 20,
                theme: 'grid',
                styles: { fontSize: 8 },
                headStyles: { fillColor: [45, 62, 80] },
            });
            doc.save(`Profile_${activeTab}.pdf`);
        }
        setIsDownloadMenuOpen(false);
    };

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                 <div className="flex items-center gap-2 flex-wrap">
                     {canManage && <button onClick={() => setIsSettingsModalOpen(true)} className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 px-3 py-2 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 border border-gray-300 dark:border-gray-600 shadow-sm flex items-center gap-2"><WarehouseIcon className="w-4 h-4" /><span className="hidden sm:inline text-sm font-medium">Settings</span></button>}
                    {activeTab !== 'Dashboard' && (
                    <div className="relative" ref={downloadMenuRef}>
                        <button onClick={() => setIsDownloadMenuOpen(p => !p)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2">Download<ChevronDownIcon className={`w-4 h-4 transition-transform ${isDownloadMenuOpen ? 'rotate-180' : ''}`} /></button>
                        {isDownloadMenuOpen && (<div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-20 ring-1 ring-black ring-opacity-5 border dark:border-gray-700"><button onClick={() => handleExport('PDF')} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">Download as PDF</button><button onClick={() => handleExport('Excel')} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">Download as Excel</button></div>)}
                    </div>
                    )}
                    <div className="flex bg-gray-200 dark:bg-gray-700 rounded-lg p-1 mr-2 items-center">
                         {activeTab === 'Planning' && (<select value={planningTimeFilter} onChange={(e) => setPlanningTimeFilter(e.target.value as any)} className="mr-2 bg-white dark:bg-gray-600 border-none rounded-md text-xs font-medium px-2 py-1.5 focus:ring-0 cursor-pointer"><option value="1M">Last 1 Month</option><option value="3M">Last 3 Months</option><option value="6M">Last 6 Months</option><option value="ALL">All Time</option></select>)}
                        <button onClick={() => setBrandFilter('All')} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === 'All' ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>All</button>
                        {brands.map(brand => <button key={brand} onClick={() => setBrandFilter(brand)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === brand ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>{brand}</button>)}
                        {canManage && <button onClick={() => setIsManageBrandsModalOpen(true)} className="ml-1 px-2 py-1 text-gray-500" title="Manage Brands"><PencilIcon className="w-3 h-3" /></button>}
                    </div>
                    {activeTab === 'Production' && canManage && <button onClick={() => handleOpenTransactionModal('PRODUCTION')} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-green-700 shadow">+ Production</button>}
                    {activeTab === 'Dispatch' && canManage && <button onClick={() => handleOpenTransactionModal('DISPATCH')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow">- Dispatch</button>}
                    {activeTab === 'Scrap' && canManage && <button onClick={() => handleOpenTransactionModal('SCRAP')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow flex items-center gap-1"><TrashIcon className="w-4 h-4"/> Record Scrap</button>}
                    {activeTab === 'Quotations' && canManage && <button onClick={() => handleOpenTransactionModal('QUOTATION')} className="bg-orange-500 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-orange-600 shadow">+ Add Item</button>}
                    {activeTab === 'Profiles' && canManage && <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">+ Profile</button>}
                    {activeTab === 'Customers' && canManage && <button onClick={() => setIsCustomerModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2"><UserPlusIcon className="w-4 h-4"/> Add Customer</button>}
                 </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {tabs.map(tab => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}>{tab.label}</button>)}
                </nav>

                 <div className="flex items-center gap-3">
                    {activeTab === 'Stock' && (
                        <div className="flex items-center">
                            <input
                                type="checkbox"
                                id="lowStockToggle"
                                checked={showLowStockOnly}
                                onChange={e => setShowLowStockOnly(e.target.checked)}
                                className="h-4 w-4 rounded border-gray-300 dark:border-gray-600 text-blue-600 focus:ring-blue-500 bg-white dark:bg-gray-700"
                            />
                            <label htmlFor="lowStockToggle" className="ml-2 block text-sm text-gray-900 dark:text-gray-300 select-none">
                                Show Low Stock
                            </label>
                        </div>
                    )}
                    <div className="mb-2 relative hidden sm:block"><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-1 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md w-64" /><SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" /></div>
                 </div>
            </div>

            <div className="animate-fade-in-right">
                {activeTab === 'Dashboard' && <ProfileDashboard profiles={activeProfiles} transactions={activeTransactions} stockData={stockData} />}
                {activeTab === 'Stock' && <div id="profile-stock-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><StockTable stockData={stockData} onEditProfile={setEditingProfile} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Planning' && <div id="profile-planning-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><PlanningTable planningData={planningData} getBrandBadge={getBrandBadge} planningTimeFilter={planningTimeFilter} /></div>}
                {activeTab === 'Production' && <div id="profile-production-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><TransactionTable transactions={productionData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} type="PRODUCTION" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Dispatch' && <div id="profile-dispatch-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><TransactionTable transactions={dispatchData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} type="DISPATCH" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Scrap' && <div id="profile-scrap-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><TransactionTable transactions={scrapData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} type="SCRAP" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Quotations' && <div id="profile-quotation-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><QuotationTable transactions={quotationData} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onAction={handleQuotationAction} onEdit={setEditingTransaction} onDelete={deleteProfileTransaction} getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Profiles' && <div id="profile-profiles-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><ProfileListTable profiles={filteredProfiles} onEdit={setEditingProfile} onDelete={deleteProfile} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Customers' && <div id="profile-customers-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden"><CustomerTable customers={filteredCustomers} onEdit={setEditingCustomer} onDelete={deleteCustomer} /></div>}
            </div>

            <Portal><TransactionModal isOpen={isTransactionModalOpen} onClose={() => setIsTransactionModalOpen(false)} type={transactionType} profiles={brandFilteredProfiles} onAdd={addProfileTransaction} addToast={addToast} customers={activeCustomers} addCustomer={addCustomer}/></Portal>
            <Portal>{editingProfile && <EditProfileModal isOpen={!!editingProfile} onClose={() => setEditingProfile(null)} profile={editingProfile} onUpdate={updateProfile} brands={brands} addToast={addToast} />}</Portal>
            <Portal>{editingTransaction && <EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} onUpdate={updateProfileTransaction} addToast={addToast} />}</Portal>
            <Portal><AddProfileModal isOpen={isAddProfileModalOpen} onClose={() => setIsAddProfileModalOpen(false)} onAdd={addProfile} brands={brands} addToast={addToast} /></Portal>
            <Portal>
                <CustomerModal 
                    isOpen={isCustomerModalOpen || !!editingCustomer} 
                    onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} 
                    customer={editingCustomer} 
                    onSave={(c) => { 
                        if (editingCustomer) {
                            updateCustomer({ ...editingCustomer, ...c });
                        } else {
                            addCustomer(c);
                        }
                    }} 
                    addToast={addToast} 
                />
            </Portal>
            <Portal><ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
            <Portal><CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} addToast={addToast} /></Portal>
        </div>
    );
};

// --- TABLE COMPONENTS ---
const StockTable: React.FC<any> = ({ stockData, onEditProfile, getBrandBadge }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr>
                <th className="px-6 py-3">Brand</th>
