    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Profile Name</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Current Stock</th><th className="px-6 py-3 text-right">{planningTimeFilter === 'ALL' ? 'All Time Sales' : `Sales (${planningTimeFilter})`}</th><th className="px-6 py-3 text-right">Share %</th></tr>
