                            <div className="w-24 h-1.5 bg-gray-200 dark:bg-gray-600 rounded-full mt-1"><div className="h-1.5 bg-blue-500 rounded-full" style={{ width: `${Math.min(p.sharePercentage, 100)}%` }}></div></div>
                        </div>
