import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import type { 
    User, Item, InflowTransaction, ConsumptionTransaction, Formula, 
    ReportCorrection, Profile, ProfileTransaction, Die, ProductionPlan, 
    Customer, UIState 
} from '../types';

interface AppState {
    currentUser: User | null;
    items: Item[];
    inflowTransactions: InflowTransaction[];
    consumptionTransactions: ConsumptionTransaction[];
    formulas: Formula[];
    reportCorrections: ReportCorrection[];
    profiles: Profile[];
    profileTransactions: ProfileTransaction[];
    dies: Die[];
    productionPlans: ProductionPlan[];
    brands: string[];
    customers: Customer[];
    uiState: UIState;

    // Auth
    login: (user: User) => void;
    logout: () => void;
    loadData: (data: any) => void;
    resetData: () => void;
    setLastSync: (time: string) => void;

    // Items
    addItem: (item: Omit<Item, 'id' | 'createdAt'>) => void;
    updateItem: (item: Item) => void;
    deleteItem: (itemId: string) => void;
    restoreItem: (itemId: string) => void;
    permanentlyDeleteItem: (itemId: string) => void;

    // Inflow
    addInflowTransaction: (tx: Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost'>) => void;
    addMultipleInflowTransactions: (txs: (Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost' | 'itemId'> & { sku: string, name?: string })[]) => void;
    createItemAndInflow: (itemData: Omit<Item, 'id' | 'createdAt'>, txData: Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost' | 'itemId'>) => void;
    updateInflowTransaction: (tx: InflowTransaction) => void;
    deleteInflowTransaction: (transactionId: string) => void;

    // Consumption
    addMultipleConsumptionTransactions: (txs: Omit<ConsumptionTransaction, 'id' | 'createdAt'>[]) => void;
    updateConsumptionTransaction: (tx: ConsumptionTransaction) => void;
    deleteConsumptionTransaction: (txId: string) => void;

    // Transactions (General for Trash)
    restoreTransaction: (id: string, type: 'inflow' | 'consumption') => void;
    permanentlyDeleteTransaction: (id: string, type: 'inflow' | 'consumption') => void;

    // Formulas
    addFormula: (formula: Omit<Formula, 'id' | 'createdAt'>) => void;
    updateFormula: (formula: Formula) => void;
    deleteFormula: (formulaId: string) => void;
    restoreFormula: (formulaId: string) => void;
    permanentlyDeleteFormula: (formulaId: string) => void;

    // Reports
    addOrUpdateReportCorrection: (correction: Omit<ReportCorrection, 'updatedAt'>) => void;

    // Profiles
    addProfile: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile;
    updateProfile: (profile: Profile) => void;
    deleteProfile: (id: string) => void;
    restoreProfile: (id: string) => void;
    permanentlyDeleteProfile: (id: string) => void;

    // Profile Transactions
    addProfileTransaction: (tx: Omit<ProfileTransaction, 'id' | 'createdAt'>) => void;
    addMultipleProfileTransactions: (txs: Omit<ProfileTransaction, 'id' | 'createdAt'>[]) => void;
    updateProfileTransaction: (tx: ProfileTransaction) => void;
    deleteProfileTransaction: (id: string) => void;
    restoreProfileTransaction: (id: string) => void;
    permanentlyDeleteProfileTransaction: (id: string) => void;
    resolveQuotation: (id: string, action: 'CONFIRM' | 'CANCEL') => void;

    // Dies
    addDie: (die: Omit<Die, 'id' | 'createdAt' | 'brand'>) => void;
    updateDie: (die: Die) => void;
    deleteDie: (id: string) => void;
    restoreDie: (id: string) => void;
    permanentlyDeleteDie: (id: string) => void;

    // Production Plans
    addProductionPlan: (plan: Omit<ProductionPlan, 'id' | 'createdAt'>) => void;
    updateProductionPlan: (plan: ProductionPlan) => void;
    deleteProductionPlan: (id: string) => void;
    restoreProductionPlan: (id: string) => void;
    permanentlyDeleteProductionPlan: (id: string) => void;

    // Brands
    addBrand: (brand: string) => void;
    updateBrand: (oldB: string, newB: string) => void;
    deleteBrand: (brand: string) => void;

    // Customers
    addCustomer: (customer: Omit<Customer, 'id' | 'createdAt' | 'deletedAt'>) => void;
    updateCustomer: (customer: Customer) => void;
    deleteCustomer: (id: string) => void;

    // UI State
    setInflowFilters: (filters: UIState['inflowFilters']) => void;
    setConsumptionFilters: (filters: UIState['consumptionFilters']) => void;
}

const initialUIState: UIState = {
    lastSync: null,
    inflowFilters: { dateFrom: '', dateTo: '', itemId: '', supplier: '', quantity: '', unitCost: '' },
    consumptionFilters: { dateFrom: '', dateTo: '', itemId: '', batchNo: '', quantity: '' }
};

export const useStore = create<AppState>()(
    persist(
        (set, get) => ({
            currentUser: null,
            items: [],
            inflowTransactions: [],
            consumptionTransactions: [],
            formulas: [],
            reportCorrections: [],
            profiles: [],
            profileTransactions: [],
            dies: [],
            productionPlans: [],
            brands: ['Sudhakar', 'Nandi', 'Supreme', 'Ashirvad', 'Astral', 'Finolex'],
            customers: [],
            uiState: initialUIState,

            // Auth
            login: (user) => set({ currentUser: user }),
            logout: () => set({ currentUser: null }),
            loadData: (data) => set(state => ({ ...state, ...data })),
            resetData: () => set({ 
                items: [], inflowTransactions: [], consumptionTransactions: [], formulas: [], 
                reportCorrections: [], profiles: [], profileTransactions: [], dies: [], 
                productionPlans: [], customers: [], uiState: initialUIState 
            }),
            setLastSync: (time) => set(state => ({ uiState: { ...state.uiState, lastSync: time } })),

            // Items
            addItem: (item) => set(state => ({ 
                items: [...state.items, { ...item, id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }] 
            })),
            updateItem: (item) => set(state => ({ items: state.items.map(i => i.id === item.id ? item : i) })),
            deleteItem: (itemId) => set(state => ({ 
                items: state.items.map(i => i.id === itemId ? { ...i, deletedAt: new Date().toISOString() } : i) 
            })),
            restoreItem: (itemId) => set(state => ({
                items: state.items.map(i => i.id === itemId ? { ...i, deletedAt: undefined } : i)
            })),
            permanentlyDeleteItem: (itemId) => set(state => ({ items: state.items.filter(i => i.id !== itemId) })),

            // Inflow
            addInflowTransaction: (tx) => set(state => ({
                inflowTransactions: [...state.inflowTransactions, {
                    ...tx,
                    id: `tx_in_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                    totalCost: tx.quantity * tx.unitCost,
                    createdAt: new Date().toISOString()
                }]
            })),
            addMultipleInflowTransactions: (txs) => set(state => {
                const newItems: Item[] = [];
                const newTransactions: InflowTransaction[] = [];
                const timestamp = new Date().toISOString();

                txs.forEach((txData, index) => {
                    let itemId = '';
                    // Try to find existing item by SKU
                    const existingItem = state.items.find(i => i.sku === txData.sku) || newItems.find(i => i.sku === txData.sku);

                    if (existingItem) {
                        itemId = existingItem.id;
                    } else {
                        itemId = `item_${Date.now()}_${index}_${Math.random().toString(36).substr(2, 9)}`;
                        newItems.push({
                            id: itemId,
                            sku: txData.sku,
                            name: txData.name || txData.sku,
                            uom: 'Units',
                            reorderPoint: 10,
                            costPrice: txData.unitCost,
                            createdAt: timestamp
                        });
                    }

                    newTransactions.push({
                        id: `tx_in_${Date.now()}_${index}_${Math.random().toString(36).substr(2, 9)}`,
                        itemId,
                        refNo: txData.refNo || `IMP-${Date.now()}-${index}`,
                        quantity: txData.quantity,
                        unitCost: txData.unitCost,
                        totalCost: txData.quantity * txData.unitCost,
                        supplier: txData.supplier,
                        txnDate: txData.txnDate || timestamp,
                        warehouseId: 'wh1',
                        createdAt: timestamp
                    });
                });

                return {
                    items: [...state.items, ...newItems],
                    inflowTransactions: [...state.inflowTransactions, ...newTransactions]
                };
            }),
            createItemAndInflow: (itemData, txData) => set(state => {
                const itemId = `item_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
                const newItem: Item = { ...itemData, id: itemId, createdAt: new Date().toISOString() };
                const newTx: InflowTransaction = {
                    ...txData,
                    id: `tx_in_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                    itemId,
                    totalCost: txData.quantity * txData.unitCost,
                    createdAt: new Date().toISOString()
                };
                return { items: [...state.items, newItem], inflowTransactions: [...state.inflowTransactions, newTx] };
            }),
            updateInflowTransaction: (tx) => set(state => ({
                inflowTransactions: state.inflowTransactions.map(t => t.id === tx.id ? tx : t)
            })),
            deleteInflowTransaction: (transactionId) => set(state => ({
                inflowTransactions: state.inflowTransactions.map(t => t.id === transactionId ? { ...t, deletedAt: new Date().toISOString() } : t)
            })),

            // Consumption
            addMultipleConsumptionTransactions: (txs) => set(state => ({
                consumptionTransactions: [
                    ...state.consumptionTransactions,
                    ...txs.map(tx => ({
                        ...tx,
                        id: `tx_out_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                        createdAt: new Date().toISOString()
                    }))
                ]
            })),
            updateConsumptionTransaction: (tx) => set(state => ({
                consumptionTransactions: state.consumptionTransactions.map(t => t.id === tx.id ? tx : t)
            })),
            deleteConsumptionTransaction: (txId) => set(state => ({
                consumptionTransactions: state.consumptionTransactions.map(t => t.id === txId ? { ...t, deletedAt: new Date().toISOString() } : t)
            })),

            // Trash General
            restoreTransaction: (id, type) => set(state => {
                if (type === 'inflow') {
                    return { inflowTransactions: state.inflowTransactions.map(t => t.id === id ? { ...t, deletedAt: undefined } : t) };
                } else {
                    return { consumptionTransactions: state.consumptionTransactions.map(t => t.id === id ? { ...t, deletedAt: undefined } : t) };
                }
            }),
            permanentlyDeleteTransaction: (id, type) => set(state => {
                if (type === 'inflow') {
                    return { inflowTransactions: state.inflowTransactions.filter(t => t.id !== id) };
                } else {
                    return { consumptionTransactions: state.consumptionTransactions.filter(t => t.id !== id) };
                }
            }),

            // Formulas
            addFormula: (formula) => set(state => ({
                formulas: [...state.formulas, { ...formula, id: `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }]
            })),
            updateFormula: (formula) => set(state => ({ formulas: state.formulas.map(f => f.id === formula.id ? formula : f) })),
            deleteFormula: (formulaId) => set(state => ({
                formulas: state.formulas.map(f => f.id === formulaId ? { ...f, deletedAt: new Date().toISOString() } : f)
            })),
            restoreFormula: (formulaId) => set(state => ({
                formulas: state.formulas.map(f => f.id === formulaId ? { ...f, deletedAt: undefined } : f)
            })),
            permanentlyDeleteFormula: (formulaId) => set(state => ({ formulas: state.formulas.filter(f => f.id !== formulaId) })),

            // Reports
            addOrUpdateReportCorrection: (correction) => set(state => {
                const existingIndex = state.reportCorrections.findIndex(c => c.itemId === correction.itemId && c.date === correction.date);
                if (existingIndex >= 0) {
                    const newCorrections = [...state.reportCorrections];
                    newCorrections[existingIndex] = { ...correction, updatedAt: new Date().toISOString() };
                    return { reportCorrections: newCorrections };
                }
                return { reportCorrections: [...state.reportCorrections, { ...correction, updatedAt: new Date().toISOString() }] };
            }),

            // Profiles
            addProfile: (profile) => {
                const newProfile = { ...profile, id: `p_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() };
                set(state => ({ profiles: [...state.profiles, newProfile] }));
                return newProfile;
            },
            updateProfile: (profile) => set(state => ({ profiles: state.profiles.map(p => p.id === profile.id ? profile : p) })),
            deleteProfile: (id) => set(state => ({ profiles: state.profiles.map(p => p.id === id ? { ...p, deletedAt: new Date().toISOString() } : p) })),
            restoreProfile: (id) => set(state => ({ profiles: state.profiles.map(p => p.id === id ? { ...p, deletedAt: undefined } : p) })),
            permanentlyDeleteProfile: (id) => set(state => ({ profiles: state.profiles.filter(p => p.id !== id) })),

            // Profile Transactions
            addProfileTransaction: (tx) => set(state => ({ 
                profileTransactions: [...state.profileTransactions, { ...tx, id: `pt_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }] 
            })),
            addMultipleProfileTransactions: (txs) => set(state => ({
                profileTransactions: [...state.profileTransactions, ...txs.map(tx => ({
                    ...tx,
                    id: `pt_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                    createdAt: new Date().toISOString()
                }))]
            })),
            updateProfileTransaction: (tx) => set(state => ({ profileTransactions: state.profileTransactions.map(t => t.id === tx.id ? tx : t) })),
            deleteProfileTransaction: (id) => set(state => ({ profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, deletedAt: new Date().toISOString() } : t) })),
            restoreProfileTransaction: (id) => set(state => ({ profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, deletedAt: undefined } : t) })),
            permanentlyDeleteProfileTransaction: (id) => set(state => ({ profileTransactions: state.profileTransactions.filter(t => t.id !== id) })),
            resolveQuotation: (id, action) => set(state => ({
                profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, status: action === 'CONFIRM' ? 'COMPLETED' : 'CANCELLED' } : t)
            })),

            // Dies
            addDie: (die) => set(state => ({ dies: [...state.dies, { ...die, id: `die_${Date.now()}`, createdAt: new Date().toISOString() }] })),
            updateDie: (die) => set(state => ({ dies: state.dies.map(d => d.id === die.id ? die : d) })),
            deleteDie: (id) => set(state => ({ dies: state.dies.map(d => d.id === id ? { ...d, deletedAt: new Date().toISOString() } : d) })),
            restoreDie: (id) => set(state => ({ dies: state.dies.map(d => d.id === id ? { ...d, deletedAt: undefined } : d) })),
            permanentlyDeleteDie: (id) => set(state => ({ dies: state.dies.filter(d => d.id !== id) })),

            // Production Plans
            addProductionPlan: (plan) => set(state => ({ productionPlans: [...state.productionPlans, { ...plan, id: `plan_${Date.now()}`, createdAt: new Date().toISOString() }] })),
            updateProductionPlan: (plan) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === plan.id ? plan : p) })),
            deleteProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === id ? { ...p, deletedAt: new Date().toISOString() } : p) })),
            restoreProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === id ? { ...p, deletedAt: undefined } : p) })),
            permanentlyDeleteProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.filter(p => p.id !== id) })),

            // Brands
            addBrand: (brand) => set(state => ({ brands: [...state.brands, brand] })),
            updateBrand: (oldB, newB) => set(state => ({ 
                brands: state.brands.map(b => b === oldB ? newB : b),
                profiles: state.profiles.map(p => p.brand === oldB ? { ...p, brand: newB } : p),
                dies: state.dies.map(d => d.brand === oldB ? { ...d, brand: newB } : d)
            })),
            deleteBrand: (brand) => set(state => ({ brands: state.brands.filter(b => b !== brand) })),

            // Customers
            addCustomer: (customer) => set(state => ({ 
                customers: [...state.customers, { ...customer, id: `cust_${Date.now()}`, createdAt: new Date().toISOString() }] 
            })),
            updateCustomer: (customer) => set(state => ({ customers: state.customers.map(c => c.id === customer.id ? customer : c) })),
            deleteCustomer: (id) => set(state => ({ customers: state.customers.filter(c => c.id !== id) })),

            // UI State
            setInflowFilters: (filters) => set(state => ({ uiState: { ...state.uiState, inflowFilters: filters } })),
            setConsumptionFilters: (filters) => set(state => ({ uiState: { ...state.uiState, consumptionFilters: filters } }))
        }),
        {
            name: 'inventory-store',
            storage: createJSONStorage(() => localStorage),
        }
    )
);

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import type { Profile, ProfileTransaction, ProfileTransactionType, ToastMessage, Customer } from '../types';
import { useStore } from '../store/useStore';
import { SearchIcon, ChevronDownIcon, UserPlusIcon, TrashIcon, PencilIcon } from '../components/Icon';
import AddProfileModal from '../components/AddProfileModal';
import CreateQuotationModal from '../components/CreateQuotationModal';
import CustomerModal from '../components/CustomerModal';
import Card from '../components/Card';

const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};

interface ProfileSectionProps {
    addToast: (message: string, type: ToastMessage['type']) => void;
}

type Tab = 'Stock' | 'Daily Log' | 'Customers' | 'Quotation';

const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const store = useStore();
    const { 
        profiles, profileTransactions, brands, customers,
        addProfile, updateProfile, deleteProfile,
        addProfileTransaction, deleteProfileTransaction, resolveQuotation,
        addCustomer, updateCustomer, deleteCustomer
    } = store;

    const [activeTab, setActiveTab] = useState<Tab>('Stock');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState('All');

    // Modals
    const [isAddProfileModalOpen, setIsAddProfileModalOpen] = useState(false);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [transactionType, setTransactionType] = useState<ProfileTransactionType>('PRODUCTION');
    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    // Derived Data
    const activeProfiles = useMemo(() => profiles.filter(p => !p.deletedAt), [profiles]);
    const activeTransactions = useMemo(() => profileTransactions.filter(t => !t.deletedAt), [profileTransactions]);
    const activeCustomers = useMemo(() => customers.filter(c => !c.deletedAt), [customers]);

    const filteredProfiles = useMemo(() => {
        let filtered = activeProfiles;
        if (brandFilter !== 'All') {
            filtered = filtered.filter(p => p.brand === brandFilter);
        }
        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            filtered = filtered.filter(p => 
                p.name.toLowerCase().includes(lower) || 
                p.sku.toLowerCase().includes(lower)
            );
        }
        return filtered;
    }, [activeProfiles, brandFilter, searchTerm]);

    const brandFilteredProfiles = useMemo(() => {
         if (brandFilter !== 'All') {
            return activeProfiles.filter(p => p.brand === brandFilter);
        }
        return activeProfiles;
    }, [activeProfiles, brandFilter]);

    // Stock Calculation
    const profileStockMap = useMemo(() => {
        const stockMap = new Map<string, number>();
        activeProfiles.forEach(p => {
            const production = activeTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = activeTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const scrap = activeTransactions.filter(t => t.profileId === p.id && t.type === 'SCRAP').reduce((sum, t) => {
                // Convert Scrap Kg to Pcs/Meters if possible
                if (t.uom === 'Kgs' && p.weight && p.weight > 0) {
                     return sum + (t.quantity / p.weight);
                }
                return sum + t.quantity;
            }, 0);
            stockMap.set(p.id, production - dispatch - scrap);
        });
        return stockMap;
    }, [activeProfiles, activeTransactions]);

    const openTransactionModal = (type: ProfileTransactionType) => {
        setTransactionType(type);
        setIsTransactionModalOpen(true);
    };

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                <div className="flex gap-2">
                     {activeTab === 'Stock' && (
                        <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">
                            + Add Profile
                        </button>
                    )}
                    {activeTab === 'Customers' && (
                         <button onClick={() => { setEditingCustomer(null); setIsCustomerModalOpen(true); }} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2">
                            <UserPlusIcon className="w-4 h-4"/> Add Customer
                        </button>
                    )}
                    {(activeTab === 'Stock' || activeTab === 'Daily Log') && (
                        <div className="flex gap-2">
                            <button onClick={() => openTransactionModal('PRODUCTION')} className="bg-green-600 text-white px-3 py-2 rounded-md text-sm font-semibold hover:bg-green-700 shadow">Production</button>
                            <button onClick={() => openTransactionModal('DISPATCH')} className="bg-indigo-600 text-white px-3 py-2 rounded-md text-sm font-semibold hover:bg-indigo-700 shadow">Dispatch</button>
                            <button onClick={() => openTransactionModal('SCRAP')} className="bg-red-600 text-white px-3 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow">Scrap</button>
                        </div>
                    )}
                     {activeTab === 'Quotation' && (
                        <button onClick={() => openTransactionModal('QUOTATION')} className="bg-[#958D5F] text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-opacity-90 shadow">
                            Create Quotation
                        </button>
                     )}
                </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end flex-wrap gap-4">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {['Stock', 'Daily Log', 'Customers', 'Quotation'].map(tab => (
                        <button 
                            key={tab} 
                            onClick={() => setActiveTab(tab as Tab)} 
                            className={`${activeTab === tab ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}
                        >
                            {tab}
                        </button>
                    ))}
                </nav>
                <div className="flex items-center gap-4 mb-2">
                    <select value={brandFilter} onChange={e => setBrandFilter(e.target.value)} className="bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block p-2">
                        <option value="All">All Brands</option>
                        {brands.map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <div className="relative">
                        <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-10 pr-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md w-64 text-sm" />
                        <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    </div>
                </div>
            </div>

            {activeTab === 'Stock' && (
                <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-x-auto">
                    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                            <tr>
                                <th className="px-6 py-3">Brand</th>
                                <th className="px-6 py-3">SKU</th>
                                <th className="px-6 py-3">Name</th>
                                <th className="px-6 py-3">Length</th>
                                <th className="px-6 py-3 text-right">Current Stock</th>
                                <th className="px-6 py-3 text-center">Status</th>
                                <th className="px-6 py-3 text-right">Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredProfiles.map(p => {
                                const stock = profileStockMap.get(p.id) || 0;
                                const isLow = stock < (p.reorderPoint || 0);
                                return (
                                    <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                                        <td className="px-6 py-4"><span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">{p.brand}</span></td>
                                        <th scope="row" className="px-6 py-4 font-medium text-gray-900 dark:text-white whitespace-nowrap">{p.sku}</th>
                                        <td className="px-6 py-4">{p.name}</td>
                                        <td className="px-6 py-4">{p.length}m</td>
                                        <td className={`px-6 py-4 text-right font-bold ${isLow ? 'text-orange-500' : ''}`}>{stock.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-center">
                                            {isLow ? <span className="text-xs font-bold text-orange-600 bg-orange-100 px-2 py-1 rounded">Low Stock</span> : <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-1 rounded">OK</span>}
                                        </td>
                                        <td className="px-6 py-4 text-right"><button onClick={() => deleteProfile(p.id)} className="text-red-500 hover:text-red-700"><TrashIcon className="w-4 h-4" /></button></td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            )}

            {activeTab === 'Daily Log' && (
                 <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-x-auto">
                    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                            <tr>
                                <th className="px-6 py-3">Date</th>
                                <th className="px-6 py-3">Type</th>
                                <th className="px-6 py-3">Ref No</th>
