                                                t.type === 'DISPATCH' ? 'bg-indigo-100 text-indigo-800' :
                                                t.type === 'SCRAP' ? 'bg-red-100 text-red-800' : 'bg-gray-100'
                                            }`}>
                                                {t.type}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 font-medium">{t.refNo}</td>
