                                        }`}>
                                            {t.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-right space-x-2">
                                        {t.status === 'PENDING' && (
                                            <>
                                                <button onClick={() => resolveQuotation(t.id, 'CONFIRM')} className="text-green-600 hover:underline text-xs">Confirm</button>
                                                <button onClick={() => resolveQuotation(t.id, 'CANCEL')} className="text-red-600 hover:underline text-xs">Cancel</button>
                                            </>
                                        )}
