                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            <Portal>
                <AddProfileModal 
                    isOpen={isAddProfileModalOpen} 
                    onClose={() => setIsAddProfileModalOpen(false)} 
                    onAdd={addProfile} 
                    brands={brands} 
                    addToast={addToast} 
                />
            </Portal>

            <Portal>
                <CustomerModal
                    isOpen={isCustomerModalOpen}
                    onClose={() => setIsCustomerModalOpen(false)}
                    customer={editingCustomer}
                    onSave={(data) => {
                        if(editingCustomer) updateCustomer({ ...editingCustomer, ...data });
                        else addCustomer(data);
                    }}
                    addToast={addToast}
                />
            </Portal>

            <Portal>
                {/* Condition: if QUOTATION type, show full invoice modal, else normal transaction modal */}
                {transactionType === 'QUOTATION' ? (
                    <CreateQuotationModal 
                        isOpen={isTransactionModalOpen} 
                        onClose={() => setIsTransactionModalOpen(false)} 
                        profiles={brandFilteredProfiles} 
                        customers={activeCustomers}
                        onAddMultiple={store.addMultipleProfileTransactions} 
                        addToast={addToast}
                    />
                ) : (
                    <TransactionModal 
                        isOpen={isTransactionModalOpen} 
                        onClose={() => setIsTransactionModalOpen(false)} 
                        type={transactionType} 
                        profiles={brandFilteredProfiles} 
                        onAdd={addProfileTransaction} 
                        addToast={addToast} 
                        customers={activeCustomers} 
                        addCustomer={addCustomer}
                    />
                )}
            </Portal>
        </div>
    );
};

// Inline TransactionModal component
interface TransactionModalProps {
    isOpen: boolean;
    onClose: () => void;
    type: ProfileTransactionType;
    profiles: Profile[];
    onAdd: (tx: Omit<ProfileTransaction, 'id' | 'createdAt'>) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
    customers: Customer[];
    addCustomer: (c: Omit<Customer, 'id' | 'createdAt' | 'deletedAt'>) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ isOpen, onClose, type, profiles, onAdd, addToast, customers, addCustomer }) => {
    const [form, setForm] = useState({
        profileId: '',
        quantity: '',
        date: new Date().toISOString().split('T')[0],
        refNo: '',
        customer: '',
        uom: 'Pcs'
    });
    const [isNewCustomer, setIsNewCustomer] = useState(false);

    useEffect(() => {
        if(isOpen) {
            setForm({ profileId: '', quantity: '', date: new Date().toISOString().split('T')[0], refNo: '', customer: '', uom: 'Pcs' });
            setIsNewCustomer(false);
        }
    }, [isOpen]);

    if (!isOpen) return null;

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const qty = parseFloat(form.quantity);
        if(!form.profileId || isNaN(qty) || qty <= 0) {
            addToast('Please select a profile and enter a valid quantity.', 'error');
            return;
        }

        // If new customer typed, add it
        if (type === 'DISPATCH' && isNewCustomer && form.customer) {
            addCustomer({ name: form.customer });
        }

        onAdd({
            profileId: form.profileId,
            type: type,
            quantity: qty,
            uom: form.uom,
            date: new Date(form.date + 'T12:00:00.000Z').toISOString(),
            refNo: form.refNo,
            customer: type === 'DISPATCH' ? form.customer : undefined
        });
        addToast(`${type} transaction recorded.`, 'success');
        onClose();
    };

    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-md" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">Record {type}</h3>
                <form onSubmit={handleSubmit} className="space-y-3">
                    <select value={form.profileId} onChange={e => {
                        const p = profiles.find(pr => pr.id === e.target.value);
                        setForm({...form, profileId: e.target.value, uom: p?.uom || 'Pcs'});
                    }} className={inputClass} required>
                        <option value="" disabled>Select Profile</option>
                        {profiles.map(p => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}
                    </select>

                    <div className="flex gap-2">
                        <input type="number" placeholder="Quantity" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} required />
                        <input type="text" value={form.uom} readOnly className="w-20 bg-gray-100 dark:bg-gray-600 text-center border border-gray-300 dark:border-gray-500 rounded-md text-sm" />
                    </div>

                    <input type="text" placeholder="Reference No." value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} />
                    <input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required />

                    {type === 'DISPATCH' && (
                        <div className="relative">
                            <input 
                                list="customer-list" 
                                placeholder="Customer Name" 
                                value={form.customer} 
                                onChange={e => {
                                    setForm({...form, customer: e.target.value});
                                    const exists = customers.some(c => c.name.toLowerCase() === e.target.value.toLowerCase());
                                    setIsNewCustomer(!exists);
                                }} 
                                className={inputClass} 
                            />
                            <datalist id="customer-list">
                                {customers.map(c => <option key={c.id} value={c.name} />)}
                            </datalist>
                            {isNewCustomer && form.customer && <span className="text-xs text-blue-500 absolute right-2 top-2.5">New</span>}
                        </div>
                    )}

                    <div className="flex justify-end gap-2 mt-4">
                        <button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-700 dark:text-white">Cancel</button>
                        <button type="submit" className={`px-4 py-2 text-white rounded shadow ${
                            type === 'PRODUCTION' ? 'bg-green-600 hover:bg-green-700' :
                            type === 'DISPATCH' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-red-600 hover:bg-red-700'
                        }`}>Save</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

