const TransactionModal: React.FC<any> = ({ isOpen, onClose, type, profiles, onAdd, addToast, customers, addCustomer }) => {
    const [form, setForm] = useState({ profileId: profiles[0]?.id || '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' });
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    const selectedProfile = useMemo(() => profiles.find((p:any) => p.id === form.profileId), [profiles, form.profileId]);
    const totalWeight = useMemo(() => (!selectedProfile || !form.quantity) ? 0 : (selectedProfile.weight || 0) * parseFloat(form.quantity), [selectedProfile, form.quantity]);

    useEffect(() => { 
        if(isOpen) { 
            const firstProfileId = profiles[0]?.id || '';
            setForm(prev => ({...prev, profileId: firstProfileId, quantity: '', uom: 'Pcs', refNo: '', machine: '', die: ''})); 
            setPosition({ x: 0, y: 0 }); 
        } 
    }, [isOpen, profiles]);

    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;

    const filteredCustomers = customers.filter((c:any) => c.name.toLowerCase().includes(customerSearch.toLowerCase()) && !c.deletedAt);
    const selectCustomer = (c: any) => { setForm(prev => ({ ...prev, customer: c.name, customerAddress: c.address || '', customerGST: c.gstin || '', customerPhone: c.phone || '' })); setCustomerSearch(c.name); setShowSuggestions(false); };
    const handleSaveCustomer = () => { if (!form.customer) return; addCustomer({ name: form.customer, address: form.customerAddress, gstin: form.customerGST, phone: form.customerPhone }); addToast('Customer saved', 'success'); };
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); onAdd({ ...form, quantity: parseFloat(form.quantity), type }); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md flex flex-col max-h-[90vh] my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={onMouseDownHeader} className="px-6 py-4 bg-gray-900 text-white rounded-t-xl border-b border-gray-700 flex justify-between items-center shrink-0 cursor-move select-none relative z-10 min-h-[60px]">
                    <h2 className="text-xl font-bold">{type === 'DISPATCH' ? 'Record Dispatch' : type === 'SCRAP' ? 'Record Scrap' : 'Record Production'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl leading-none">&times;</button>
                </div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0">
                    <form onSubmit={handleSubmit} className="space-y-3">
