                        )}
                    </table>
                </div>
                <div className="mt-4 flex justify-end">
                    <button onClick={onClose} className="px-5 py-2 bg-gray-200 text-gray-800 dark:bg-gray-700 dark:text-white rounded-md hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors">Close</button>
                </div>
            </div>
        </div>
    );
};

