                    <input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} placeholder="Ref No"/>
                    <input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} placeholder="Qty"/>
                    {transaction.type === 'SCRAP' && <div className="grid grid-cols-2 gap-2"><input value={form.machine || ''} onChange={e => setForm({...form, machine: e.target.value})} className={inputClass} placeholder="Machine"/><input value={form.die || ''} onChange={e => setForm({...form, die: e.target.value})} className={inputClass} placeholder="Die"/></div>}
                    <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded">Update</button>
                </form>
            </div>
        </div>
    );
};

