const DashboardListModal: React.FC<{ isOpen: boolean; onClose: () => void; items: any[]; title: string; type?: 'value' | 'lowstock' | 'list' }> = ({ isOpen, onClose, items, title, type = 'list' }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const sortedItems = useMemo(() => {
        let sorted = [...items];
        if (type === 'value') {
            sorted.sort((a, b) => (b.currentStock * b.price) - (a.currentStock * a.price));
        } else if (type === 'lowstock') {
            sorted.sort((a, b) => a.currentStock - b.currentStock);
        } else {
            sorted.sort((a, b) => a.name.localeCompare(b.name));
        }
        return sorted;
    }, [items, type]);

    const filtered = useMemo(() => sortedItems.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [sortedItems, searchTerm]);

    const grandTotalValue = useMemo(() => type === 'value' ? filtered.reduce((acc, p) => acc + (p.currentStock * (p.price || 0)), 0) : 0, [filtered, type]);

    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
        if (isOpen) window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-3xl flex flex-col h-[80vh]" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        {type === 'lowstock' && <WarningIcon className="w-6 h-6 text-red-500" />}
                        {type === 'value' && <SparklesIcon className="w-6 h-6 text-green-500" />}
                        {title}
                    </h2>
                    <div className="relative">
                        <input autoFocus type="text" placeholder="Search..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md focus:ring-blue-500 focus:border-blue-500 w-64 dark:text-white" />
                        <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    </div>
                </div>
                <div className="overflow-y-auto flex-1 bg-gray-50 dark:bg-gray-900/50 rounded border dark:border-gray-700">
                    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="bg-gray-100 dark:bg-gray-700 text-xs uppercase text-gray-700 dark:text-gray-300 sticky top-0">
                            <tr>
                                <th className="px-6 py-3">SKU</th>
                                <th className="px-6 py-3">Name</th>
                                <th className="px-6 py-3 text-right">Stock</th>
                                {type === 'lowstock' && <th className="px-6 py-3 text-right">Reorder Pt</th>}
                                {type === 'value' && <th className="px-6 py-3 text-right">Price</th>}
                                {type === 'value' && <th className="px-6 py-3 text-right">Total Value</th>}
                            </tr>
                        </thead>
                        <tbody>
                            {filtered.length === 0 ? (
                                <tr><td colSpan={6} className="text-center py-8">No profiles found.</td></tr>
                            ) : (
                                filtered.map(p => (
                                    <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-white dark:hover:bg-gray-800">
                                        <td className="px-6 py-4 font-medium">{p.sku}</td>
                                        <td className="px-6 py-4">{p.name}</td>
                                        <td className={`px-6 py-4 text-right font-bold ${type === 'lowstock' ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}>
                                            {p.currentStock} <span className="text-xs font-normal text-gray-500">{p.uom}</span>
                                        </td>
                                        {type === 'lowstock' && <td className="px-6 py-4 text-right">{p.reorderPoint}</td>}
                                        {type === 'value' && <td className="px-6 py-4 text-right">{p.price?.toLocaleString()}</td>}
                                        {type === 'value' && <td className="px-6 py-4 text-right font-mono text-green-600 dark:text-green-400">{(p.currentStock * (p.price||0)).toLocaleString()}</td>}
                                    </tr>
                                ))
                            )}
                        </tbody>
                        {type === 'value' && (
                            <tfoot className="sticky bottom-0 bg-gray-100 dark:bg-gray-700 border-t dark:border-gray-600 font-bold text-gray-900 dark:text-white">
                                <tr>
                                    <td colSpan={4} className="px-6 py-3 text-right">Grand Total</td>
                                    <td className="px-6 py-3 text-right text-green-600 dark:text-green-400">{grandTotalValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })}</td>
