  { id: 'i2', sku: 'UPVC-RAW-002', name: 'Calcium Carbonate', uom: 'kg', reorderPoint: 500, createdAt: new Date().toISOString(), costPrice: 38.5 },
  { id: 'i3', sku: 'UPVC-RAW-003', name: 'Titanium Dioxide', uom: 'kg', reorderPoint: 100, createdAt: new Date().toISOString(), costPrice: 218.0 },
  { id: 'i4', sku: 'UPVC-RAW-004', name: 'Pigment', uom: 'kg', reorderPoint: 60, createdAt: new Date().toISOString(), costPrice: 55.0 },
