const TransactionModal: React.FC<any> = ({ isOpen, onClose, type, profiles, onAdd, addToast, customers, addCustomer }) => {
    const [form, setForm] = useState({ profileId: profiles[0]?.id || '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' });
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    const selectedProfile = useMemo(() => profiles.find((p:any) => p.id === form.profileId), [profiles, form.profileId]);
    const totalWeight = useMemo(() => (!selectedProfile || !form.quantity) ? 0 : (selectedProfile.weight || 0) * parseFloat(form.quantity), [selectedProfile, form.quantity]);

    useEffect(() => { 
        if(isOpen) { 
            const firstProfileId = profiles[0]?.id || '';
            setForm(prev => ({...prev, profileId: firstProfileId, quantity: '', uom: 'Pcs', refNo: '', machine: '', die: ''})); 
            setPosition({ x: 0, y: 0 }); 
        } 
    }, [isOpen, profiles]);

    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;

    const filteredCustomers = customers.filter((c:any) => c.name.toLowerCase().includes(customerSearch.toLowerCase()) && !c.deletedAt);
    const selectCustomer = (c: any) => { setForm(prev => ({ ...prev, customer: c.name, customerAddress: c.address || '', customerGST: c.gstin || '', customerPhone: c.phone || '' })); setCustomerSearch(c.name); setShowSuggestions(false); };
    const handleSaveCustomer = () => { if (!form.customer) return; addCustomer({ name: form.customer, address: form.customerAddress, gstin: form.customerGST, phone: form.customerPhone }); addToast('Customer saved', 'success'); };
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); onAdd({ ...form, quantity: parseFloat(form.quantity), type }); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md flex flex-col max-h-[90vh] my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={onMouseDownHeader} className="px-6 py-4 bg-gray-900 text-white rounded-t-xl border-b border-gray-700 flex justify-between items-center shrink-0 cursor-move select-none relative z-10 min-h-[60px]">
                    <h2 className="text-xl font-bold">{type === 'DISPATCH' ? 'Record Dispatch' : type === 'SCRAP' ? 'Record Scrap' : 'Record Production'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl leading-none">&times;</button>
                </div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0">
                    <form onSubmit={handleSubmit} className="space-y-3">
                        <div><label className="block text-xs font-medium dark:text-gray-300">Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required /></div>
                        <div>
                            <label className="block text-xs font-medium dark:text-gray-300">Profile</label>
                            <select value={form.profileId} onChange={e => setForm({...form, profileId: e.target.value})} className={inputClass}>
                                {profiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}
                            </select>
                            {selectedProfile && (
                                <div className="mt-2 p-2 bg-gray-5 dark:bg-gray-700/50 rounded border dark:border-gray-600 text-xs space-y-1">
                                    <div className="flex justify-between">
                                        <span>Specs:</span> 
                                        <span className="font-medium">{selectedProfile.length}m / {selectedProfile.weight}kg</span>
                                    </div>
                                    {selectedProfile.currentStock !== undefined && (
                                        <div className="flex justify-between">
                                            <span>Current Stock:</span> 
                                            <span className={`font-bold ${selectedProfile.currentStock < (selectedProfile.reorderPoint || 0) ? 'text-red-500' : 'text-gray-700 dark:text-gray-300'}`}>
                                                {selectedProfile.currentStock} {selectedProfile.uom}
                                            </span>
                                        </div>
                                    )}
                                    {selectedProfile.reorderPoint !== undefined && (
                                        <div className="flex justify-between">
                                            <span>Reorder Point:</span> 
                                            <span className="font-medium text-orange-600 dark:text-orange-400">{selectedProfile.reorderPoint}</span>
                                        </div>
                                    )}
                                    <div className="flex justify-between border-t border-gray-200 dark:border-gray-600 pt-1 mt-1">
                                        <span>Est. Total Weight:</span> 
                                        <span className="font-bold text-blue-600 dark:text-blue-400">{totalWeight.toLocaleString()} kg</span>
                                    </div>
                                </div>
                            )}
                        </div>
                        <div><label className="block text-xs font-medium dark:text-gray-300">Ref No.</label><input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} required /></div>
                        <div className="flex gap-2">
                            <div className="flex-1"><label className="block text-xs font-medium dark:text-gray-300">Quantity</label><input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} required /></div>
                            {type === 'SCRAP' && (
                                <div className="w-24">
                                    <label className="block text-xs font-medium dark:text-gray-300">Unit</label>
                                    <select value={form.uom} onChange={e => setForm({...form, uom: e.target.value})} className={inputClass}>
                                        <option value="Pcs">Pcs</option>
                                        <option value="Kgs">Kgs</option>
                                    </select>
                                </div>
                            )}
                        </div>
                        {type === 'SCRAP' && <div className="grid grid-cols-2 gap-2"><div><label className="block text-xs font-medium dark:text-gray-300">Machine No.</label><input value={form.machine} onChange={e => setForm({...form, machine: e.target.value})} className={inputClass} /></div><div><label className="block text-xs font-medium dark:text-gray-300">Die No.</label><input value={form.die} onChange={e => setForm({...form, die: e.target.value})} className={inputClass} /></div></div>}
                        {(type === 'DISPATCH') && <><div className="relative"><label className="block text-xs font-medium dark:text-gray-300">Customer Name (Search)</label><input value={form.customer} onChange={e => { setForm({...form, customer: e.target.value}); setCustomerSearch(e.target.value); setShowSuggestions(true); }} onFocus={() => setShowSuggestions(true)} className={inputClass} required placeholder="Type to search..." />{showSuggestions && customerSearch && filteredCustomers.length > 0 && (<div className="absolute z-20 w-full bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">{filteredCustomers.map((c:any) => (<div key={c.id} onClick={() => selectCustomer(c)} className="px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-600 cursor-pointer text-sm"><div className="font-medium">{c.name}</div><div className="text-xs text-gray-500">{c.phone}</div></div>))}</div>)}</div><div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded border dark:border-gray-700 space-y-2"><div className="flex justify-between items-center"><p className="text-xs font-bold text-gray-500">Customer Details</p><button type="button" onClick={handleSaveCustomer} className="text-xs text-blue-600 hover:underline flex items-center gap-1"><UserPlusIcon className="w-3 h-3"/> Save Customer</button></div><input placeholder="Address" value={form.customerAddress} onChange={e => setForm({...form, customerAddress: e.target.value})} className={inputClass}/><div className="grid grid-cols-2 gap-2"><input placeholder="GSTIN" value={form.customerGST} onChange={e => setForm({...form, customerGST: e.target.value})} className={inputClass}/><input placeholder="Mobile" value={form.customerPhone} onChange={e => setForm({...form, customerPhone: e.target.value})} className={inputClass}/></div></div></>}
                        <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save</button></div>
                    </form>
                </div>
            </div>
        </div>
    );
};

