const DashboardListModal: React.FC<{ isOpen: boolean; onClose: () => void; items: any[]; title: string; type?: 'value' | 'lowstock' | 'list' }> = ({ isOpen, onClose, items, title, type = 'list' }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const sortedItems = useMemo(() => {
        let sorted = [...items];
        if (type === 'value') {
            sorted.sort((a, b) => (b.currentStock * b.price) - (a.currentStock * a.price));
        } else if (type === 'lowstock') {
            sorted.sort((a, b) => a.currentStock - b.currentStock);
        } else {
            sorted.sort((a, b) => a.name.localeCompare(b.name));
        }
        return sorted;
    }, [items, type]);

    const filtered = useMemo(() => sortedItems.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [sortedItems, searchTerm]);

    const grandTotalValue = useMemo(() => type === 'value' ? filtered.reduce((acc, p) => acc + (p.currentStock * (p.price || 0)), 0) : 0, [filtered, type]);

    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
        if (isOpen) window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-3xl flex flex-col h-[80vh]" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        {type === 'lowstock' && <WarningIcon className="w-6 h-6 text-red-500" />}
                        {type === 'value' && <SparklesIcon className="w-6 h-6 text-green-500" />}
                        {title}
                    </h2>
                    <div className="relative">
                        <input autoFocus type="text" placeholder="Search..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md focus:ring-blue-500 focus:border-blue-500 w-64 dark:text-white" />
                        <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    </div>
                </div>
                <div className="overflow-y-auto flex-1 bg-gray-50 dark:bg-gray-900/50 rounded border dark:border-gray-700">
                    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="bg-gray-100 dark:bg-gray-700 text-xs uppercase text-gray-700 dark:text-gray-300 sticky top-0">
                            <tr>
                                <th className="px-6 py-3">SKU</th>
                                <th className="px-6 py-3">Name</th>
                                <th className="px-6 py-3 text-right">Stock</th>
                                {type === 'lowstock' && <th className="px-6 py-3 text-right">Reorder Pt</th>}
                                {type === 'value' && <th className="px-6 py-3 text-right">Price</th>}
                                {type === 'value' && <th className="px-6 py-3 text-right">Total Value</th>}
                            </tr>
                        </thead>
                        <tbody>
                            {filtered.length === 0 ? (
                                <tr><td colSpan={6} className="text-center py-8">No profiles found.</td></tr>
                            ) : (
                                filtered.map(p => (
                                    <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-white dark:hover:bg-gray-800">
                                        <td className="px-6 py-4 font-medium">{p.sku}</td>
                                        <td className="px-6 py-4">{p.name}</td>
                                        <td className={`px-6 py-4 text-right font-bold ${type === 'lowstock' ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}>
                                            {p.currentStock} <span className="text-xs font-normal text-gray-500">{p.uom}</span>
                                        </td>
                                        {type === 'lowstock' && <td className="px-6 py-4 text-right">{p.reorderPoint}</td>}
                                        {type === 'value' && <td className="px-6 py-4 text-right">{p.price?.toLocaleString()}</td>}
                                        {type === 'value' && <td className="px-6 py-4 text-right font-mono text-green-600 dark:text-green-400">{(p.currentStock * (p.price||0)).toLocaleString()}</td>}
                                    </tr>
                                ))
                            )}
                        </tbody>
                        {type === 'value' && (
                            <tfoot className="sticky bottom-0 bg-gray-100 dark:bg-gray-700 border-t dark:border-gray-600 font-bold text-gray-900 dark:text-white">
                                <tr>
                                    <td colSpan={4} className="px-6 py-3 text-right">Grand Total</td>
                                    <td className="px-6 py-3 text-right text-green-600 dark:text-green-400">{grandTotalValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })}</td>
                                </tr>
                            </tfoot>
                        )}
                    </table>
                </div>
                <div className="mt-4 flex justify-end">
                    <button onClick={onClose} className="px-5 py-2 bg-gray-200 text-gray-800 dark:bg-gray-700 dark:text-white rounded-md hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors">Close</button>
                </div>
            </div>
        </div>
    );
};

// --- DASHBOARD COMPONENT ---
const ProfileDashboard: React.FC<{ 
    profiles: Profile[], 
    transactions: ProfileTransaction[], 
    stockData: any[] 
}> = ({ profiles, transactions, stockData }) => {
    const chartRef1 = useRef<HTMLCanvasElement>(null);
    const chartRef2 = useRef<HTMLCanvasElement>(null);
    const chartInstance1 = useRef<any>(null);
    const chartInstance2 = useRef<any>(null);

    const [isListOpen, setIsListOpen] = useState(false);
    const [isLowStockOpen, setIsLowStockOpen] = useState(false);
    const [isValueOpen, setIsValueOpen] = useState(false);

    const totalProfiles = profiles.length;
    const lowStockItems = useMemo(() => stockData.filter(p => p.currentStock < (p.reorderPoint || 0)), [stockData]);
    const lowStockCount = lowStockItems.length;
    const totalStockValue = stockData.reduce((acc, p) => acc + (p.currentStock * (p.price || 0)), 0);

    const currentMonth = new Date().toISOString().slice(0, 7); 
    const currentMonthDispatch = transactions
        .filter(t => t.type === 'DISPATCH' && t.date.startsWith(currentMonth))
        .reduce((sum, t) => sum + t.quantity, 0);

    useEffect(() => {
        if (typeof Chart === 'undefined') return;

        const isDarkMode = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        const textColor = isDarkMode ? '#E5E7EB' : '#374151';
        const gridColor = isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)';

        const topValueProfiles = [...stockData]
            .map(p => ({ name: p.name, value: p.currentStock * (p.price || 0) }))
            .sort((a, b) => b.value - a.value)
            .slice(0, 5);

        if (chartRef1.current) {
            if (chartInstance1.current) chartInstance1.current.destroy();
            const ctx1 = chartRef1.current.getContext('2d');
            if (ctx1) {
                chartInstance1.current = new Chart(ctx1, {
                    type: 'doughnut',
                    data: {
                        labels: topValueProfiles.map(p => p.name),
                        datasets: [{
                            data: topValueProfiles.map(p => p.value),
                            backgroundColor: ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'],
                            borderColor: isDarkMode ? '#1F2937' : '#FFFFFF',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { 
                            legend: { position: 'right', labels: { color: textColor } },
                            title: { display: false }
                        }
                    }
                });
            }
        }

        const last6Months = [];
        for (let i = 5; i >= 0; i--) {
            const d = new Date();
            d.setMonth(d.getMonth() - i);
            last6Months.push(d.toISOString().slice(0, 7)); 
        }

        const productionData = last6Months.map(month => 
            transactions.filter(t => (t.type === 'PRODUCTION' || t.type === 'RETURN') && t.date.startsWith(month)).reduce((sum, t) => sum + t.quantity, 0)
        );
        const dispatchData = last6Months.map(month => 
            transactions.filter(t => t.type === 'DISPATCH' && t.date.startsWith(month)).reduce((sum, t) => sum + t.quantity, 0)
        );
        const labels = last6Months.map(m => new Date(m + '-01').toLocaleString('default', { month: 'short' }));

        if (chartRef2.current) {
            if (chartInstance2.current) chartInstance2.current.destroy();
            const ctx2 = chartRef2.current.getContext('2d');
            if (ctx2) {
                chartInstance2.current = new Chart(ctx2, {
                    type: 'bar',
                    data: {
                        labels: labels,
                        datasets: [
                            { label: 'Production', data: productionData, backgroundColor: '#10B981' },
                            { label: 'Dispatch', data: dispatchData, backgroundColor: '#EF4444' }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        scales: {
                            y: { ticks: { color: textColor }, grid: { color: gridColor } },
                            x: { ticks: { color: textColor }, grid: { color: gridColor } }
                        },
                        plugins: { legend: { position: 'top', labels: { color: textColor } } }
                    }
                });
            }
        }

        return () => {
            if(chartInstance1.current) chartInstance1.current.destroy();
            if(chartInstance2.current) chartInstance2.current.destroy();
        };
    }, [stockData, transactions]);

    return (
        <div className="space-y-6 animate-fade-in-right">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <button onClick={() => setIsListOpen(true)} className="text-left focus:outline-none hover:scale-105 transition-transform duration-200">
                    <Card className="h-full">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Profiles</p>
                                <p className="text-3xl font-bold text-gray-900 dark:text-white mt-1">{totalProfiles}</p>
                            </div>
                            <div className="p-3 bg-blue-100 dark:bg-blue-900/30 rounded-full">
                                <WarehouseIcon className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                            </div>
                        </div>
                    </Card>
                </button>
                <button onClick={() => setIsLowStockOpen(true)} className="text-left focus:outline-none hover:scale-105 transition-transform duration-200">
                    <Card className="h-full border-l-4 border-l-transparent hover:border-l-red-500">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Low Stock Alerts</p>
                                <p className={`text-3xl font-bold mt-1 ${lowStockCount > 0 ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}>{lowStockCount}</p>
                            </div>
                            <div className={`p-3 rounded-full ${lowStockCount > 0 ? 'bg-red-100 dark:bg-red-900/30' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                <WarningIcon className={`w-6 h-6 ${lowStockCount > 0 ? 'text-red-500' : 'text-gray-400'}`} />
                            </div>
                        </div>
                    </Card>
                </button>
                <button onClick={() => setIsValueOpen(true)} className="text-left focus:outline-none hover:scale-105 transition-transform duration-200">
                    <Card className="h-full">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Stock Value</p>
                                <p className="text-3xl font-bold text-green-600 dark:text-green-400 mt-1">
                                    {totalStockValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })}
                                </p>
                            </div>
                            <div className="p-3 bg-green-100 dark:bg-green-900/30 rounded-full">
                                <SparklesIcon className="w-6 h-6 text-green-600 dark:text-green-400" />
                            </div>
                        </div>
                    </Card>
                </button>
                <Card className="h-full">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Dispatch (This Month)</p>
                            <p className="text-3xl font-bold text-purple-600 dark:text-purple-400 mt-1">{currentMonthDispatch.toLocaleString()}</p>
                        </div>
                        <div className="p-3 bg-purple-100 dark:bg-purple-900/30 rounded-full">
                            <UserIcon className="w-6 h-6 text-purple-600 dark:text-purple-400" />
                        </div>
                    </div>
                </Card>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <Card className="h-96">
                    <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Production vs Dispatch (6 Months)</h3>
                    <div className="h-72 w-full">
                        <canvas ref={chartRef2}></canvas>
                    </div>
                </Card>
                <Card className="h-96">
                    <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Top 5 Profiles by Stock Value</h3>
                    <div className="h-72 w-full">
                        <canvas ref={chartRef1}></canvas>
                    </div>
                </Card>
            </div>

            <Portal><DashboardListModal isOpen={isListOpen} onClose={() => setIsListOpen(false)} items={stockData} title="All Profiles" type="list" /></Portal>
            <Portal><DashboardListModal isOpen={isLowStockOpen} onClose={() => setIsLowStockOpen(false)} items={lowStockItems} title="Low Stock Profiles" type="lowstock" /></Portal>
            <Portal><DashboardListModal isOpen={isValueOpen} onClose={() => setIsValueOpen(false)} items={stockData} title="Profile Stock Value" type="value" /></Portal>
        </div>
    );
};

