    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { if(isOpen) { setForm(settings); setLogoPreview(settings.logoUrl || ''); setPosition({ x: 0, y: 0 }); } }, [isOpen, settings]);
    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;
    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (file) { const reader = new FileReader(); reader.onloadend = () => { const result = reader.result as string; setForm({ ...form, logoUrl: result }); setLogoPreview(result); }; reader.readAsDataURL(file); } };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white p-2 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none";
    const labelClass = "block text-xs font-medium mb-1 text-gray-700 dark:text-gray-300";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={onMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]"><h2 className="text-xl font-bold flex items-center gap-2"><WarehouseIcon className="w-6 h-6 text-blue-400"/> Company Settings</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button></div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                    <div className="flex flex-col items-center p-6 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 mb-6">
                        <div className="w-48 h-32 bg-white dark:bg-black/20 border border-gray-300 dark:border-gray-600 rounded-lg flex items-center justify-center overflow-hidden mb-4 shadow-sm">{logoPreview ? <img src={logoPreview} alt="Logo" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-400 text-xs">No Logo</span>}</div>
                        <label className="cursor-pointer bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-bold hover:bg-blue-700 flex gap-2"><CloudUploadIcon className="w-4 h-4"/> Upload Logo <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" /></label>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">General Info</h3><div><label className={labelClass}>Company Name</label><input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>GSTIN</label><input value={form.gstin} onChange={e => setForm({...form, gstin: e.target.value})} className={inputClass} /></div><div className="grid grid-cols-2 gap-3"><div><label className={labelClass}>Phone</label><input value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Email</label><input value={form.email} onChange={e => setForm({...form, email: e.target.value})} className={inputClass} /></div></div></div>
                        <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">Address</h3><div><label className={labelClass}>Address Line 1</label><input value={form.addressLine1} onChange={e => setForm({...form, addressLine1: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Address Line 2</label><input value={form.addressLine2} onChange={e => setForm({...form, addressLine2: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>City, State, Zip</label><input value={form.cityStateZip} onChange={e => setForm({...form, cityStateZip: e.target.value})} className={inputClass} /></div></div>
                    </div>
                    <div className="mt-6 space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">Bank & Terms</h3><div className="grid grid-cols-2 gap-4"><div><label className={labelClass}>Bank Name</label><input value={form.bankName} onChange={e => setForm({...form, bankName: e.target.value})} className={inputClass} /></div><div><label className="block text-xs font-medium mb-1 text-gray-700 dark:text-gray-300">Account No.</label><input value={form.accountNo} onChange={e => setForm({...form, accountNo: e.target.value})} className="w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white p-2 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none" /></div><div><label className={labelClass}>IFSC</label><input value={form.ifsc} onChange={e => setForm({...form, ifsc: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Branch</label><input value={form.branch} onChange={e => setForm({...form, branch: e.target.value})} className={inputClass} /></div></div><div><label className={labelClass}>Terms & Conditions</label><textarea value={form.terms} onChange={e => setForm({...form, terms: e.target.value})} rows={3} className={inputClass}></textarea></div></div>
                </div>
                <div className="p-4 bg-gray-100 dark:bg-gray-700 rounded-b-xl flex justify-end gap-3 shrink-0 border-t border-gray-200 dark:border-gray-600"><button type="button" onClick={onClose} className="px-5 py-2 bg-white dark:bg-gray-600 border rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 text-gray-700 dark:text-white transition-colors">Cancel</button><button type="button" onClick={() => { updateSettings(form); addToast('Settings Saved!', 'success'); onClose(); }} className="px-6 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 shadow transition-colors font-bold">Save Settings</button></div>
            </div>
        </div>
    );
};

const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const [activeTab, setActiveTab] = useState<Tab>('Dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState('All');

    // Modals state
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [transactionType, setTransactionType] = useState<'PRODUCTION' | 'DISPATCH' | 'SCRAP'>('PRODUCTION');
    const [editingTransaction, setEditingTransaction] = useState<ProfileTransaction | null>(null);
    const [isQuotationModalOpen, setIsQuotationModalOpen] = useState(false);
    const [editingQuotation, setEditingQuotation] = useState<ProfileTransaction[] | null>(null);
    const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
    const [isManageBrandsModalOpen, setIsManageBrandsModalOpen] = useState(false);
    const [planningTimeFilter, setPlanningTimeFilter] = useState<'3M' | '6M' | '12M' | 'ALL'>('3M');

    // Data from store - SPLIT TO AVOID OBJECT IDENTITY CHANGE ON EVERY RENDER
    const allProfiles = useStore(state => state.profiles);
    const allTransactions = useStore(state => state.profileTransactions);
    const allCustomers = useStore(state => state.customers);
    const brands = useStore(state => state.brands);
    const companySettings = useStore(state => state.companySettings);

    const { addProfile, updateProfile, deleteProfile, addProfileTransaction, updateProfileTransaction, deleteProfileTransaction, resolveQuotation, addCustomer, updateCustomer, deleteCustomer, addBrand, updateBrand, deleteBrand, updateCompanySettings } = useStore();

    // Memoized Filters
    const profiles = useMemo(() => allProfiles.filter(p => !p.deletedAt), [allProfiles]);
    const profileTransactions = useMemo(() => allTransactions.filter(t => !t.deletedAt), [allTransactions]);
    const customers = useMemo(() => allCustomers.filter(c => !c.deletedAt), [allCustomers]);

    // BRAND FILTER LOGIC
    const brandFilteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return profiles;
        return profiles.filter(p => p.brand === brandFilter);
    }, [profiles, brandFilter]);

    // Memoized Lookups & Derived Data
    const profileMap = useMemo(() => new Map(profiles.map(p => [p.id, p])), [profiles]);
    const getProfile = useCallback((id: string) => profileMap.get(id), [profileMap]);
    const getProfileName = useCallback((id: string) => profileMap.get(id)?.name || 'Unknown', [profileMap]);
    const getProfileSpecs = useCallback((id: string) => { const p = profileMap.get(id); return p ? `${p.length || '?'}m, ${p.weight || '?'}kg` : ''; }, [profileMap]);
    const getBrandBadge = useCallback((brand: string) => <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-white border border-gray-200 text-gray-800 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-300">{brand || '-'}</span>, []);

    const profileStocks = useMemo(() => {
        const stockMap = new Map<string, number>();
        profiles.forEach(p => {
            const production = profileTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatchAndScrap = profileTransactions.filter(t => t.profileId === p.id && (t.type === 'DISPATCH' || t.type === 'SCRAP')).reduce((sum, t) => sum + t.quantity, 0);
            stockMap.set(p.id, production - dispatchAndScrap);
        });
        return stockMap;
    }, [profiles, profileTransactions]);

    const quotationReservedStock = useMemo(() => {
        const reserved = new Map<string, number>();
        profileTransactions.filter(t => t.type === 'QUOTATION' && t.status === 'PENDING').forEach(t => {
            reserved.set(t.profileId, (reserved.get(t.profileId) || 0) + t.quantity);
        });
        return reserved;
    }, [profileTransactions]);

    // Updated stockData to respect brand filter
    const stockData = useMemo(() => {
        return brandFilteredProfiles.map(p => ({
            ...p,
            currentStock: profileStocks.get(p.id) || 0,
            reservedStock: quotationReservedStock.get(p.id) || 0,
        }));
    }, [brandFilteredProfiles, profileStocks, quotationReservedStock]);

    const filteredProfiles = useMemo(() => stockData.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [stockData, searchTerm]);

    // Updated transaction filtering to respect brand filter
    const brandFilteredTransactions = useMemo(() => {
        if (brandFilter === 'All') return profileTransactions;
        const validIds = new Set(brandFilteredProfiles.map(p => p.id));
        return profileTransactions.filter(t => validIds.has(t.profileId));
    }, [profileTransactions, brandFilteredProfiles, brandFilter]);

    const productionTransactions = useFilteredTransactions(brandFilteredTransactions, brandFilteredProfiles, searchTerm, getProfile, 'PRODUCTION');
    const dispatchTransactions = useFilteredTransactions(brandFilteredTransactions, brandFilteredProfiles, searchTerm, getProfile, 'DISPATCH');
    const scrapTransactions = useFilteredTransactions(brandFilteredTransactions, brandFilteredProfiles, searchTerm, getProfile, 'SCRAP');

    const groupedQuotations = useMemo(() => {
        const groups: { [key: string]: any } = {};
        profileTransactions.filter(t => t.type === 'QUOTATION').forEach(t => {
            const groupKey = t.refNo;
            if (!groups[groupKey]) {
                groups[groupKey] = {
                    refNo: t.refNo,
                    customer: t.customer,
                    date: t.date,
                    status: t.status,
                    totalAmount: 0,
                    items: [],
                    brand: getProfile(t.profileId)?.brand,
                    invoiceDetails: t.invoiceDetails
                };
            }
            groups[groupKey].items.push(t);
            groups[groupKey].totalAmount = t.invoiceDetails?.totalAmount || groups[groupKey].totalAmount + (t.unitPrice! * t.quantity);
        });

        const allQuotes = Object.values(groups).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

        if (brandFilter !== 'All') {
            return allQuotes.filter(g => g.brand === brandFilter);
        }
        return allQuotes;
    }, [profileTransactions, getProfile, brandFilter]);

    // Planning Data
    const planningData = useMemo(() => {
        let thresholdDate: Date | null = null;
        if (planningTimeFilter !== 'ALL') {
            const months = { '3M': 3, '6M': 6, '12M': 12 };
            thresholdDate = new Date();
            thresholdDate.setMonth(thresholdDate.getMonth() - months[planningTimeFilter]);
        }

        // Note: Using brandFilteredTransactions ensures sales percentage is relative to visible brand sales if desired,
        // or use 'profileTransactions' for global share. Here we use filtered for consistency.
        const periodTxns = thresholdDate ? brandFilteredTransactions.filter(t => new Date(t.date) >= thresholdDate!) : brandFilteredTransactions;

        const totalSales = periodTxns.filter(t => t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);

        return stockData.map(p => {
            const periodSales = periodTxns.filter(t => t.type === 'DISPATCH' && t.profileId === p.id).reduce((sum, t) => sum + t.quantity, 0);
            return { ...p, periodSales, sharePercentage: totalSales > 0 ? (periodSales / totalSales) * 100 : 0 };
        }).sort((a, b) => b.periodSales - a.periodSales);
    }, [stockData, brandFilteredTransactions, planningTimeFilter]);

    // HANDLERS
    const handleAddProfile = (data: Omit<Profile, 'id' | 'createdAt'>) => { addProfile(data); addToast('Profile Added!', 'success'); };
    const handleUpdateProfile = (data: Profile) => { updateProfile(data); addToast('Profile Updated!', 'success'); };
    const handleDeleteProfile = (id: string) => { deleteProfile(id); addToast('Profile Deleted!', 'info'); };

    const handleAddCustomer = (data: any) => { addCustomer(data); };
    const handleUpdateCustomer = (data: any) => { updateCustomer(data); };
    const handleDeleteCustomer = (id: string) => { deleteCustomer(id); addToast('Customer Deleted!', 'info'); };

    const handleAddTransaction = (data: any) => { addProfileTransaction(data); addToast(`${data.type} recorded!`, 'success'); };
    const handleUpdateTransaction = (data: any) => { updateProfileTransaction(data); addToast('Record updated!', 'success'); };
    const handleDeleteTransaction = (id: string) => { deleteProfileTransaction(id); addToast('Record deleted!', 'info'); };

    // UPDATED HANDLER: Confirm all pending items for the quotation
    const handleQuotationAction = (refNo: string, action: 'CONFIRM_DISPATCH' | 'CONFIRM_RETURN' | 'CANCEL') => {
        // Find ALL items belonging to this quotation that are still pending
        const items = profileTransactions.filter(t => t.refNo === refNo && t.type === 'QUOTATION' && t.status === 'PENDING');

        if (items.length === 0) {
            addToast('No pending items found for this quotation.', 'info');
            return;
        }

        // Process each item individually
        items.forEach(t => {
            resolveQuotation(t.id, action);
        });

        const actionVerb = action === 'CANCEL' ? 'Cancelled' : action === 'CONFIRM_RETURN' ? 'Reversed (Stock +)' : 'Confirmed (Stock -)';
        addToast(`Quotation ${actionVerb}! All items processed.`, 'success');
    };

    const handleDeleteQuotation = (refNo: string) => {
        const itemsToDelete = profileTransactions.filter(t => t.refNo === refNo && t.type === 'QUOTATION');
        itemsToDelete.forEach(t => deleteProfileTransaction(t.id));
        addToast(`Quotation ${refNo} deleted!`, 'info');
    };

    const TABS: Tab[] = ['Dashboard', 'Stock', 'Planning', 'Production', 'Dispatch', 'Scrap', 'Quotations', 'Profiles', 'Customers'];

    return (
        <div>
            {/* Header with Title and Global Filters */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto items-end sm:items-center">

                    {/* Filters Group */}
                    <div className="flex items-center gap-2 bg-white dark:bg-gray-800 p-1 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm">
                        {['Stock', 'Production', 'Dispatch', 'Scrap', 'Profiles', 'Customers'].includes(activeTab) && (
                            <div className="relative">
                                <input 
                                    type="text" 
                                    placeholder="Search..." 
                                    value={searchTerm} 
                                    onChange={e => setSearchTerm(e.target.value)} 
                                    className="pl-7 pr-2 py-1 border-none bg-transparent focus:ring-0 w-32 sm:w-48 text-sm text-gray-700 dark:text-gray-200 placeholder-gray-400" 
                                />
                                <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            </div>
                        )}

                        {/* Vertical Separator */}
                        {['Stock', 'Production', 'Dispatch', 'Scrap', 'Profiles', 'Customers'].includes(activeTab) && <div className="h-6 w-px bg-gray-300 dark:bg-gray-600 mx-1"></div>}

                        <select 
                            value={brandFilter} 
                            onChange={(e) => setBrandFilter(e.target.value)} 
                            className="bg-transparent border-none text-sm font-medium focus:ring-0 cursor-pointer text-gray-900 dark:text-white pr-8 outline-none"
                            title="Filter by Brand"
                        >
                            <option value="All">All Brands</option>
                            {brands.map(b => <option key={b} value={b}>{b}</option>)}
                        </select>

                        {activeTab === 'Planning' && (
                             <select value={planningTimeFilter} onChange={e => setPlanningTimeFilter(e.target.value as any)} className="bg-transparent border-none text-sm font-medium focus:ring-0 cursor-pointer text-gray-900 dark:text-white outline-none">
                                <option value="3M">3 Months</option><option value="6M">6 Months</option><option value="12M">12 Months</option><option value="ALL">All Time</option>
                            </select>
                        )}
                    </div>

                    {/* Actions Group */}
                    <div className="flex items-center gap-2">
                        <button onClick={() => setIsManageBrandsModalOpen(true)} className="p-2 text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-sm transition-all" title="Manage Brands">
                            <PencilIcon className="w-4 h-4" />
                        </button>
                        <button onClick={() => setIsSettingsModalOpen(true)} className="p-2 text-gray-500 hover:text-gray-800 dark:hover:text-white bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-sm transition-all" title="Settings">
                            <span className="text-sm font-bold">⚙️</span>
                        </button>

                        {/* Primary Action Button (Context Aware) */}
                        {activeTab === 'Production' && (
                            <button onClick={() => { setTransactionType('PRODUCTION'); setIsTransactionModalOpen(true); }} className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-green-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Production
                            </button>
                        )}
                        {activeTab === 'Dispatch' && (
                            <button onClick={() => { setTransactionType('DISPATCH'); setIsTransactionModalOpen(true); }} className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-red-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Dispatch
                            </button>
                        )}
                        {activeTab === 'Scrap' && (
                            <button onClick={() => { setTransactionType('SCRAP'); setIsTransactionModalOpen(true); }} className="bg-orange-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-orange-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Scrap
                            </button>
                        )}
                        {activeTab === 'Profiles' && (
                            <button onClick={() => setIsProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Add Profile
                            </button>
                        )}
                        {activeTab === 'Customers' && (
                            <button onClick={() => setIsCustomerModalOpen(true)} className="bg-purple-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-purple-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Add Customer
                            </button>
                        )}
                        {activeTab === 'Quotations' && (
                            <button onClick={() => setIsQuotationModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + New Quotation
                            </button>
                        )}
                    </div>
                </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 no-print">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {TABS.map(tab => <button key={tab} onClick={() => setActiveTab(tab)} className={`${activeTab === tab ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}>{tab}</button>)}
                </nav>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                {activeTab === 'Dashboard' && <ProfileDashboard profiles={brandFilteredProfiles} transactions={brandFilteredTransactions} stockData={stockData} />}
                {activeTab === 'Stock' && <StockTable stockData={filteredProfiles} onEditProfile={(p:Profile) => {setEditingProfile(p); setIsProfileModalOpen(true);}} getBrandBadge={getBrandBadge} />}
                {activeTab === 'Planning' && <PlanningTable planningData={planningData} getBrandBadge={getBrandBadge} planningTimeFilter={planningTimeFilter} />}
                {activeTab === 'Production' && <TransactionTable transactions={productionTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} type="PRODUCTION" getBrandBadge={getBrandBadge} getProfile={getProfile} />}
                {activeTab === 'Dispatch' && <TransactionTable transactions={dispatchTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} type="DISPATCH" getBrandBadge={getBrandBadge} getProfile={getProfile} />}
                {activeTab === 'Scrap' && <TransactionTable transactions={scrapTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} type="SCRAP" getBrandBadge={getBrandBadge} getProfile={getProfile} />}
                {activeTab === 'Quotations' && <div id="profile-quotations-table"><QuotationTable groupedQuotations={groupedQuotations} onAction={handleQuotationAction} onEdit={(refNo:string) => { setEditingQuotation(profileTransactions.filter(t => t.refNo === refNo)); setIsQuotationModalOpen(true); }} onDelete={handleDeleteQuotation} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Profiles' && <ProfileListTable profiles={filteredProfiles} onEdit={(p:Profile) => { setEditingProfile(p); setIsProfileModalOpen(true); }} onDelete={handleDeleteProfile} getBrandBadge={getBrandBadge} />}
                {activeTab === 'Customers' && <CustomerTable customers={customers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()))} onEdit={(c:Customer) => { setEditingCustomer(c); setIsCustomerModalOpen(true); }} onDelete={handleDeleteCustomer} />}
            </div>

            <Portal><AddProfileModal isOpen={isProfileModalOpen} onClose={() => {setIsProfileModalOpen(false); setEditingProfile(null);}} onAdd={editingProfile ? (data) => handleUpdateProfile({...editingProfile, ...data}) : handleAddProfile} brands={brands} addToast={addToast} initialData={editingProfile} /></Portal>
            <Portal><CustomerModal isOpen={isCustomerModalOpen} onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} onSave={editingCustomer ? (data) => handleUpdateCustomer({...editingCustomer, ...data}) : handleAddCustomer} customer={editingCustomer} addToast={addToast} /></Portal>
            <Portal><TransactionModal isOpen={isTransactionModalOpen} onClose={() => { setIsTransactionModalOpen(false); setEditingTransaction(null); }} type={transactionType} profiles={stockData} onAdd={handleAddTransaction} addToast={addToast} customers={customers} addCustomer={addCustomer} /></Portal>
            <Portal><EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} onUpdate={handleUpdateTransaction} /></Portal>
            <Portal><CreateQuotationModal isOpen={isQuotationModalOpen} onClose={() => {setIsQuotationModalOpen(false); setEditingQuotation(null);}} profiles={profiles} customers={customers} onAddMultiple={(txs) => { txs.forEach(tx => addProfileTransaction(tx))}} addToast={addToast} existingTransactions={editingQuotation} /></Portal>
            <Portal><CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} addToast={addToast} /></Portal>
            <Portal><ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
        </div>
    );
};

export default ProfileSection;

import React, { useState, useEffect, useMemo } from 'react';
import type { Profile, ProfileTransaction, InvoiceDetails, Customer, ToastMessage } from '../types';
import { TrashIcon, PencilIcon } from './Icon';

interface CreateQuotationModalProps {
    isOpen: boolean;
    onClose: () => void;
    profiles: Profile[];
    customers: Customer[];
    onAddMultiple: (txs: Omit<ProfileTransaction, 'id' | 'createdAt'>[]) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
    existingTransactions?: ProfileTransaction[];
    brands: string[];
    addBrand: (brand: string) => void;
    deleteBrand: (brand: string) => void;
}

interface QuotationItem {
    id: number;
    profileId: string;
    quantity: number;
    price: number;
    amount: number;
}

const CreateQuotationModal: React.FC<CreateQuotationModalProps> = ({ isOpen, onClose, profiles, customers, onAddMultiple, addToast, existingTransactions, brands, addBrand, deleteBrand }) => {
    const [invoiceData, setInvoiceData] = useState<InvoiceDetails>({
        category: 'Tax Invoice',
        reverseCharge: 'No',
        documentType: 'Tax Invoice',
        documentNo: '',
        documentDate: new Date().toISOString().split('T')[0],
        legalName: '',
        address1: '',
        address2: '',
        location: '',
        pincode: '',
        phone: '',
        gstin: '',
        state: 'Telangana',
        email: '',
        placeOfSupply: 'Telangana',
        igstOnIntra: 'No',
        transactionType: 'Regular',
        totalTaxable: 0,
        igstValue: 0,
        sgstValue: 0,
        cgstValue: 0,
        cessAdvolValue: 0,
        cessNonAdValue: 0,
        stateCessValue: 0,
        totalAmount: 0
    });

    const [items, setItems] = useState<QuotationItem[]>([]);
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [brandFilter, setBrandFilter] = useState('All');
    const [isManageBrandsModalOpen, setIsManageBrandsModalOpen] = useState(false);

    // Use passed brands for the filter dropdown
    const availableBrands = useMemo(() => {
        return ['All', ...brands];
    }, [brands]);

    // Filter profiles based on brand selection
    const filteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return profiles;
        return profiles.filter(p => p.brand === brandFilter);
    }, [profiles, brandFilter]);

    useEffect(() => {
        if (isOpen) {
            setBrandFilter('All');
            if (existingTransactions && existingTransactions.length > 0) {
                // Populate from existing transactions
                const first = existingTransactions[0];
                if (first.invoiceDetails) {
                    setInvoiceData(first.invoiceDetails);
                    setCustomerSearch(first.invoiceDetails.legalName);
                } else {
                    // Fallback for legacy data
                    setInvoiceData(prev => ({
                        ...prev,
                        documentNo: first.refNo,
                        legalName: first.customer || '',
                        documentDate: first.date.split('T')[0]
                    }));
                    setCustomerSearch(first.customer || '');
                }

                const mappedItems = existingTransactions.map((tx, idx) => ({
                    id: Date.now() + idx,
                    profileId: tx.profileId,
                    quantity: tx.quantity,
                    price: tx.unitPrice || 0,
                    amount: (tx.quantity * (tx.unitPrice || 0))
                }));
                setItems(mappedItems);

            } else {
                // New Quotation
                setInvoiceData(prev => ({
                    ...prev,
                    documentNo: `INV-${Date.now().toString().slice(-6)}`,
                    documentDate: new Date().toISOString().split('T')[0],
                    legalName: '',
                    address1: '',
                    address2: '',
                    location: '',
                    pincode: '',
                    phone: '',
                    gstin: '',
                    state: 'Telangana',
                    email: '',
                    placeOfSupply: 'Telangana',
                    totalTaxable: 0,
                    igstValue: 0,
                    sgstValue: 0,
                    cgstValue: 0,
                    totalAmount: 0
                }));
                setItems([]);
                setCustomerSearch('');
            }
        }
    }, [isOpen, existingTransactions]);

    const filteredCustomers = useMemo(() => {
        return customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase()));
    }, [customers, customerSearch]);

    const handleCustomerSelect = (customer: Customer) => {
        setInvoiceData(prev => ({
            ...prev,
            legalName: customer.name,
            address1: customer.address || '',
            gstin: customer.gstin || '',
            phone: customer.phone || '',
        }));
        setCustomerSearch(customer.name);
        setShowSuggestions(false);
    };

    const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setInvoiceData(prev => ({ ...prev, [name]: value }));
    };

    const addItem = () => {
        setItems(prev => [...prev, { id: Date.now(), profileId: '', quantity: 1, price: 0, amount: 0 }]);
    };

    const updateItem = (id: number, field: keyof QuotationItem, value: any) => {
        setItems(prev => prev.map(item => {
            if (item.id === id) {
                const updated = { ...item, [field]: value };
                if (field === 'profileId') {
                    const profile = profiles.find(p => p.id === value);
                    updated.price = profile?.price || 0;
                }
                updated.amount = updated.quantity * updated.price;
                return updated;
            }
            return item;
        }));
    };

    const removeItem = (id: number) => {
        setItems(prev => prev.filter(item => item.id !== id));
    };

    const clearAllItems = () => setItems([]);

    // Recalculate totals
    useEffect(() => {
        const totalTaxable = items.reduce((sum, item) => sum + item.amount, 0);

        // Simple tax calculation logic (Assuming 18% GST for simplicity if regular)
        const isInterState = invoiceData.placeOfSupply.toLowerCase() !== invoiceData.state.toLowerCase();
        const taxRate = 0.18; // Default 18%

        let igst = 0, cgst = 0, sgst = 0;

        if (isInterState) {
            igst = totalTaxable * taxRate;
        } else {
            cgst = totalTaxable * (taxRate / 2);
            sgst = totalTaxable * (taxRate / 2);
        }

        setInvoiceData(prev => ({
            ...prev,
            totalTaxable,
            igstValue: parseFloat(igst.toFixed(2)),
            cgstValue: parseFloat(cgst.toFixed(2)),
            sgstValue: parseFloat(sgst.toFixed(2)),
            totalAmount: Math.round(totalTaxable + igst + cgst + sgst)
        }));
    }, [items, invoiceData.placeOfSupply, invoiceData.state]);

    const handleSave = () => {
        // Use invoiceData.legalName directly which is synchronized with the input
        if (!invoiceData.legalName.trim()) {
            addToast('Legal Name is required.', 'error');
            return;
        }
        if (items.length === 0) {
            addToast('Please add at least one item.', 'error');
            return;
        }

        // Generate transactions
        const transactions: Omit<ProfileTransaction, 'id' | 'createdAt'>[] = items.map(item => ({
            profileId: item.profileId,
            type: 'QUOTATION',
            quantity: item.quantity,
            uom: 'Pcs',
            date: new Date(invoiceData.documentDate).toISOString(),
            refNo: invoiceData.documentNo,
            status: 'PENDING',
            customer: invoiceData.legalName,
            customerAddress: invoiceData.address1,
            customerGST: invoiceData.gstin,
            customerPhone: invoiceData.phone,
            unitPrice: item.price,
            invoiceDetails: invoiceData
        }));

        onAddMultiple(transactions);

        addToast(existingTransactions ? 'Quotation updated successfully.' : 'Quotation saved successfully.', 'success');
        onClose();
    };

    if (!isOpen) return null;

    const labelStyle = "block text-xs font-semibold text-gray-700 dark:text-gray-300 mb-1";
    const inputStyle = "w-full text-sm border border-gray-300 dark:border-gray-600 rounded px-2 py-1 bg-white dark:bg-gray-700 focus:ring-1 focus:ring-blue-500 outline-none";
    const sectionHeaderStyle = "font-bold text-white px-4 py-2 bg-[#958D5F] text-sm"; // Gold/Olive color from image

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 z-[100] flex justify-center items-center p-2" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl w-full max-w-7xl h-[95vh] flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>

                {/* Top Section */}
                <div className="flex flex-col md:flex-row h-1/2">
                    {/* Document Details */}
                    <div className="w-full md:w-1/4 border-r dark:border-gray-600 flex flex-col">
                        <div className={sectionHeaderStyle}>Document Details</div>
                        <div className="p-4 space-y-3 bg-[#EBE9D6] dark:bg-gray-800 h-full overflow-y-auto">
                            <div>
                                <label className={labelStyle}>Category: <span className="text-red-500">*</span></label>
                                <select name="category" value={invoiceData.category} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>Tax Invoice</option>
                                    <option>Proforma Invoice</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelStyle}>Reverse Charge: <span className="text-red-500">*</span></label>
                                <select name="reverseCharge" value={invoiceData.reverseCharge} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>No</option>
                                    <option>Yes</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelStyle}>Document Type: <span className="text-red-500">*</span></label>
                                <select name="documentType" value={invoiceData.documentType} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>Tax Invoice</option>
                                    <option>Bill of Supply</option>
                                    <option>Credit Note</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelStyle}>Document No: <span className="text-red-500">*</span></label>
                                <input name="documentNo" value={invoiceData.documentNo} onChange={handleHeaderChange} className={inputStyle} />
                            </div>
                            <div>
                                <label className={labelStyle}>Document Date: <span className="text-red-500">*</span></label>
                                <input type="date" name="documentDate" value={invoiceData.documentDate} onChange={handleHeaderChange} className={inputStyle} />
                            </div>
                        </div>
                    </div>

                    {/* Bill To Details */}
                    <div className="w-full md:w-1/2 border-r dark:border-gray-600 flex flex-col">
                        <div className={sectionHeaderStyle}>Bill To Details</div>
                        <div className="p-4 grid grid-cols-2 gap-4 bg-[#EBE9D6] dark:bg-gray-800 h-full overflow-y-auto">
                            <div className="relative">
                                <label className={labelStyle}>Legal Name: <span className="text-red-500">*</span></label>
                                <input 
                                    value={customerSearch} 
                                    onChange={(e) => { 
                                        setCustomerSearch(e.target.value); 
                                        setInvoiceData(prev => ({ ...prev, legalName: e.target.value })); 
                                        setShowSuggestions(true); 
                                    }}
                                    onFocus={() => setShowSuggestions(true)}
                                    className={inputStyle} 
                                    placeholder="Search Customer or Type Name..."
                                />
                                {showSuggestions && customerSearch && filteredCustomers.length > 0 && (
                                    <div className="absolute z-10 w-full bg-white dark:bg-gray-700 border shadow-lg max-h-40 overflow-y-auto mt-1">
                                        {filteredCustomers.map(c => (
                                            <div key={c.id} className="px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-600 cursor-pointer text-sm" onClick={() => handleCustomerSelect(c)}>
                                                {c.name}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                            <div><label className={labelStyle}>GSTIN: <span className="text-red-500">*</span></label><input name="gstin" value={invoiceData.gstin} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className={labelStyle}>Address 1: <span className="text-red-500">*</span></label><input name="address1" value={invoiceData.address1} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className={labelStyle}>Address 2:</label><input name="address2" value={invoiceData.address2} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className={labelStyle}>Location: <span className="text-red-500">*</span></label><input name="location" value={invoiceData.location} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div>
                                <label className={labelStyle}>State: <span className="text-red-500">*</span></label>
                                <select name="state" value={invoiceData.state} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>Telangana</option><option>Andhra Pradesh</option><option>Karnataka</option><option>Maharashtra</option>
                                </select>
                            </div>
                            <div><label className={labelStyle}>Pincode: <span className="text-red-500">*</span></label><input name="pincode" value={invoiceData.pincode} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className={labelStyle}>Email:</label><input name="email" value={invoiceData.email} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className={labelStyle}>Phone No:</label><input name="phone" value={invoiceData.phone} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div>
                                <label className={labelStyle}>Place of Supply: <span className="text-red-500">*</span></label>
                                <select name="placeOfSupply" value={invoiceData.placeOfSupply} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>Telangana</option><option>Andhra Pradesh</option><option>Karnataka</option><option>Maharashtra</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Transaction Details */}
                    <div className="w-full md:w-1/4 flex flex-col">
                        <div className={sectionHeaderStyle}>Transaction Details</div>
                        <div className="p-4 space-y-3 bg-[#958D5F] bg-opacity-30 dark:bg-gray-800 h-full">
                            <div>
                                <label className={labelStyle}>Igst On Intra:</label>
                                <select name="igstOnIntra" value={invoiceData.igstOnIntra} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>No</option><option>Yes</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelStyle}>Transaction Type:</label>
                                <select name="transactionType" value={invoiceData.transactionType} onChange={handleHeaderChange} className={inputStyle}>
                                    <option>Regular</option><option>Bill To - Ship To</option>
                                </select>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Item Details Header */}
                <div className="bg-[#2D89C8] text-white px-4 py-2 flex justify-between items-center text-sm font-bold">
                    <div className="flex items-center gap-4">
                        <span>Item Details</span>
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-normal opacity-80">Filter Profile by Brand:</span>
                            <select 
                                value={brandFilter} 
                                onChange={(e) => setBrandFilter(e.target.value)}
                                className="text-black text-xs p-1 rounded border-none focus:ring-0"
                            >
                                {availableBrands.map(b => <option key={b} value={b}>{b}</option>)}
                            </select>
                            <button 
                                onClick={() => setIsManageBrandsModalOpen(true)}
                                className="p-1 text-white hover:text-gray-200 bg-blue-600/50 rounded hover:bg-blue-600 transition-colors" 
                                title="Manage Brands"
                            >
                                <PencilIcon className="w-3 h-3" />
                            </button>
                        </div>
                    </div>
                    <div className="space-x-2">
                        <button onClick={addItem} className="bg-white text-[#2D89C8] px-3 py-1 rounded hover:bg-gray-100">Add New Item</button>
                        <button onClick={clearAllItems} className="bg-white text-red-500 px-3 py-1 rounded hover:bg-gray-100">Clear All Items</button>
                    </div>
                </div>

                {/* Item Details Table */}
                <div className="flex-grow overflow-y-auto bg-white dark:bg-gray-800 border-t dark:border-gray-600">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 sticky top-0">
                            <tr>
                                <th className="px-4 py-2 w-10">#</th>
                                <th className="px-4 py-2">Profile / Item</th>
                                <th className="px-4 py-2 w-24 text-right">Qty in Lengths</th>
                                <th className="px-4 py-2 w-32 text-right">Unit Price</th>
                                <th className="px-4 py-2 w-32 text-right">Amount</th>
                                <th className="px-4 py-2 w-16 text-center">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y dark:divide-gray-700">
                            {items.length === 0 ? (
                                <tr><td colSpan={6} className="text-center py-10 text-gray-500">No items added.</td></tr>
                            ) : (
                                items.map((item, index) => (
                                    <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                        <td className="px-4 py-2 text-center">{index + 1}</td>
                                        <td className="px-4 py-2">
                                            <select 
                                                value={item.profileId} 
                                                onChange={e => updateItem(item.id, 'profileId', e.target.value)} 
                                                className="w-full border p-1 rounded"
                                            >
                                                <option value="">Select Profile</option>
                                                {filteredProfiles.map(p => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}
                                            </select>
                                        </td>
                                        <td className="px-4 py-2">
                                            <input type="number" value={item.quantity} onChange={e => updateItem(item.id, 'quantity', parseFloat(e.target.value))} className="w-full border p-1 rounded text-right" />
                                        </td>
                                        <td className="px-4 py-2">
                                            <input type="number" value={item.price} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} className="w-full border p-1 rounded text-right" />
                                        </td>
                                        <td className="px-4 py-2 text-right font-medium">{item.amount.toFixed(2)}</td>
                                        <td className="px-4 py-2 text-center">
                                            <button onClick={() => removeItem(item.id)} className="text-red-500 hover:text-red-700"><TrashIcon className="w-4 h-4"/></button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Footer Totals */}
                <div className="bg-[#CFC9A8] dark:bg-gray-900 p-4 border-t dark:border-gray-600">
                    <div className="grid grid-cols-4 md:grid-cols-8 gap-4 text-xs font-bold text-gray-800 dark:text-gray-300">
                        <div>
                            <label className="block mb-1">Total Taxable Value</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.totalTaxable.toFixed(2)}</div>
                        </div>
                        <div>
                            <label className="block mb-1">IGST Value</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.igstValue.toFixed(2)}</div>
                        </div>
                        <div>
                            <label className="block mb-1">SGST Value</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.sgstValue.toFixed(2)}</div>
                        </div>
                        <div>
                            <label className="block mb-1">CGST Value</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.cgstValue.toFixed(2)}</div>
                        </div>
                        <div>
                            <label className="block mb-1">CESS Advol Value</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.cessAdvolValue}</div>
                        </div>
                        <div>
                            <label className="block mb-1">CESS Non-Ad Value</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.cessNonAdValue}</div>
                        </div>
                        <div>
                            <label className="block mb-1">Total State CESS</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded">{invoiceData.stateCessValue}</div>
                        </div>
                        <div>
                            <label className="block mb-1">Total Amount</label>
                            <div className="bg-white dark:bg-gray-700 px-2 py-1 rounded text-base font-bold text-blue-700">{invoiceData.totalAmount.toFixed(2)}</div>
                        </div>
                    </div>
                    <div className="mt-4 flex justify-end gap-3">
                        <button onClick={onClose} className="px-6 py-2 bg-gray-600 text-white rounded hover:bg-gray-700">Cancel</button>
                        <button onClick={handleSave} className="px-6 py-2 bg-blue-700 text-white rounded hover:bg-blue-800 shadow">{existingTransactions ? 'Update Invoice' : 'Save Invoice'}</button>
                    </div>
                </div>
            </div>

            {isManageBrandsModalOpen && (
                <ManageBrandsModal 
                    isOpen={isManageBrandsModalOpen} 
                    onClose={() => setIsManageBrandsModalOpen(false)} 
                    brands={brands} 
                    addBrand={addBrand} 
                    deleteBrand={deleteBrand} 
                    addToast={addToast} 
                />
            )}
        </div>
    );
};

const ManageBrandsModal: React.FC<any> = ({ isOpen, onClose, brands, addBrand, deleteBrand, addToast }) => {
    const [newB, setNewB] = useState('');
    if (!isOpen) return null;
    const handleAdd = () => { if (newB.trim() && !brands.includes(newB.trim())) { addBrand(newB.trim()); setNewB(''); } else { addToast('Brand already exists or is empty.', 'error'); } };
    const handleDelete = (e: React.MouseEvent, brand: string) => { e.stopPropagation(); deleteBrand(brand); };
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[110] flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-sm shadow-xl" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">Manage Brands</h3>
                <div className="flex gap-2 mb-4"><input value={newB} onChange={e => setNewB(e.target.value)} className="border p-2 flex-1 rounded dark:bg-gray-700 dark:text-white dark:border-gray-600" placeholder="New Brand Name" /><button onClick={handleAdd} className="bg-blue-600 text-white px-4 rounded">Add</button></div>
                <div className="max-h-48 overflow-y-auto border rounded dark:border-gray-600">
                    {brands.map((b:string) => <div key={b} className="flex justify-between p-2 border-b dark:border-gray-700 dark:text-gray-200"><span>{b}</span><button onClick={(e) => handleDelete(e, b)} className="text-red-500">Del</button></div>)}
                </div>
                <button onClick={onClose} className="mt-4 w-full border p-2 rounded dark:text-white hover:bg-gray-100 dark:hover:bg-gray-700">Close</button>
            </div>
        </div>
    );
};

