// --- ZUSTAND STORE DEFINITION ---

interface AppState {
    // State
    items: Item[];
    inflowTransactions: InflowTransaction[];
    consumptionTransactions: ConsumptionTransaction[];
    formulas: Formula[];
    reportCorrections: ReportCorrection[];
    profiles: Profile[];
    profileTransactions: ProfileTransaction[];
    brands: string[];
    customers: Customer[];
    dies: Die[];
    productionPlans: ProductionPlan[];
    currentUser: User | null;
    companySettings: CompanySettings;
    uiState: {
        inflowFilters: Record<string, string>;
        consumptionFilters: Record<string, string>;
        lastSync: string | null;
    };

    // Actions
    // Auth
    login: (user: User) => void;
    logout: () => void;

    // Global Settings
    updateCompanySettings: (settings: CompanySettings) => void;

    // Items
    addItem: (itemData: Omit<Item, 'id' | 'createdAt'>) => Item;
    updateItem: (updatedItem: Item) => void;
    deleteItem: (itemId: string) => string | null; // returns name of deleted item or null

    // Inflow
    addInflowTransaction: (txData: Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost'>) => void;
    updateInflowTransaction: (updatedTx: InflowTransaction) => void;
    deleteInflowTransaction: (txId: string) => void;
    addMultipleInflowTransactions: (newTxnsData: (Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost' | 'itemId'> & { sku: string, name?: string })[]) => { itemsAdded: number, txnsAdded: number };
    createItemAndInflow: (itemData: Omit<Item, 'id' | 'createdAt'>, txData: Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost' | 'itemId'>) => void;

    // Consumption
    addMultipleConsumptionTransactions: (txnsData: Omit<ConsumptionTransaction, 'id' | 'createdAt'>[]) => number;
    updateConsumptionTransaction: (updatedTx: ConsumptionTransaction) => void;
    deleteConsumptionTransaction: (txId: string) => void;

    // Formulas
    addFormula: (formulaData: Omit<Formula, 'id' | 'createdAt'>) => void;
    updateFormula: (updatedFormula: Formula) => void;
    deleteFormula: (formulaId: string) => void;

    // Profiles
    addProfile: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile; // Modified to return the new Profile
    updateProfile: (profile: Profile) => void;
    deleteProfile: (id: string) => void;
    addProfileTransaction: (tx: Omit<ProfileTransaction, 'id' | 'createdAt'>) => void;
    addMultipleProfileTransactions: (txs: Omit<ProfileTransaction, 'id' | 'createdAt'>[]) => void;
    updateProfileTransaction: (tx: ProfileTransaction) => void;
    deleteProfileTransaction: (id: string) => void;
    resolveQuotation: (id: string, action: 'CONFIRM_DISPATCH' | 'CONFIRM_RETURN' | 'CANCEL') => void;

    // Brands
    addBrand: (brand: string) => void;
    updateBrand: (oldBrand: string, newBrand: string) => void;
    deleteBrand: (brand: string) => void;

    // Customers
    addCustomer: (customer: Omit<Customer, 'id' | 'createdAt'>) => void;
    updateCustomer: (customer: Customer) => void;
    deleteCustomer: (id: string) => void;

    // Dies & Planning
    addDie: (dieData: Omit<Die, 'id' | 'createdAt' | 'brand'>) => void;
    updateDie: (die: Die) => void;
    deleteDie: (id: string) => void;
    addProductionPlan: (plan: Omit<ProductionPlan, 'id' | 'createdAt'>) => void;
    updateProductionPlan: (plan: ProductionPlan) => void;
    deleteProductionPlan: (id: string) => void;

    // Reports
    addOrUpdateReportCorrection: (correction: Omit<ReportCorrection, 'updatedAt'>) => void;

    // Trash / Restore
    restoreItem: (itemId: string) => void;
    restoreTransaction: (id: string, type: 'inflow' | 'consumption') => void;
    restoreFormula: (formulaId: string) => void;
    permanentlyDeleteItem: (itemId: string) => void;
    permanentlyDeleteTransaction: (id: string, type: 'inflow' | 'consumption') => void;
    permanentlyDeleteFormula: (formulaId: string) => void;

    restoreProfile: (id: string) => void;
    permanentlyDeleteProfile: (id: string) => void;
    restoreProfileTransaction: (id: string) => void;
    permanentlyDeleteProfileTransaction: (id: string) => void;

    restoreDie: (id: string) => void;
    permanentlyDeleteDie: (id: string) => void;
    restoreProductionPlan: (id: string) => void;
    permanentlyDeleteProductionPlan: (id: string) => void;

    // UI State
    setInflowFilters: (filters: Record<string, string>) => void;
    setConsumptionFilters: (filters: Record<string, string>) => void;
    setLastSync: (timestamp: string | null) => void;

    // Global
    resetData: () => void;
    loadData: (data: Partial<AppState>) => void;
}

export const useStore = create<AppState>()(
    persist(
        (set, get) => ({
            // State
            items: MOCK_ITEMS,
            inflowTransactions: MOCK_INFLOW_TRANSACTIONS,
            consumptionTransactions: MOCK_CONSUMPTION_TRANSACTIONS,
            formulas: MOCK_FORMULAS,
            reportCorrections: MOCK_REPORT_CORRECTIONS,
            profiles: MOCK_PROFILES,
            profileTransactions: MOCK_PROFILE_TRANSACTIONS,
            brands: ['Scraft', 'Smart', 'Eco'],
            customers: MOCK_CUSTOMERS,
            dies: MOCK_DIES,
            productionPlans: MOCK_PRODUCTION_PLANS,
            currentUser: null,
            companySettings: DEFAULT_COMPANY_SETTINGS,
            uiState: defaultUiState,

            // Actions
            login: (user) => set({ currentUser: user }),
            logout: () => set({ currentUser: null }),

            updateCompanySettings: (settings) => set({ companySettings: settings }),

            addItem: (itemData) => {
                const newItem = { ...itemData, id: `i_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() };
                set(state => ({ items: [...state.items, newItem] }));
                return newItem;
            },
            updateItem: (item) => set(state => ({ items: state.items.map(i => i.id === item.id ? item : i) })),
            deleteItem: (id) => {
                const item = get().items.find(i => i.id === id);
                set(state => ({ items: state.items.map(i => i.id === id ? { ...i, deletedAt: new Date().toISOString() } : i) }));
                return item ? item.name : null;
            },

            addInflowTransaction: (txData) => set(state => ({ inflowTransactions: [...state.inflowTransactions, { ...txData, id: `in_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString(), totalCost: txData.quantity * txData.unitCost }] })),
            updateInflowTransaction: (tx) => set(state => ({ inflowTransactions: state.inflowTransactions.map(t => t.id === tx.id ? tx : t) })),
            deleteInflowTransaction: (id) => set(state => ({ inflowTransactions: state.inflowTransactions.map(t => t.id === id ? { ...t, deletedAt: new Date().toISOString() } : t) })),
            addMultipleInflowTransactions: (newTxnsData) => {
                 let itemsAdded = 0;
                 let txnsAdded = 0;
                 set(state => {
                     const currentItems = state.items;
                     const newItems: Item[] = [];
                     const finalTxns: InflowTransaction[] = [];

                     newTxnsData.forEach(t => {
                         let item = currentItems.find(i => i.sku === t.sku);
                         if (!item) {
                             item = newItems.find(i => i.sku === t.sku);
                         }
                         if (!item) {
                             item = {
                                 id: `i_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                                 sku: t.sku,
                                 name: t.name || t.sku,
                                 uom: 'kg', 
                                 reorderPoint: 0,
                                 createdAt: new Date().toISOString(),
                                 costPrice: t.unitCost
                             };
                             newItems.push(item);
                             itemsAdded++;
                         }

                         finalTxns.push({
                             id: `in_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                             refNo: t.refNo,
                             itemId: item.id,
                             quantity: t.quantity,
                             unitCost: t.unitCost,
                             totalCost: t.quantity * t.unitCost,
                             warehouseId: 'wh1',
                             supplier: t.supplier,
                             createdAt: new Date().toISOString(),
                             txnDate: t.txnDate,
                         });
                         txnsAdded++;
                     });

                     return {
                         items: [...state.items, ...newItems],
                         inflowTransactions: [...state.inflowTransactions, ...finalTxns]
                     };
                 });
                 return { itemsAdded, txnsAdded };
            },
            createItemAndInflow: (itemData, txData) => {
                const newItem = { ...itemData, id: `i_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() };
                const newTx = { ...txData, itemId: newItem.id, id: `in_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString(), totalCost: txData.quantity * txData.unitCost };
                set(state => ({ items: [...state.items, newItem], inflowTransactions: [...state.inflowTransactions, newTx] }));
            },

            addMultipleConsumptionTransactions: (txnsData) => {
                const newTxns = txnsData.map((t, idx) => ({ ...t, id: `out_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }));
                set(state => ({ consumptionTransactions: [...state.consumptionTransactions, ...newTxns] }));
                return newTxns.length;
            },
            updateConsumptionTransaction: (tx) => set(state => ({ consumptionTransactions: state.consumptionTransactions.map(t => t.id === tx.id ? tx : t) })),
            deleteConsumptionTransaction: (id) => set(state => ({ consumptionTransactions: state.consumptionTransactions.map(t => t.id === id ? { ...t, deletedAt: new Date().toISOString() } : t) })),

            addFormula: (formulaData) => set(state => ({ formulas: [...state.formulas, { ...formulaData, id: `f_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }] })),
            updateFormula: (formula) => set(state => ({ formulas: state.formulas.map(f => f.id === formula.id ? formula : f) })),
            deleteFormula: (id) => set(state => ({ formulas: state.formulas.map(f => f.id === id ? { ...f, deletedAt: new Date().toISOString() } : f) })),

            addProfile: (profile) => {
                const newProfile = { ...profile, id: `p_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() };
                set(state => ({ profiles: [...state.profiles, newProfile] }));
                return newProfile;
            },
            updateProfile: (profile) => set(state => ({ profiles: state.profiles.map(p => p.id === profile.id ? profile : p) })),
            deleteProfile: (id) => set(state => ({ profiles: state.profiles.map(p => p.id === id ? { ...p, deletedAt: new Date().toISOString() } : p) })),

            addProfileTransaction: (tx) => set(state => ({ 
                profileTransactions: [...state.profileTransactions, { ...tx, id: `pt_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }] 
            })),
            addMultipleProfileTransactions: (txs) => set(state => ({
                profileTransactions: [...state.profileTransactions, ...txs.map((tx, idx) => ({
                    ...tx,
                    id: `pt_${Date.now()}_${idx}_${Math.random().toString(36).substr(2, 9)}`,
                    createdAt: new Date().toISOString()
                }))]
            })),
            updateProfileTransaction: (tx) => set(state => ({ profileTransactions: state.profileTransactions.map(t => t.id === tx.id ? tx : t) })),
            deleteProfileTransaction: (id) => set(state => ({ profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, deletedAt: new Date().toISOString() } : t) })),
            resolveQuotation: (id, action) => {
                const tx = get().profileTransactions.find(t => t.id === id);
                if (tx && tx.type === 'QUOTATION') {
                    if (action === 'CANCEL') {
                        set(state => ({ profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, status: 'CANCELLED' } : t) }));
                    } else {
                        // Determine type based on action: CONFIRM_RETURN -> RETURN, otherwise DISPATCH
                        const type = action === 'CONFIRM_RETURN' ? 'RETURN' : 'DISPATCH';
                        const refPrefix = action === 'CONFIRM_RETURN' ? 'RET-' : 'DISP-';

                        const newTx: ProfileTransaction = {
                            id: `pt_auto_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, 
                            profileId: tx.profileId,
                            type: type, 
                            quantity: tx.quantity,
                            uom: tx.uom,
                            date: new Date().toISOString(),
                            refNo: `${refPrefix}${tx.refNo}`,
                            customer: tx.customer,
                            createdAt: new Date().toISOString()
                        };
                        set(state => ({ 
                            profileTransactions: [
                                ...state.profileTransactions.map(t => t.id === id ? { ...t, status: 'COMPLETED' } : t),
                                newTx
                            ] 
                        }));
                    }
                }
            },

            addBrand: (brand) => set(state => ({ brands: [...state.brands, brand] })),
            updateBrand: (oldB, newB) => set(state => ({ 
                brands: state.brands.map(b => b === oldB ? newB : b),
                profiles: state.profiles.map(p => p.brand === oldB ? { ...p, brand: newB } : p),
                dies: state.dies.map(d => d.brand === oldB ? { ...d, brand: newB } : d)
            })),
            deleteBrand: (brand) => set(state => ({ brands: state.brands.filter(b => b !== brand) })),

            addCustomer: (c) => set(state => ({ customers: [...state.customers, { ...c, id: `cust_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }] })),
            updateCustomer: (c) => set(state => ({ customers: state.customers.map(cust => cust.id === c.id ? c : cust) })),
            deleteCustomer: (id) => set(state => ({ customers: state.customers.map(c => c.id === id ? { ...c, deletedAt: new Date().toISOString() } : c) })),

            addDie: (dieData) => {
                const profile = get().profiles.find(p => p.id === dieData.profileId);
                const newDie: Die = { ...dieData, id: `die_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString(), brand: profile?.brand || '', processLog: {} }; 
                set(state => ({ dies: [...state.dies, newDie] }));
            },
            updateDie: (die) => {
                 const profile = get().profiles.find(p => p.id === die.profileId);
                 const updatedDie = { ...die, brand: profile?.brand || '', processLog: die.processLog || {} }; 
                 set(state => ({ dies: state.dies.map(d => d.id === die.id ? updatedDie : d) }))
            },
            deleteDie: (id) => set(state => ({ dies: state.dies.map(d => d.id === id ? { ...d, deletedAt: new Date().toISOString() } : d) })),
            addProductionPlan: (plan) => set(state => ({ productionPlans: [...state.productionPlans, { ...plan, id: `pp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, createdAt: new Date().toISOString() }] })),
            updateProductionPlan: (plan) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === plan.id ? plan : p) })),
            deleteProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === id ? { ...p, deletedAt: new Date().toISOString() } : p) })),

            addOrUpdateReportCorrection: (correction) => set(state => {
                const existingIndex = state.reportCorrections.findIndex(c => c.itemId === correction.itemId && c.date === correction.date);
                const newCorrection = { ...correction, updatedAt: new Date().toISOString() };
                if (existingIndex > -1) {
                    const newCorrections = [...state.reportCorrections];
                    newCorrections[existingIndex] = newCorrection;
                    return { reportCorrections: newCorrections };
                }
                return { reportCorrections: [newCorrection, ...state.reportCorrections] };
            }),

            restoreItem: (itemId) => set(state => ({
                items: state.items.map(i => i.id === itemId ? { ...i, deletedAt: null } : i),
                inflowTransactions: state.inflowTransactions.map(tx => tx.itemId === itemId ? { ...tx, deletedAt: null } : tx),
                consumptionTransactions: state.consumptionTransactions.map(tx => tx.itemId === itemId ? { ...tx, deletedAt: null } : tx),
            })),
            restoreTransaction: (id, type) => {
                if (type === 'inflow') {
                    set(state => ({ inflowTransactions: state.inflowTransactions.map(tx => tx.id === id ? { ...tx, deletedAt: null } : tx) }));
                } else {
                    set(state => ({ consumptionTransactions: state.consumptionTransactions.map(tx => tx.id === id ? { ...tx, deletedAt: null } : tx) }));
                }
            },
            restoreFormula: (formulaId) => set(state => ({
                formulas: state.formulas.map(f => f.id === formulaId ? { ...f, deletedAt: null } : f),
            })),
            permanentlyDeleteItem: (itemId) => set(state => ({
                items: state.items.filter(i => i.id !== itemId),
                inflowTransactions: state.inflowTransactions.filter(tx => tx.itemId !== itemId),
                consumptionTransactions: state.consumptionTransactions.filter(tx => tx.itemId !== itemId),
            })),
            permanentlyDeleteTransaction: (id, type) => {
                if (type === 'inflow') {
                    set(state => ({ inflowTransactions: state.inflowTransactions.filter(tx => tx.id !== id) }));
                } else {
                    set(state => ({ consumptionTransactions: state.consumptionTransactions.filter(tx => tx.id !== id) }));
                }
            },
            permanentlyDeleteFormula: (formulaId) => set(state => ({
                formulas: state.formulas.filter(f => f.id !== formulaId),
            })),

            restoreProfile: (id) => set(state => ({
                profiles: state.profiles.map(p => p.id === id ? { ...p, deletedAt: null } : p)
            })),
            permanentlyDeleteProfile: (id) => set(state => ({
                profiles: state.profiles.filter(p => p.id !== id),
            })),
            restoreProfileTransaction: (id) => set(state => ({
                profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, deletedAt: null } : t)
            })),
            permanentlyDeleteProfileTransaction: (id) => set(state => ({
                profileTransactions: state.profileTransactions.filter(t => t.id !== id)
            })),

            restoreDie: (id) => set(state => ({ dies: state.dies.map(d => d.id === id ? { ...d, deletedAt: null } : d) })),
            permanentlyDeleteDie: (id) => set(state => ({ dies: state.dies.filter(d => d.id !== id) })),
            restoreProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === id ? { ...p, deletedAt: null } : p) })),
            permanentlyDeleteProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.filter(p => p.id !== id) })),

            setInflowFilters: (filters) => set(state => ({
                uiState: { ...state.uiState, inflowFilters: filters }
            })),
            setConsumptionFilters: (filters) => set(state => ({
                uiState: { ...state.uiState, consumptionFilters: filters }
            })),
            setLastSync: (timestamp) => set(state => ({
                uiState: { ...state.uiState, lastSync: timestamp }
            })),

            resetData: () => set({
                items: MOCK_ITEMS,
                inflowTransactions: MOCK_INFLOW_TRANSACTIONS,
                consumptionTransactions: MOCK_CONSUMPTION_TRANSACTIONS,
                formulas: MOCK_FORMULAS,
                reportCorrections: MOCK_REPORT_CORRECTIONS,
                profiles: MOCK_PROFILES,
                profileTransactions: MOCK_PROFILE_TRANSACTIONS,
                brands: ['Scraft', 'Smart', 'Eco'],
                customers: MOCK_CUSTOMERS,
                dies: MOCK_DIES,
                productionPlans: MOCK_PRODUCTION_PLANS,
                currentUser: get().currentUser,
                companySettings: DEFAULT_COMPANY_SETTINGS,
                uiState: defaultUiState,
            }),
            loadData: (data) => set(state => ({
                ...state,
                items: data.items || state.items,
                inflowTransactions: data.inflowTransactions || state.inflowTransactions,
                consumptionTransactions: data.consumptionTransactions || state.consumptionTransactions,
                formulas: data.formulas || state.formulas,
                reportCorrections: data.reportCorrections || state.reportCorrections,
                profiles: data.profiles || state.profiles,
                profileTransactions: data.profileTransactions || state.profileTransactions,
                brands: data.brands || state.brands,
                customers: data.customers || state.customers,
                dies: data.dies || state.dies,
                productionPlans: data.productionPlans || state.productionPlans,
                companySettings: data.companySettings || state.companySettings,
                uiState: data.uiState || state.uiState,
            })),
        }),
        {
            name: 'erp-storage', 
            storage: createJSONStorage(() => localStorage), 
            partialize: (state) =>
              Object.fromEntries(
                Object.entries(state).filter(([key]) => !['currentUser'].includes(key))
              ),
        }
    )
);

