                            <label className="cursor-pointer bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-bold hover:bg-blue-700 flex gap-2"><CloudUploadIcon className="w-4 h-4"/> Upload Default <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" /></label>
