                {activeTab === 'Dispatch' && <div id="profile-dispatch-table"><TransactionTable transactions={dispatchTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} onPrint={generateInvoicePDF} type="DISPATCH" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Scrap' && <div id="profile-scrap-table"><TransactionTable transactions={scrapTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} type="SCRAP" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Quotations' && <div id="profile-quotations-table"><QuotationTable groupedQuotations={groupedQuotations} onAction={handleQuotationAction} onEdit={(refNo:string) => { setEditingQuotation(allTransactions.filter(t => t.refNo === refNo)); setIsQuotationModalOpen(true); }} onDelete={handleDeleteQuotation} onPrint={generateInvoicePDF} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Profiles' && <div id="profile-list-table"><ProfileListTable profiles={filteredProfiles} onEdit={(p:Profile) => { setEditingProfile(p); setIsProfileModalOpen(true); }} onDelete={handleDeleteProfile} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Customers' && <div id="profile-customers-table"><CustomerTable customers={allCustomers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()))} onEdit={(c:Customer) => { setEditingCustomer(c); setIsCustomerModalOpen(true); }} onDelete={handleDeleteCustomer} /></div>}
            </div>

            <Portal><AddProfileModal isOpen={isProfileModalOpen} onClose={() => {setIsProfileModalOpen(false); setEditingProfile(null);}} onAdd={editingProfile ? (data) => handleUpdateProfile({...editingProfile, ...data}) : handleAddProfile} brands={brands} addToast={addToast} initialData={editingProfile} /></Portal>
            <Portal><CustomerModal isOpen={isCustomerModalOpen} onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} onSave={editingCustomer ? (data) => handleUpdateCustomer({...editingCustomer, ...data}) : handleAddCustomer} customer={editingCustomer} addToast={addToast} /></Portal>
            <Portal><TransactionModal isOpen={isTransactionModalOpen} onClose={() => { setIsTransactionModalOpen(false); setEditingTransaction(null); }} type={transactionType} profiles={stockData} onAdd={handleAddTransaction} addToast={addToast} customers={allCustomers} addCustomer={handleAddCustomer} /></Portal>
            <Portal><EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} onUpdate={handleUpdateTransaction} /></Portal>
            <Portal>
                <CreateQuotationModal 
                    isOpen={isQuotationModalOpen} 
                    onClose={() => {setIsQuotationModalOpen(false); setEditingQuotation(null);}} 
                    profiles={allProfiles} 
                    customers={allCustomers} 
                    onAddMultiple={(txs) => { txs.forEach(tx => addProfileTransaction(tx))}} 
                    addToast={addToast} 
                    existingTransactions={editingQuotation ? editingQuotation : undefined}
                    brands={brands}
                    addBrand={addBrand}
                    deleteBrand={deleteBrand}
                />
            </Portal>
            <Portal><CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} addToast={addToast} brands={brands} /></Portal>
            <Portal><ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
        </div>
    );
};

