        // Handle Single Dispatch vs Grouped Quotation
        const isQuotation = !!data.items;
        const txData = isQuotation ? data.items : [data];
        const refTx = txData[0];
        const profile = getProfile(refTx.profileId);
        // Prioritize brand saved in transaction
        const brandName = refTx.brand || profile?.brand || 'Smart';

        // Determine Logo
        let logoToUse = companySettings.logoUrl;
        let brandHeader = '';
        const brandLogo = companySettings.brandLogos?.find(bl => bl.brand === brandName);
        if (brandLogo) {
            logoToUse = brandLogo.logoUrl;
            brandHeader = brandName.toUpperCase();
        }

        // Header Section
        if (logoToUse) {
            try { doc.addImage(logoToUse, 'JPEG', 14, 10, 30, 15); } catch (e) {}
        } else {
            doc.setFontSize(20);
            doc.setTextColor(40, 167, 69);
            doc.text(brandHeader || "Smart UPVC", 14, 20);
        }

        doc.setFontSize(22);
        doc.setTextColor(165, 42, 42); // Maroon/Brown
        doc.text("RAVIRAJA", 195, 20, { align: 'right' });
        doc.setFontSize(10);
        doc.setTextColor(0, 0, 0);
        doc.text("Industries Pvt. Ltd.", 195, 25, { align: 'right' });

        doc.setFontSize(14);
        doc.setFont("helvetica", "bold");
        doc.text(isQuotation ? "QUOTATION" : "DISPATCH NOTE", 105, 35, { align: 'center' });

        // Address Grid
        doc.autoTable({
            startY: 40,
            theme: 'grid',
            styles: { fontSize: 9, cellPadding: 2, lineWidth: 0.1, lineColor: [0,0,0], textColor: [0,0,0] },
            body: [
                [ { content: 'Supplier Registered Address', styles: { fontStyle: 'bold', fillColor: [240,240,240] } }, { content: 'Factory Address', styles: { fontStyle: 'bold', fillColor: [240,240,240] } } ],
                [ { content: `${companySettings.name}\n${companySettings.addressLine1}\n${companySettings.cityStateZip}` }, { content: 'Plot no: 488, TIF MSME\nGreen Park, Dandu Malkapuram Vill -508252' } ],
                [ { content: `Supplier GSTN: ${companySettings.gstin}`, styles: { fontStyle: 'bold' } }, { content: `Code: AALCR2439Q` } ]
            ],
            columnStyles: { 0: { cellWidth: 95 }, 1: { cellWidth: 95 } },
            margin: { left: 10, right: 10 }
        });

        // Customer & Doc Meta Grid
        const currentY = (doc as any).lastAutoTable.finalY;
        doc.autoTable({
            startY: currentY,
            theme: 'grid',
            styles: { fontSize: 9, cellPadding: 2, lineWidth: 0.1, lineColor: [0,0,0], textColor: [0,0,0] },
            body: [
                [ { content: 'Billed & Delivered to', styles: { fontStyle: 'bold', fillColor: [240,240,240] } }, { content: isQuotation ? 'Quotation Details' : 'Dispatch Details', styles: { fontStyle: 'bold', fillColor: [240,240,240] } } ],
                [ { content: `${refTx.customer || 'Unknown Customer'}\n${refTx.customerAddress || ''}\nGSTIN: ${refTx.customerGST || ''}`, rowSpan: 4 }, { content: `Document No: ${refTx.refNo}` } ],
                [ { content: `Date: ${new Date(refTx.date).toLocaleDateString()}` } ],
                [ { content: `Place of Supply: ${refTx.invoiceDetails?.placeOfSupply || 'Telangana'}` } ],
                [ { content: `Transport: By Road` } ]
            ],
            columnStyles: { 0: { cellWidth: 130 }, 1: { cellWidth: 60 } },
            margin: { left: 10, right: 10 }
        });

        // Items Table
        let totalTaxable = 0;
        let totalQty = 0;
        let totalWeightKg = 0;
        const body = txData.map((t: any, i: number) => {
            const p = getProfile(t.profileId);
            const qty = t.quantity; // Total Lengths
            // Prioritize Transaction overrides (customized in Modal)
            const hsn = t.hsnCode || p?.hsnCode || '39252000';
            const sku = t.profileSkuOverride || p?.sku || '';
            const meterWeight = t.weight || p?.weight || 0;
            const price = t.unitPrice || p?.price || 0;
            const pps = t.piecesPerPacket || p?.piecesPerPacket || 1;
            const packs = t.packets || Math.ceil(qty / pps);

            const amt = qty * price;
            totalTaxable += amt;
            totalQty += qty;
            const weight = meterWeight * qty;
            totalWeightKg += weight;
            return [
                i + 1,
                t.profileNameOverride || p?.name || 'Unknown',
                hsn,
                sku,
                packs,
                pps,
                qty,
                meterWeight.toFixed(3),
                amt.toLocaleString('en-IN', { minimumFractionDigits: 2 })
            ];
        });

        doc.autoTable({
            startY: (doc as any).lastAutoTable.finalY + 5,
            theme: 'grid',
            styles: { fontSize: 8, cellPadding: 2, lineWidth: 0.1, lineColor: [0,0,0], textColor: [0,0,0], halign: 'center' },
            headStyles: { fillColor: [230, 230, 230], fontStyle: 'bold' },
            head: [['Sl.No', 'Description', 'HSN', 'Profile Code', 'Packets', 'Lengths/Pkt', 'Total Lengths', 'Meter Weight', 'Amount Rs']],
            body,
            margin: { left: 10, right: 10 }
        });

        // Totals & Footer
        const finalY = (doc as any).lastAutoTable.finalY;
        const cgst = totalTaxable * 0.09;
        const sgst = totalTaxable * 0.09;
        const grandTotal = totalTaxable + cgst + sgst;

        doc.autoTable({
            startY: finalY,
            theme: 'grid',
            styles: { fontSize: 9, cellPadding: 2, lineWidth: 0.1, lineColor: [0,0,0], textColor: [0,0,0] },
            body: [
                [ { content: 'Total Taxable Value', colSpan: 8, styles: { halign: 'right', fontStyle: 'bold' } }, { content: totalTaxable.toLocaleString('en-IN', { minimumFractionDigits: 2 }), styles: { halign: 'right', fontStyle: 'bold' } } ],
                [ { content: 'CGST @ 9%', colSpan: 8, styles: { halign: 'right' } }, { content: cgst.toLocaleString('en-IN', { minimumFractionDigits: 2 }), styles: { halign: 'right' } } ],
                [ { content: 'SGST @ 9%', colSpan: 8, styles: { halign: 'right' } }, { content: sgst.toLocaleString('en-IN', { minimumFractionDigits: 2 }), styles: { halign: 'right' } } ],
                [ { content: 'Total Invoice Value', colSpan: 8, styles: { halign: 'right', fontStyle: 'bold' } }, { content: Math.round(grandTotal).toLocaleString('en-IN'), styles: { halign: 'right', fontStyle: 'bold' } } ]
            ],
            margin: { left: 10, right: 10 }
        });

        // Signature Area
        const bottomY = (doc as any).lastAutoTable.finalY + 5;
        doc.setFontSize(9);
        doc.text(`Amount in Words: ${numberToWords(Math.round(grandTotal))}`, 10, bottomY);
        doc.text(`Bank: ${companySettings.bankName || 'UNION BANK'}\nAccount: ${companySettings.accountNo || ''}\nIFSC: ${companySettings.ifsc || ''}`, 10, bottomY + 10);
        doc.text(`For ${companySettings.name}\n\n\nAuthorised Signatory`, 195, bottomY + 15, { align: 'right' });

        doc.save(`${refTx.refNo}.pdf`);
    }, [getProfile, companySettings]);

    // Derived Data
    const brandFilteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return allProfiles;
        return allProfiles.filter(p => p.brand === brandFilter);
    }, [allProfiles, brandFilter]);

    const brandFilteredTransactions = useMemo(() => {
        if (brandFilter === 'All') return allTransactions;
        const allowedProfileIds = new Set(brandFilteredProfiles.map(p => p.id));
        return allTransactions.filter(t => allowedProfileIds.has(t.profileId));
    }, [allTransactions, brandFilteredProfiles, brandFilter]);

    const stockData = useMemo(() => {
        return brandFilteredProfiles.map(p => {
            const relevantTxns = allTransactions.filter(t => t.profileId === p.id);
            const production = relevantTxns.filter(t => t.type === 'PRODUCTION' || t.type === 'RETURN').reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = relevantTxns.filter(t => t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const scrap = relevantTxns.filter(t => t.type === 'SCRAP').reduce((sum, t) => {
                 if (t.uom === 'Kgs' && p.weight && p.weight > 0) {
                    return sum + (t.quantity / p.weight);
                }
                return sum + t.quantity;
            }, 0);
            const reserved = relevantTxns.filter(t => t.type === 'QUOTATION' && t.status === 'PENDING').reduce((sum, t) => sum + t.quantity, 0);

            return {
                ...p,
                currentStock: production - dispatch - scrap,
                reservedStock: reserved
            };
        });
    }, [brandFilteredProfiles, allTransactions]);

    const productionTransactions = useFilteredTransactions(brandFilteredTransactions, brandFilteredProfiles, searchTerm, getProfile, 'PRODUCTION');
    const dispatchTransactions = useFilteredTransactions(brandFilteredTransactions, brandFilteredProfiles, searchTerm, getProfile, 'DISPATCH');
    const scrapTransactions = useFilteredTransactions(brandFilteredTransactions, brandFilteredProfiles, searchTerm, getProfile, 'SCRAP');

    const groupedQuotations = useMemo(() => {
        const rawQuotations = brandFilteredTransactions.filter(t => t.type === 'QUOTATION');
        const groups: Record<string, any> = {};
        rawQuotations.forEach(t => {
            if (!groups[t.refNo]) {
                const profile = getProfile(t.profileId);
                groups[t.refNo] = {
                    refNo: t.refNo,
                    date: t.date,
                    customer: t.customer,
                    status: t.status,
                    totalAmount: 0,
                    items: [],
                    invoiceDetails: t.invoiceDetails,
                    brand: t.brand || profile?.brand
                };
            }
            const profile = getProfile(t.profileId);
            const price = t.unitPrice || profile?.price || 0;
            const amount = t.quantity * price;
            groups[t.refNo].totalAmount = (t.invoiceDetails?.totalAmount) || (groups[t.refNo].totalAmount + amount);
            groups[t.refNo].items.push(t);
        });

        let result = Object.values(groups).sort((a:any, b:any) => new Date(b.date).getTime() - new Date(a.date).getTime());
        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            result = result.filter((g:any) => 
                g.refNo.toLowerCase().includes(lower) || 
                g.customer?.toLowerCase().includes(lower) ||
                g.items.some((item: any) => {
                    const prof = getProfile(item.profileId);
                    return item.profileSkuOverride?.toLowerCase().includes(lower) || 
                           item.hsnCode?.toLowerCase().includes(lower) ||
                           prof?.sku?.toLowerCase().includes(lower);
                })
            );
        }
        return result;
    }, [brandFilteredTransactions, searchTerm, getProfile]);

    const filteredProfiles = useMemo(() => {
        if (!searchTerm) return brandFilteredProfiles;
        const lower = searchTerm.toLowerCase();
        return brandFilteredProfiles.filter(p => p.name.toLowerCase().includes(lower) || p.sku.toLowerCase().includes(lower));
    }, [brandFilteredProfiles, searchTerm]);

    const planningData = useMemo(() => {
        const now = new Date();
        let thresholdDate: Date | null = null;
        if (planningTimeFilter === '3M') thresholdDate = new Date(now.setMonth(now.getMonth() - 3));
        else if (planningTimeFilter === '6M') thresholdDate = new Date(now.setMonth(now.getMonth() - 6));
        else if (planningTimeFilter === '12M') thresholdDate = new Date(now.setMonth(now.getMonth() - 12));

        const periodStart = thresholdDate ? thresholdDate.getTime() : 0;

        return stockData.map(p => {
            const periodSales = allTransactions
                .filter(t => t.profileId === p.id && t.type === 'DISPATCH' && new Date(t.date).getTime() >= periodStart)
                .reduce((sum, t) => sum + t.quantity, 0);
            return { ...p, periodSales };
        }).map((p, _, array) => {
            const totalPeriodSales = array.reduce((sum, item) => sum + item.periodSales, 0);
            return {
                ...p,
                sharePercentage: totalPeriodSales > 0 ? (p.periodSales / totalPeriodSales) * 100 : 0
            };
        }).sort((a, b) => b.periodSales - a.periodSales);
    }, [stockData, allTransactions, planningTimeFilter]);

    // Handlers
    const handleAddProfile = (data: any) => { addProfile(data); addToast('Profile added successfully', 'success'); };
    const handleUpdateProfile = (data: any) => { updateProfile(data); addToast('Profile updated successfully', 'success'); };
    const handleDeleteProfile = (id: string) => { if(confirm('Delete profile? This will move it to trash.')) { deleteProfile(id); addToast('Profile deleted', 'info'); } };

    const handleAddCustomer = (data: any) => { addCustomer(data); addToast('Customer added', 'success'); };
    const handleUpdateCustomer = (data: any) => { updateCustomer(data); addToast('Customer updated', 'success'); };
    const handleDeleteCustomer = (id: string) => { if(confirm('Delete customer?')) { deleteCustomer(id); addToast('Customer deleted', 'info'); } };

    const handleAddTransaction = (data: any) => { addProfileTransaction(data); addToast('Transaction recorded', 'success'); };
    const handleUpdateTransaction = (data: any) => { updateProfileTransaction(data); addToast('Transaction updated', 'success'); };
    const handleDeleteTransaction = (id: string) => { if(confirm('Delete transaction?')) { deleteProfileTransaction(id); addToast('Transaction deleted', 'info'); } };

    const handleQuotationAction = (refNo: string, action: 'CONFIRM_DISPATCH' | 'CONFIRM_RETURN' | 'CANCEL') => {
        const txns = allTransactions.filter(t => t.refNo === refNo && t.status === 'PENDING');
        txns.forEach(t => resolveQuotation(t.id, action));
        addToast(`Quotation ${action === 'CANCEL' ? 'Cancelled' : action === 'CONFIRM_RETURN' ? 'Returned' : 'Dispatched'}`, 'success');
    };

    const handleDeleteQuotation = (refNo: string) => {
        if(confirm('Delete entire quotation?')) {
            const txns = allTransactions.filter(t => t.refNo === refNo);
            txns.forEach(t => deleteProfileTransaction(t.id));
            addToast('Quotation deleted', 'info');
        }
    };

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
                setIsDownloadMenuOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [downloadMenuRef]);

    const getActiveTableId = () => {
        switch(activeTab) {
            case 'Stock': return 'profile-stock-table';
            case 'Planning': return 'profile-planning-table';
            case 'Production': return 'profile-production-table';
            case 'Dispatch': return 'profile-dispatch-table';
            case 'Scrap': return 'profile-scrap-table';
            case 'Quotations': return 'profile-quotations-table';
            case 'Profiles': return 'profile-list-table';
            case 'Customers': return 'profile-customers-table';
            default: return null;
        }
    };

    const handleExport = (type: 'pdf' | 'excel') => {
        const tableId = getActiveTableId();
        if (!tableId) return;

        const tableContainer = document.getElementById(tableId);
        const tableElement = tableContainer?.querySelector('table');

        if (!tableElement) {
            addToast('No data to export', 'info');
            return;
        }

        if (type === 'pdf') {
            const { jsPDF } = jspdf;
            const doc = new jsPDF({ orientation: 'landscape' });

            const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
            const noPrintColumn = clonedTable.querySelector('th:last-child');
            if (noPrintColumn && (noPrintColumn.textContent?.includes('Action') || noPrintColumn.classList.contains('no-print'))) {
                const index = Array.from(noPrintColumn.parentElement!.children).indexOf(noPrintColumn);
                Array.from(clonedTable.rows).forEach(row => {
                    if (row.cells[index]) row.deleteCell(index);
                });
            }

            doc.text(`${activeTab} Report`, 14, 15);
            doc.autoTable({ html: clonedTable, startY: 20, theme: 'grid', styles: { fontSize: 8 } });
            doc.save(`${activeTab}_Report_${new Date().toISOString().split('T')[0]}.pdf`);
        } else {
            const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
            const headers = Array.from(clonedTable.querySelectorAll('thead th'));
            const actionIndex = headers.findIndex(th => th.textContent?.includes('Action') || th.classList.contains('no-print'));
            if(actionIndex > -1) {
                 Array.from(clonedTable.rows).forEach(row => {
                    if(row.cells[actionIndex]) row.deleteCell(actionIndex);
                });
            }

            const wb = XLSX.utils.table_to_book(clonedTable, { sheet: "Sheet1" });
            XLSX.writeFile(wb, `${activeTab}_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
        }
        setIsDownloadMenuOpen(false);
    };

    const TABS: Tab[] = ['Dashboard', 'Stock', 'Planning', 'Production', 'Dispatch', 'Scrap', 'Quotations', 'Profiles', 'Customers'];

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Section</h1>
                <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto items-end sm:items-center">

                    <div className="flex items-center gap-2 bg-white dark:bg-gray-800 p-1 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm">
                        {['Stock', 'Production', 'Dispatch', 'Scrap', 'Profiles', 'Customers', 'Quotations'].includes(activeTab) && (
                            <div className="relative">
                                <input 
                                    type="text" 
                                    placeholder="Search ref, cust, HSN, code..." 
                                    value={searchTerm} 
                                    onChange={e => setSearchTerm(e.target.value)} 
                                    className="pl-7 pr-2 py-1 border-none bg-transparent focus:ring-0 w-32 sm:w-48 text-sm text-gray-700 dark:text-gray-200 placeholder-gray-400" 
                                />
                                <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            </div>
                        )}

                        {['Stock', 'Production', 'Dispatch', 'Scrap', 'Profiles', 'Customers', 'Quotations'].includes(activeTab) && <div className="h-6 w-px bg-gray-300 dark:bg-gray-600 mx-1"></div>}

                        <select 
                            value={brandFilter} 
                            onChange={(e) => setBrandFilter(e.target.value)} 
                            className="bg-transparent border-none text-sm font-medium focus:ring-0 cursor-pointer text-gray-900 dark:text-white pr-8 outline-none"
                            title="Filter by Brand"
                        >
                            <option value="All">All Brands</option>
                            {brands.map(b => <option key={b} value={b}>{b}</option>)}
                        </select>

                        {activeTab === 'Planning' && (
                             <select value={planningTimeFilter} onChange={e => setPlanningTimeFilter(e.target.value as any)} className="bg-transparent border-none text-sm font-medium focus:ring-0 cursor-pointer text-gray-900 dark:text-white outline-none">
                                <option value="3M">3 Months</option><option value="6M">6 Months</option><option value="12M">12 Months</option><option value="ALL">All Time</option>
                            </select>
                        )}
                    </div>

                    <div className="flex items-center gap-2">
                        {getActiveTableId() && (
                            <div className="relative" ref={downloadMenuRef}>
                                <button
                                    onClick={() => setIsDownloadMenuOpen(prev => !prev)}
                                    className="p-2 text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-sm transition-all flex items-center gap-1"
                                    title="Download Report"
                                >
                                    <span className="text-sm font-bold">⬇</span>
                                </button>
                                {isDownloadMenuOpen && (
                                    <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-20 ring-1 ring-black ring-opacity-5">
                                        <button onClick={() => handleExport('pdf')} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">
                                            Download as PDF
                                        </button>
                                        <button onClick={() => handleExport('excel')} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">
                                            Download as Excel
                                        </button>
                                    </div>
                                )}
                            </div>
                        )}

                        <button onClick={() => setIsManageBrandsModalOpen(true)} className="p-2 text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-sm transition-all" title="Manage Brands">
                            <PencilIcon className="w-4 h-4" />
                        </button>
                        <button onClick={() => setIsSettingsModalOpen(true)} className="p-2 text-gray-500 hover:text-gray-800 dark:hover:text-white bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-sm transition-all" title="Settings">
                            <span className="text-sm font-bold">⚙️</span>
                        </button>

                        {activeTab === 'Production' && (
                            <button onClick={() => { setTransactionType('PRODUCTION'); setIsTransactionModalOpen(true); }} className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-green-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Production
                            </button>
                        )}
                        {activeTab === 'Dispatch' && (
                            <button onClick={() => { setTransactionType('DISPATCH'); setIsTransactionModalOpen(true); }} className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-red-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Dispatch
                            </button>
                        )}
                        {activeTab === 'Scrap' && (
                            <button onClick={() => { setTransactionType('SCRAP'); setIsTransactionModalOpen(true); }} className="bg-orange-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-orange-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Scrap
                            </button>
                        )}
                        {activeTab === 'Profiles' && (
                            <button onClick={() => setIsProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Add Profile
                            </button>
                        )}
                        {activeTab === 'Customers' && (
                            <button onClick={() => setIsCustomerModalOpen(true)} className="bg-purple-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-purple-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + Add Customer
                            </button>
                        )}
                        {activeTab === 'Quotations' && (
                            <button onClick={() => setIsQuotationModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 shadow-md transition-transform active:scale-95 flex items-center gap-2">
                                + New Quotation
                            </button>
                        )}
                    </div>
                </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 no-print">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {TABS.map(tab => <button key={tab} onClick={() => setActiveTab(tab)} className={`${activeTab === tab ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}>{tab}</button>)}
                </nav>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                {activeTab === 'Dashboard' && <ProfileDashboard profiles={brandFilteredProfiles} transactions={brandFilteredTransactions} stockData={stockData} />}
                {activeTab === 'Stock' && <div id="profile-stock-table"><StockTable stockData={filteredProfiles} onEditProfile={(p:Profile) => {setEditingProfile(p); setIsProfileModalOpen(true);}} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Planning' && <div id="profile-planning-table"><PlanningTable planningData={planningData} getBrandBadge={getBrandBadge} planningTimeFilter={planningTimeFilter} /></div>}
                {activeTab === 'Production' && <div id="profile-production-table"><TransactionTable transactions={productionTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} type="PRODUCTION" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Dispatch' && <div id="profile-dispatch-table"><TransactionTable transactions={dispatchTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} onPrint={generateInvoicePDF} type="DISPATCH" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Scrap' && <div id="profile-scrap-table"><TransactionTable transactions={scrapTransactions} getProfileName={getProfileName} getProfileSpecs={getProfileSpecs} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={handleDeleteTransaction} type="SCRAP" getBrandBadge={getBrandBadge} getProfile={getProfile} /></div>}
                {activeTab === 'Quotations' && <div id="profile-quotations-table"><QuotationTable groupedQuotations={groupedQuotations} onAction={handleQuotationAction} onEdit={(refNo:string) => { setEditingQuotation(allTransactions.filter(t => t.refNo === refNo)); setIsQuotationModalOpen(true); }} onDelete={handleDeleteQuotation} onPrint={generateInvoicePDF} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Profiles' && <div id="profile-list-table"><ProfileListTable profiles={filteredProfiles} onEdit={(p:Profile) => { setEditingProfile(p); setIsProfileModalOpen(true); }} onDelete={handleDeleteProfile} getBrandBadge={getBrandBadge} /></div>}
                {activeTab === 'Customers' && <div id="profile-customers-table"><CustomerTable customers={allCustomers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()))} onEdit={(c:Customer) => { setEditingCustomer(c); setIsCustomerModalOpen(true); }} onDelete={handleDeleteCustomer} /></div>}
            </div>

            <Portal><AddProfileModal isOpen={isProfileModalOpen} onClose={() => {setIsProfileModalOpen(false); setEditingProfile(null);}} onAdd={editingProfile ? (data) => handleUpdateProfile({...editingProfile, ...data}) : handleAddProfile} brands={brands} addToast={addToast} initialData={editingProfile} /></Portal>
            <Portal><CustomerModal isOpen={isCustomerModalOpen} onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} onSave={editingCustomer ? (data) => handleUpdateCustomer({...editingCustomer, ...data}) : handleAddCustomer} customer={editingCustomer} addToast={addToast} /></Portal>
            <Portal><TransactionModal isOpen={isTransactionModalOpen} onClose={() => { setIsTransactionModalOpen(false); setEditingTransaction(null); }} type={transactionType} profiles={stockData} onAdd={handleAddTransaction} addToast={addToast} customers={allCustomers} addCustomer={handleAddCustomer} /></Portal>
            <Portal><EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} onUpdate={handleUpdateTransaction} /></Portal>
            <Portal>
                <CreateQuotationModal 
                    isOpen={isQuotationModalOpen} 
                    onClose={() => {setIsQuotationModalOpen(false); setEditingQuotation(null);}} 
                    profiles={allProfiles} 
                    customers={allCustomers} 
                    onAddMultiple={(txs) => { txs.forEach(tx => addProfileTransaction(tx))}} 
                    addToast={addToast} 
                    existingTransactions={editingQuotation ? editingQuotation : undefined}
                    brands={brands}
                    addBrand={addBrand}
                    deleteBrand={deleteBrand}
                />
            </Portal>
            <Portal><CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} addToast={addToast} brands={brands} /></Portal>
            <Portal><ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
        </div>
    );
};

