// --- PDF GENERATOR HELPER ---
const numberToWords = (num: number): string => {
    const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
    const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

    const format = (n: number): string => {
        if (n < 20) return a[n];
        const digit = n % 10;
        if (n < 100) return b[Math.floor(n / 10)] + (digit !== 0 ? ' ' + a[digit] : '');
        if (n < 1000) return a[Math.floor(n / 100)] + 'Hundred ' + (n % 100 !== 0 ? 'and ' + format(n % 100) : '');
        return '';
    };

    if (num === 0) return 'Zero';
    let str = '';
    if (num >= 10000000) { str += format(Math.floor(num / 10000000)) + 'Crore '; num %= 10000000; }
    if (num >= 100000) { str += format(Math.floor(num / 100000)) + 'Lakh '; num %= 100000; }
    if (num >= 1000) { str += format(Math.floor(num / 1000)) + 'Thousand '; num %= 1000; }
    str += format(num);
    return str.trim() + ' Only';
};

// --- HOOKS ---
const useFilteredTransactions = (
    transactions: ProfileTransaction[], 
    profiles: Profile[], 
    searchTerm: string, 
    getProfile: (id: string) => Profile | undefined,
    type: 'PRODUCTION' | 'DISPATCH' | 'SCRAP' | 'QUOTATION'
) => {
    return useMemo(() => {
        const validProfileIds = new Set(profiles.map(p => p.id));
        let data;

        if (type === 'PRODUCTION') { 
                data = transactions.filter(t => (t.type === 'PRODUCTION' || t.type === 'RETURN') && validProfileIds.has(t.profileId));
        } else {
                data = transactions.filter(t => t.type === type && validProfileIds.has(t.profileId));
        }

        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            data = data.filter(t => {
                const profile = getProfile(t.profileId);
                return t.refNo.toLowerCase().includes(lowerSearch) ||
                        (profile && profile.name.toLowerCase().includes(lowerSearch)) ||
                        (profile && profile.sku.toLowerCase().includes(lowerSearch)) ||
                        (t.hsnCode && t.hsnCode.toLowerCase().includes(lowerSearch)) ||
                        (t.customer && t.customer.toLowerCase().includes(lowerSearch));
            });
        }

        return [...data].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [transactions, profiles, searchTerm, getProfile, type]);
};

const DashboardListModal: React.FC<{ isOpen: boolean; onClose: () => void; items: any[]; title: string; type?: 'value' | 'lowstock' | 'list' }> = ({ isOpen, onClose, items, title, type = 'list' }) => {
