                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <div className="flex flex-col items-center">
                                    <label className="cursor-pointer bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-white px-2 py-1.5 rounded text-[10px] font-bold hover:bg-gray-300 dark:hover:bg-gray-500 w-full text-center truncate">
                                        {newBrandLogo ? 'Left Selected' : 'Set Left Image'}
                                        <input type="file" accept="image/*" onChange={(e) => handleBrandLogoUpload(e, 'left')} className="hidden" />
                                    </label>
                                </div>
                                <div className="flex flex-col items-center">
                                    <label className="cursor-pointer bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-white px-2 py-1.5 rounded text-[10px] font-bold hover:bg-gray-300 dark:hover:bg-gray-500 w-full text-center truncate">
                                        {newBrandRightLogo ? 'Right Selected' : 'Set Right Image'}
                                        <input type="file" accept="image/*" onChange={(e) => handleBrandLogoUpload(e, 'right')} className="hidden" />
