                                    <label className="cursor-pointer bg-blue-600 text-white px-2 py-1 rounded text-[10px] font-bold hover:bg-blue-700 flex gap-1 items-center"><CloudUploadIcon className="w-3 h-3"/> Upload <input type="file" accept="image/*" onChange={(e) => handleLogoUpload(e, 'right')} className="hidden" /></label>
