                                    <label className="cursor-pointer bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-white px-2 py-1.5 rounded text-[10px] font-bold hover:bg-gray-300 dark:hover:bg-gray-500 w-full text-center truncate">
