    const [newBrandLogo, setNewBrandLogo] = useState('');
    const [newBrandRightLogo, setNewBrandRightLogo] = useState('');
    const [isLocalManageBrandsOpen, setIsLocalManageBrandsOpen] = useState(false);

    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { 
        if(isOpen) { 
            setForm(settings); 
            setLogoPreview(settings.logoUrl || ''); 
            setLogoRightPreview(settings.logoRightUrl || '');
            setPosition({ x: 0, y: 0 }); 
            if(brands && brands.length > 0) setSelectedBrand(brands[0]);
        } 
    }, [isOpen, settings, brands]);

    const onMouseDownHeader = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        setIsDragging(true);
        dragStart.current = { x: e.clientX, y: e.clientY };
        startPos.current = { ...position };
    };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                e.preventDefault();
                setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) });
            }
        };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) {
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }
        return () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [isDragging]);

    if(!isOpen) return null;

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>, side: 'left' | 'right') => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const result = reader.result as string;
                if (side === 'left') {
                    setForm({ ...form, logoUrl: result });
                    setLogoPreview(result);
                } else {
                    setForm({ ...form, logoRightUrl: result });
                    setLogoRightPreview(result);
                }
            };
            reader.readAsDataURL(file);
        }
    };

    const handleBrandLogoUpload = (e: React.ChangeEvent<HTMLInputElement>, side: 'left' | 'right') => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const result = reader.result as string;
                if (side === 'left') setNewBrandLogo(result);
                else setNewBrandRightLogo(result);
            };
            reader.readAsDataURL(file);
        }
    };

    const addBrandLogo = () => {
        if (!selectedBrand || (!newBrandLogo && !newBrandRightLogo)) {
            addToast('Please select a brand and upload at least one logo.', 'error');
            return;
        }
        const updatedLogos = form.brandLogos ? [...form.brandLogos] : [];
        const existingIndex = updatedLogos.findIndex((bl: BrandLogo) => bl.brand === selectedBrand);
        const newEntry = { 
            brand: selectedBrand, 
            logoUrl: newBrandLogo || (existingIndex > -1 ? updatedLogos[existingIndex].logoUrl : ''), 
            logoRightUrl: newBrandRightLogo || (existingIndex > -1 ? updatedLogos[existingIndex].logoRightUrl : '') 
        };
        if (existingIndex > -1) {
            updatedLogos[existingIndex] = newEntry;
        } else {
            updatedLogos.push(newEntry);
        }
        setForm({ ...form, brandLogos: updatedLogos });
        setNewBrandLogo('');
        setNewBrandRightLogo('');
        addToast(`Logos updated for ${selectedBrand}`, 'success');
    };

    const removeBrandLogo = (brand: string) => {
        const updatedLogos = form.brandLogos?.filter((bl: BrandLogo) => bl.brand !== brand) || [];
        setForm({ ...form, brandLogos: updatedLogos });
    };

    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white p-2 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none";
    const labelClass = "block text-xs font-medium mb-1 text-gray-700 dark:text-gray-300";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-5xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={onMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]"><h2 className="text-xl font-bold flex items-center gap-2"><WarehouseIcon className="w-6 h-6 text-blue-400"/> Company Settings</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button></div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                    <div className="flex flex-col md:flex-row gap-6 mb-6">
                        <div className="flex flex-col p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 flex-1">
                            <h3 className="font-bold text-gray-800 dark:text-gray-200 mb-2 uppercase text-xs tracking-wider">Default Header Logos</h3>
                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <div className="flex flex-col items-center">
                                    <span className="text-[10px] uppercase font-bold text-gray-500 mb-1">Left side</span>
                                    <div className="w-full h-24 bg-white dark:bg-black/20 border rounded-lg flex items-center justify-center overflow-hidden mb-2 shadow-sm">{logoPreview ? <img src={logoPreview} alt="L" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-400 text-[10px]">Empty</span>}</div>
                                    <label className="cursor-pointer bg-blue-600 text-white px-2 py-1 rounded text-[10px] font-bold hover:bg-blue-700 flex gap-1 items-center transition-colors"><CloudUploadIcon className="w-3 h-3"/> Upload <input type="file" accept="image/*" onChange={(e) => handleLogoUpload(e, 'left')} className="hidden" /></label>
                                </div>
                                <div className="flex flex-col items-center">
                                    <span className="text-[10px] uppercase font-bold text-gray-500 mb-1">Right side</span>
                                    <div className="w-full h-24 bg-white dark:bg-black/20 border rounded-lg flex items-center justify-center overflow-hidden mb-2 shadow-sm">{logoRightPreview ? <img src={logoRightPreview} alt="R" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-400 text-[10px]">Empty</span>}</div>
                                    <label className="cursor-pointer bg-blue-600 text-white px-2 py-1 rounded text-[10px] font-bold hover:bg-blue-700 flex gap-1 items-center transition-colors"><CloudUploadIcon className="w-3 h-3"/> Upload <input type="file" accept="image/*" onChange={(e) => handleLogoUpload(e, 'right')} className="hidden" /></label>
                                </div>
                            </div>
                        </div>

                        <div className="flex flex-col p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 flex-1">
                            <div className="flex justify-between items-center mb-2">
                                <h3 className="font-bold text-gray-800 dark:text-gray-200 uppercase text-xs tracking-wider">Brand Overrides</h3>
                                <button onClick={() => setIsLocalManageBrandsOpen(true)} className="text-[10px] text-blue-600 flex items-center gap-1 font-bold hover:underline"><PencilIcon className="w-2.5 h-2.5"/> Manage Brands</button>
                            </div>
                            <div className="flex gap-2 mb-3">
                                <select value={selectedBrand} onChange={e => setSelectedBrand(e.target.value)} className="w-full p-2 rounded border text-sm dark:bg-gray-700 dark:text-white">
                                    <option value="" disabled>Select Brand</option>
                                    {brands.map((b: string) => <option key={b} value={b}>{b}</option>)}
                                </select>
                            </div>
                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <div className="flex flex-col items-center">
                                    <label className="cursor-pointer bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-white px-2 py-1.5 rounded text-[10px] font-bold hover:bg-gray-300 dark:hover:bg-gray-500 w-full text-center truncate transition-colors">
                                        {newBrandLogo ? 'Left Loaded' : 'Set Left Logo'}
                                        <input type="file" accept="image/*" onChange={(e) => handleBrandLogoUpload(e, 'left')} className="hidden" />
                                    </label>
                                </div>
                                <div className="flex flex-col items-center">
                                    <label className="cursor-pointer bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-white px-2 py-1.5 rounded text-[10px] font-bold hover:bg-gray-300 dark:hover:bg-gray-500 w-full text-center truncate transition-colors">
                                        {newBrandRightLogo ? 'Right Loaded' : 'Set Right Logo'}
                                        <input type="file" accept="image/*" onChange={(e) => handleBrandLogoUpload(e, 'right')} className="hidden" />
                                    </label>
                                </div>
