                            <button onClick={addBrandLogo} className="bg-green-600 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-green-700 w-full mb-3 shadow-sm transition-colors">Save Brand Logos</button>

                            <div className="flex-1 overflow-y-auto max-h-40 border-t border-gray-200 dark:border-gray-600 pt-2 space-y-1">
