                                {(!form.brandLogos || form.brandLogos.length === 0) && <p className="text-[10px] text-gray-500 text-center italic">No brand overrides.</p>}
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200 uppercase text-xs">General Information</h3><div><label className={labelClass}>Company Name</label><input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>GSTIN</label><input value={form.gstin} onChange={e => setForm({...form, gstin: e.target.value})} className={inputClass} /></div><div className="grid grid-cols-2 gap-3"><div><label className={labelClass}>Phone</label><input value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Email</label><input value={form.email} onChange={e => setForm({...form, email: e.target.value})} className={inputClass} /></div></div></div>
