// --- TRANSACTION FILTER HOOK ---
const useFilteredTransactions = (allTxns: any[], profiles: any[], searchTerm: string, getProfile: any, type: string) => {
    return useMemo(() => {
        let txns = allTxns.filter(t => t.type === type && !t.deletedAt);
        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            txns = txns.filter(t => {
                const p = getProfile(t.profileId);
                return t.refNo.toLowerCase().includes(lower) || 
                       p?.name.toLowerCase().includes(lower) || 
                       p?.sku.toLowerCase().includes(lower) ||
                       (t.customer && t.customer.toLowerCase().includes(lower)) ||
                       (t.profileNameOverride && t.profileNameOverride.toLowerCase().includes(lower)) ||
                       (t.profileSkuOverride && t.profileSkuOverride.toLowerCase().includes(lower));
            });
        }
        return txns.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [allTxns, profiles, searchTerm, getProfile, type]);
};

// --- PDF GENERATOR HELPER ---
const numberToWords = (num: number): string => {
    const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
    const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

    const format = (n: number): string => {
        if (n < 20) return a[n];
        const digit = n % 10;
        if (n < 100) return b[Math.floor(n / 10)] + (digit !== 0 ? ' ' + a[digit] : '');
        if (n < 1000) return a[Math.floor(n / 100)] + 'Hundred ' + (n % 100 !== 0 ? 'and ' + format(n % 100) : '');
        return '';
    };

    if (num === 0) return 'Zero';
    let str = '';
    if (num >= 10000000) { str += format(Math.floor(num / 10000000)) + 'Crore '; num %= 10000000; }
    if (num >= 100000) { str += format(Math.floor(num / 100000)) + 'Lakh '; num %= 100000; }
    if (num >= 1000) { str += format(Math.floor(num / 1000)) + 'Thousand '; num %= 1000; }
    str += format(num);
    return str.trim() + ' Only';
};

// --- DASHBOARD VIEW ---
const ProfileDashboard: React.FC<any> = ({ profiles, transactions, stockData }) => {
    const chartRef = useRef<HTMLCanvasElement>(null);
    const chartInstance = useRef<any>(null);

    useEffect(() => {
        if (!chartRef.current || typeof Chart === 'undefined') return;
        const ctx = chartRef.current.getContext('2d');
        if (!ctx) return;

        if (chartInstance.current) chartInstance.current.destroy();

        const sorted = [...stockData].sort((a,b) => (b.currentStock - b.reservedStock) - (a.currentStock - a.reservedStock)).slice(0, 5);

        chartInstance.current = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: sorted.map(p => p.sku),
                datasets: [{
                    label: 'Available Stock',
                    data: sorted.map(p => p.currentStock - p.reservedStock),
                    backgroundColor: '#3B82F6'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } }
            }
        });

        return () => { if (chartInstance.current) chartInstance.current.destroy(); };
    }, [stockData]);

    const totalActual = stockData.reduce((sum: number, p: any) => sum + p.currentStock, 0);
    const totalReserved = stockData.reduce((sum: number, p: any) => sum + p.reservedStock, 0);
    const lowStockCount = stockData.filter((p: any) => (p.currentStock - p.reservedStock) < (p.reorderPoint || 0)).length;

    return (
        <div className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-800">
                    <h3 className="text-sm font-bold text-blue-800 dark:text-blue-300 uppercase">Total Actual Stock</h3>
                    <p className="text-3xl font-black mt-2 text-blue-900 dark:text-white">{totalActual.toLocaleString()}</p>
                </Card>
                <Card className="bg-orange-50 dark:bg-orange-900/20 border border-orange-100 dark:border-orange-800">
                    <h3 className="text-sm font-bold text-orange-800 dark:text-orange-300 uppercase">Reserved (Quotations)</h3>
                    <p className="text-3xl font-black mt-2 text-orange-900 dark:text-white">{totalReserved.toLocaleString()}</p>
                </Card>
                <Card className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800">
                    <h3 className="text-sm font-bold text-red-800 dark:text-red-300 uppercase">Low Stock Alerts</h3>
                    <p className="text-3xl font-black mt-2 text-red-900 dark:text-white">{lowStockCount}</p>
                </Card>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <Card className="h-80">
                    <h3 className="font-bold mb-4">Top 5 Profiles by Available Stock</h3>
                    <div className="h-60"><canvas ref={chartRef}></canvas></div>
                </Card>
                <Card className="h-80 overflow-y-auto">
                    <h3 className="font-bold mb-4">Recent Transactions</h3>
                    <div className="space-y-3">
                        {transactions.slice(0, 10).map((t: any) => (
                            <div key={t.id} className="flex justify-between items-center text-sm border-b dark:border-gray-700 pb-2">
                                <div>
                                    <span className={`font-bold ${t.type === 'PRODUCTION' ? 'text-green-600' : 'text-red-600'}`}>{t.type}</span>
                                    <span className="ml-2 text-gray-500">{t.refNo}</span>
                                </div>
                                <div className="text-right">
                                    <div className="font-medium">{t.quantity} Pcs</div>
                                    <div className="text-[10px] text-gray-400">{new Date(t.date).toLocaleDateString()}</div>
                                </div>
                            </div>
