const ManageBrandsModal: React.FC<any> = ({ isOpen, onClose, brands, addBrand, updateBrand, deleteBrand, addToast }) => {
    const [newB, setNewB] = useState('');
    const [editingBrand, setEditingBrand] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');

    if (!isOpen) return null;

    const handleAdd = () => { 
        if (newB.trim() && !brands.includes(newB.trim())) { 
            addBrand(newB.trim()); 
            setNewB(''); 
        } else { 
            addToast('Brand already exists or is empty.', 'error'); 
        } 
    };

    const handleStartEdit = (brand: string) => {
        setEditingBrand(brand);
        setEditValue(brand);
    };

    const handleSaveEdit = () => {
        if (editingBrand && editValue.trim() && (editValue.trim() === editingBrand || !brands.includes(editValue.trim()))) {
            updateBrand(editingBrand, editValue.trim());
            setEditingBrand(null);
            addToast('Brand updated successfully.', 'success');
        } else {
            addToast('Brand already exists or is empty.', 'error');
        }
    };

    const handleDelete = (e: React.MouseEvent, brand: string) => { 
        e.stopPropagation(); 
        if(confirm(`Are you sure you want to delete brand "${brand}"? All profiles with this brand will be updated.`)) {
            deleteBrand(brand); 
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[120] flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-sm shadow-2xl" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold text-lg mb-4 dark:text-white">Manage Brands</h3>
                <div className="flex gap-2 mb-6">
                    <input 
                        value={newB} 
                        onChange={e => setNewB(e.target.value)} 
                        className="border border-gray-300 dark:border-gray-600 p-2 flex-1 rounded dark:bg-gray-700 dark:text-white text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                        placeholder="New Brand Name" 
                    />
                    <button onClick={handleAdd} className="bg-blue-600 text-white px-4 py-2 rounded text-sm font-bold shadow hover:bg-blue-700 transition-colors">Add</button>
                </div>
                <div className="max-h-64 overflow-y-auto border border-gray-200 dark:border-gray-700 rounded-md bg-gray-50 dark:bg-gray-900/30">
                    {brands.map((b:string) => (
                        <div key={b} className="flex justify-between items-center p-3 border-b border-gray-200 dark:border-gray-700 last:border-0">
                            {editingBrand === b ? (
                                <div className="flex flex-1 gap-1">
                                    <input 
                                        autoFocus
                                        value={editValue} 
                                        onChange={e => setEditValue(e.target.value)} 
                                        className="border border-blue-400 p-1 flex-1 rounded text-xs dark:bg-gray-700 dark:text-white outline-none" 
                                    />
                                    <button onClick={handleSaveEdit} className="text-green-500 text-xs font-bold">Save</button>
                                    <button onClick={() => setEditingBrand(null)} className="text-gray-400 text-xs">Esc</button>
                                </div>
                            ) : (
                                <>
                                    <span className="text-sm font-medium dark:text-gray-200">{b}</span>
                                    <div className="flex gap-3">
                                        <button onClick={() => handleStartEdit(b)} className="text-blue-500 hover:text-blue-700" title="Edit Brand"><PencilIcon className="w-3.5 h-3.5"/></button>
                                        <button onClick={(e) => handleDelete(e, b)} className="text-red-500 hover:text-red-700" title="Delete Brand"><TrashIcon className="w-3.5 h-3.5"/></button>
