    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { 
        if(isOpen) { 
            setForm(settings); 
            setLogoPreview(settings.logoUrl || ''); 
            setLogoRightPreview(settings.logoRightUrl || '');
            setPosition({ x: 0, y: 0 }); 
            if(brands && brands.length > 0) setSelectedBrand(brands[0]);
        } 
    }, [isOpen, settings, brands]);

    const onMouseDownHeader = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        setIsDragging(true);
        dragStart.current = { x: e.clientX, y: e.clientY };
        startPos.current = { ...position };
    };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                e.preventDefault();
                setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) });
            }
        };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) {
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }
        return () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [isDragging]);

    if(!isOpen) return null;

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>, side: 'left' | 'right') => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const result = reader.result as string;
                if (side === 'left') {
                    setForm({ ...form, logoUrl: result });
                    setLogoPreview(result);
                } else {
                    setForm({ ...form, logoRightUrl: result });
                    setLogoRightPreview(result);
                }
            };
            reader.readAsDataURL(file);
        }
    };

    const handleBrandLogoUpload = (e: React.ChangeEvent<HTMLInputElement>, side: 'left' | 'right') => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
