const StockTable: React.FC<any> = ({ stockData, onEditProfile, getBrandBadge }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Name</th><th className="px-6 py-3 text-right">Actual</th><th className="px-6 py-3 text-right">Reserved</th><th className="px-6 py-3 text-right font-black">Available</th><th className="px-6 py-3 text-right no-print">Action</th></tr>
        </thead>
        <tbody>
            {stockData.map((p: any) => {
                const available = p.currentStock - p.reservedStock;
                return (
                    <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                        <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4 font-bold">{p.sku}</td><td className="px-6 py-4">{p.name}</td><td className="px-6 py-4 text-right">{p.currentStock}</td><td className="px-6 py-4 text-right text-orange-500">{p.reservedStock > 0 ? `-${p.reservedStock}` : '0'}</td><td className={`px-6 py-4 text-right font-black ${available < (p.reorderPoint || 0) ? 'text-red-600' : 'text-blue-600'}`}>{available}</td><td className="px-6 py-4 text-right no-print"><button onClick={() => onEditProfile(p)} className="text-blue-500 hover:underline">Edit</button></td>
                    </tr>
                );
            })}
        </tbody>
    </table>
);

