                    <td className="px-6 py-4 text-right space-x-2 whitespace-nowrap"><button onClick={() => onPrint(group)} className="text-gray-500">🖨️</button><button onClick={() => onEdit(group.refNo)} className="text-blue-500"><PencilIcon className="w-3.5 h-3.5"/></button><button onClick={() => onDelete(group.refNo)} className="text-red-500"><TrashIcon className="w-3.5 h-3.5"/></button></td>
