const TransactionModal: React.FC<any> = ({ isOpen, onClose, type, profiles, onAdd, addToast, customers, addCustomer }) => {
    const [form, setForm] = useState({ profileId: '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' });
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    useEffect(() => { 
        if(isOpen) { 
            setForm({ profileId: profiles[0]?.id || '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' }); 
        } 
    }, [isOpen, profiles]);
    if(!isOpen) return null;
    const filteredCustomers = customers.filter((c:any) => c.name.toLowerCase().includes(customerSearch.toLowerCase()) && !c.deletedAt);
    const selectCustomer = (c: any) => { setForm(prev => ({ ...prev, customer: c.name, customerAddress: c.address || '', customerGST: c.gstin || '', customerPhone: c.phone || '' })); setCustomerSearch(c.name); setShowSuggestions(false); };
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); onAdd({ ...form, quantity: parseFloat(form.quantity), type }); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white focus:ring-1 focus:ring-blue-500 outline-none";
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[160] flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="px-6 py-4 bg-gray-900 text-white rounded-t-xl flex justify-between items-center"><h2 className="text-xl font-bold">{type}</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl">&times;</button></div>
                <div className="p-6 overflow-y-auto"><form onSubmit={handleSubmit} className="space-y-3">
                    <div><label className="text-xs font-bold uppercase text-gray-500">Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required /></div>
                    <div><label className="text-xs font-bold uppercase text-gray-500">Profile</label><select value={form.profileId} onChange={e => setForm({...form, profileId: e.target.value})} className={inputClass} required>{profiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select></div>
                    <div><label className="text-xs font-bold uppercase text-gray-500">Ref No</label><input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} required /></div>
