const ManageBrandsModal: React.FC<any> = ({ isOpen, onClose, brands, addBrand, updateBrand, deleteBrand, addToast }) => {
    const [newB, setNewB] = useState('');
    const [editingBrand, setEditingBrand] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');
    if (!isOpen) return null;
    const handleAdd = () => { if (newB.trim() && !brands.includes(newB.trim())) { addBrand(newB.trim()); setNewB(''); } else { addToast('Brand already exists or invalid.', 'error'); } };
    const handleSaveEdit = () => { if (editingBrand && editValue.trim() && !brands.includes(editValue.trim())) { updateBrand(editingBrand, editValue.trim()); setEditingBrand(null); } };
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[160] flex justify-center items-center p-4" onClick={onClose}>
