                <div className="flex gap-2 mb-4"><input value={newB} onChange={e => setNewB(e.target.value)} className="border dark:border-gray-600 p-2 flex-1 rounded dark:bg-gray-700 dark:text-white" placeholder="New Brand"/><button onClick={handleAdd} className="bg-blue-600 text-white px-4 rounded font-bold hover:bg-blue-700">Add</button></div>
                <div className="max-h-60 overflow-y-auto border dark:border-gray-700 rounded bg-gray-50 dark:bg-gray-900/50">{brands.map((b:string) => (<div key={b} className="flex justify-between p-3 border-b dark:border-gray-700">{editingBrand === b ? (<><input value={editValue} onChange={e => setEditValue(e.target.value)} className="border p-1 rounded flex-1 dark:bg-gray-700 dark:text-white"/><button onClick={handleSaveEdit} className="text-green-500 font-bold ml-2">Save</button></>) : (<><span className="font-bold dark:text-gray-200">{b}</span><div className="flex gap-2"><button onClick={() => { setEditingBrand(b); setEditValue(b); }} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteBrand(b)} className="text-red-500 hover:underline">Del</button></div></>)}</div>))}</div>
                <button onClick={onClose} className="mt-6 w-full py-2 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-white rounded font-black hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors">Close</button>
            </div>
        </div>
    );
};

