                    <div><label className="text-xs font-bold uppercase text-gray-500 mb-1 block">GSTIN</label><input value={form.gstin} onChange={e => setForm({...form, gstin: e.target.value})} className="w-full border dark:border-gray-600 p-2 rounded dark:bg-gray-700 dark:text-white" /></div>
