                <div className="mt-8 flex justify-end gap-3"><button onClick={onClose} className="px-6 py-2 border dark:border-gray-600 rounded font-bold dark:text-gray-300">Cancel</button><button onClick={() => { updateSettings(form); addToast('Settings Saved!', 'success'); onClose(); }} className="px-6 py-2 bg-blue-600 text-white rounded font-bold shadow hover:bg-blue-700 transition-colors">Save Changes</button></div>
