export default ProfileSection;

import React, { useState, useEffect, useMemo } from 'react';
import type { Profile, ProfileTransaction, InvoiceDetails, Customer, ToastMessage } from '../types';
import { TrashIcon, PencilIcon } from './Icon';
import { createPortal } from 'react-dom';

interface CreateQuotationModalProps {
    isOpen: boolean;
    onClose: () => void;
    profiles: Profile[];
    customers: Customer[];
    onAddMultiple: (txs: Omit<ProfileTransaction, 'id' | 'createdAt'>[]) => void;
    addCustomer: (customer: Omit<Customer, 'id' | 'createdAt' | 'deletedAt'>) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
    existingTransactions?: ProfileTransaction[];
    brands: string[];
    addBrand: (brand: string) => void;
    deleteBrand: (brand: string) => void;
}

interface QuotationItem {
    id: number;
    profileId: string;
    description: string; 
    hsnCode: string;
    profileCode: string; 
    packets: number;
    lengthsPerPacket: number;
    quantity: number; 
    weight: number; 
    price: number;
    amount: number;
    brand?: string; 
}

const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};

const CreateQuotationModal: React.FC<CreateQuotationModalProps> = ({ isOpen, onClose, profiles, customers, onAddMultiple, addCustomer, addToast, existingTransactions, brands, addBrand, deleteBrand }) => {
    const [invoiceData, setInvoiceData] = useState<InvoiceDetails>({
        category: 'Tax Invoice',
        reverseCharge: 'No',
        documentType: 'Tax Invoice',
        documentNo: '',
        documentDate: new Date().toISOString().split('T')[0],
        legalName: '',
        address1: '',
        address2: '',
        location: '',
        pincode: '',
        phone: '',
        gstin: '',
        state: 'Telangana',
        email: '',
        placeOfSupply: 'Telangana',
        igstOnIntra: 'No',
        transactionType: 'Regular',
        totalTaxable: 0,
        igstValue: 0,
        sgstValue: 0,
        cgstValue: 0,
        cessAdvolValue: 0,
        cessNonAdValue: 0,
        stateCessValue: 0,
        totalAmount: 0
    });

    const [items, setItems] = useState<QuotationItem[]>([]);
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [brandFilter, setBrandFilter] = useState('All');
    const [isLocalManageBrandsOpen, setIsLocalManageBrandsOpen] = useState(false);

    const availableBrands = useMemo(() => {
        return ['All', ...brands];
    }, [brands]);

    const filteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return profiles;
        return profiles.filter(p => p.brand === brandFilter);
    }, [profiles, brandFilter]);

    useEffect(() => {
        if (isOpen) {
            setBrandFilter('All');
            if (existingTransactions && existingTransactions.length > 0) {
                const first = existingTransactions[0];
                if (first.invoiceDetails) {
                    setInvoiceData(first.invoiceDetails);
                    setCustomerSearch(first.invoiceDetails.legalName);
                } else {
                    setInvoiceData(prev => ({
                        ...prev,
                        documentNo: first.refNo,
                        legalName: first.customer || '',
                        documentDate: (first.date || '').split('T')[0]
                    }));
                    setCustomerSearch(first.customer || '');
                }

                const mappedItems = existingTransactions.map((tx, idx) => {
                    const p = profiles.find(prof => prof.id === tx.profileId);
                    return {
                        id: Date.now() + idx,
                        profileId: tx.profileId,
                        description: tx.profileNameOverride || p?.name || 'Unknown',
                        hsnCode: tx.hsnCode || p?.hsnCode || '39252000',
                        profileCode: tx.profileSkuOverride || p?.sku || '',
                        packets: Number(tx.packets || Math.ceil(tx.quantity / (tx.piecesPerPacket || p?.piecesPerPacket || 1))),
                        lengthsPerPacket: Number(tx.piecesPerPacket || p?.piecesPerPacket || 1),
                        quantity: Number(tx.quantity || 0),
                        weight: Number(tx.weight || p?.weight || 0),
                        price: Number(tx.unitPrice || p?.price || 0),
                        amount: Number(tx.quantity || 0) * Number(tx.unitPrice || p?.price || 0),
                        brand: tx.brand || p?.brand
                    };
                });
                setItems(mappedItems);
            } else {
                setInvoiceData(prev => ({
                    ...prev,
                    documentNo: `QT-${Date.now().toString().slice(-6)}`,
                    documentDate: new Date().toISOString().split('T')[0],
                    legalName: '',
                    address1: '',
                    gstin: '',
                    phone: '',
                    placeOfSupply: 'Telangana',
                    totalTaxable: 0,
                    igstValue: 0,
                    sgstValue: 0,
                    cgstValue: 0,
                    totalAmount: 0
                }));
                setItems([]);
                setCustomerSearch('');
            }
        }
    }, [isOpen, existingTransactions, profiles]);

    const filteredCustomers = useMemo(() => {
        if (!customerSearch) return [];
        return customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase()));
    }, [customers, customerSearch]);

    const handleCustomerSelect = (customer: Customer) => {
        setInvoiceData(prev => ({
            ...prev,
            legalName: customer.name,
            address1: customer.address || '',
            gstin: customer.gstin || '',
            phone: customer.phone || '',
        }));
        setCustomerSearch(customer.name);
        setShowSuggestions(false);
    };

    const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setInvoiceData(prev => ({ ...prev, [name]: value }));
    };

    const addItem = () => {
        setItems(prev => [...prev, { 
            id: Date.now(), 
            profileId: '', 
            description: '',
            hsnCode: '39252000',
            profileCode: '',
            packets: 0,
            lengthsPerPacket: 1,
            quantity: 1, 
            weight: 0,
            price: 0, 
            amount: 0,
            brand: ''
        }]);
    };

    const updateItem = (id: number, field: keyof QuotationItem, value: any) => {
        setItems(prev => prev.map(item => {
            if (item.id === id) {
                const updated = { ...item, [field]: value };

                if (field === 'profileId') {
                    const profile = profiles.find(p => p.id === value);
                    updated.description = profile?.name || '';
                    updated.hsnCode = profile?.hsnCode || '39252000';
                    updated.profileCode = profile?.sku || '';
                    updated.lengthsPerPacket = Number(profile?.piecesPerPacket || 1);
                    updated.weight = Number(profile?.weight || 0);
                    updated.price = Number(profile?.price || 0);
                    updated.brand = profile?.brand || '';
                    updated.quantity = Number(updated.packets) * Number(updated.lengthsPerPacket) || updated.quantity;
                }

                if (field === 'packets' || field === 'lengthsPerPacket') {
                    updated.quantity = (Number(updated.packets) || 0) * (Number(updated.lengthsPerPacket) || 0);
                }

                if (field === 'quantity') {
                    updated.packets = Math.ceil((Number(updated.quantity) || 0) / (Number(updated.lengthsPerPacket) || 1));
                }

                updated.amount = (Number(updated.quantity) || 0) * (Number(updated.price) || 0);
                return updated;
            }
            return item;
        }));
    };

    const removeItem = (id: number) => {
        setItems(prev => prev.filter(item => item.id !== id));
    };

    const clearAllItems = () => setItems([]);

    useEffect(() => {
        const totalTaxable = items.reduce((sum, item) => sum + item.amount, 0);
        const isInterState = invoiceData.placeOfSupply.toLowerCase() !== invoiceData.state.toLowerCase();
        const taxRate = 0.18;
        let igst = 0, cgst = 0, sgst = 0;
        if (isInterState) {
            igst = totalTaxable * taxRate;
        } else {
            cgst = totalTaxable * (taxRate / 2);
            sgst = totalTaxable * (taxRate / 2);
        }
        setInvoiceData(prev => ({
            ...prev,
            totalTaxable,
            igstValue: parseFloat(igst.toFixed(2)),
            cgstValue: parseFloat(cgst.toFixed(2)),
            sgstValue: parseFloat(sgst.toFixed(2)),
            totalAmount: Math.round(totalTaxable + igst + cgst + sgst)
        }));
    }, [items, invoiceData.placeOfSupply, invoiceData.state]);

    const handleSave = () => {
        const customerName = invoiceData.legalName.trim();
        if (!customerName) {
            addToast('Legal Name is required.', 'error');
            return;
        }
        if (items.length === 0) {
            addToast('Please add at least one item.', 'error');
            return;
        }

        // AUTO-SAVE CUSTOMER LOGIC
        const existingCustomer = customers.find(c => c.name.toLowerCase() === customerName.toLowerCase());
        if (!existingCustomer) {
            addCustomer({
                name: customerName,
                address: invoiceData.address1,
                gstin: invoiceData.gstin,
                phone: invoiceData.phone
            });
            addToast(`New customer "${customerName}" saved automatically.`, 'info');
        }

        const transactions: Omit<ProfileTransaction, 'id' | 'createdAt'>[] = items.map(item => ({
            profileId: item.profileId,
            type: 'QUOTATION',
            quantity: Number(item.quantity),
            uom: 'Pcs',
            date: new Date(invoiceData.documentDate).toISOString(),
            refNo: invoiceData.documentNo,
            status: 'PENDING',
            customer: customerName,
            customerAddress: invoiceData.address1,
            customerGST: invoiceData.gstin,
            customerPhone: invoiceData.phone,
            unitPrice: Number(item.price),
            hsnCode: item.hsnCode,
            weight: Number(item.weight),
            piecesPerPacket: Number(item.lengthsPerPacket),
            packets: Number(item.packets),
            profileNameOverride: item.description,
            profileSkuOverride: item.profileCode,
            brand: item.brand,
            invoiceDetails: invoiceData
        }));

        onAddMultiple(transactions);
        addToast(existingTransactions ? 'Quotation updated successfully.' : 'Quotation saved successfully.', 'success');
        onClose();
    };

    if (!isOpen) return null;

    const labelStyle = "block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1";
    const inputStyle = "w-full text-sm border border-gray-300 dark:border-gray-600 rounded-md px-3 py-2 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all";
    const sectionHeaderStyle = "font-black text-white px-4 py-2 bg-[#4A5E80] text-[10px] uppercase tracking-widest";

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 z-[100] flex justify-center items-center p-2" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-7xl h-[95vh] flex flex-col overflow-hidden border border-gray-200 dark:border-gray-700" onClick={e => e.stopPropagation()}>

                <div className="flex flex-col md:flex-row h-1/3">
                    <div className="w-full md:w-1/4 border-r dark:border-gray-700 flex flex-col">
                        <div className={sectionHeaderStyle}>Document Info</div>
                        <div className="p-4 space-y-3 bg-gray-50 dark:bg-gray-900/50 h-full overflow-y-auto">
                            <div>
                                <label className={labelStyle}>Category</label>
                                <select name="category" value={invoiceData.category} onChange={handleHeaderChange} className={inputStyle}>
                                    <option className="bg-white dark:bg-gray-800">Tax Invoice</option>
                                    <option className="bg-white dark:bg-gray-800">Proforma Invoice</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelStyle}>Ref No.</label>
                                <input name="documentNo" value={invoiceData.documentNo} onChange={handleHeaderChange} className={`${inputStyle} font-mono`} />
                            </div>
                            <div>
                                <label className={labelStyle}>Date</label>
                                <input type="date" name="documentDate" value={invoiceData.documentDate} onChange={handleHeaderChange} className={inputStyle} />
                            </div>
                        </div>
                    </div>

                    <div className="w-full md:w-1/2 border-r dark:border-gray-700 flex flex-col">
                        <div className={sectionHeaderStyle}>Billing Details</div>
                        <div className="p-4 grid grid-cols-2 gap-x-4 gap-y-3 bg-gray-50 dark:bg-gray-900/50 h-full overflow-y-auto">
                            <div className="relative col-span-2">
                                <label className={labelStyle}>Customer Name (Auto-saves new)</label>
                                <input 
                                    value={customerSearch} 
                                    onChange={(e) => { 
                                        setCustomerSearch(e.target.value); 
                                        setInvoiceData(prev => ({ ...prev, legalName: e.target.value })); 
                                        setShowSuggestions(true); 
                                    }}
                                    onFocus={() => setShowSuggestions(true)}
                                    className={inputStyle} 
                                    placeholder="Search existing or type new name..."
                                />
                                {showSuggestions && customerSearch && filteredCustomers.length > 0 && (
                                    <div className="absolute gap-2 z-50 w-full bg-white dark:bg-gray-800 border dark:border-gray-600 shadow-2xl rounded-md mt-1 max-h-48 overflow-y-auto ring-1 ring-black ring-opacity-5">
                                        {filteredCustomers.map(c => (
                                            <div key={c.id} className="px-4 py-3 hover:bg-blue-600 hover:text-white cursor-pointer text-sm font-bold border-b last:border-0 dark:border-gray-700 transition-colors" onClick={() => handleCustomerSelect(c)}>
                                                <div className="flex justify-between">
                                                    <span>{c.name}</span>
                                                    <span className="text-[10px] opacity-70">{c.gstin || 'No GST'}</span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                            <div><label className={labelStyle}>GSTIN</label><input name="gstin" value={invoiceData.gstin} onChange={handleHeaderChange} className={`${inputStyle} font-mono uppercase`} /></div>
                            <div><label className={labelStyle}>Phone No.</label><input name="phone" value={invoiceData.phone} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div className="col-span-2"><label className={labelStyle}>Address</label><input name="address1" value={invoiceData.address1} onChange={handleHeaderChange} className={inputStyle} /></div>
                        </div>
                    </div>

                    <div className="w-full md:w-1/4 flex flex-col">
                        <div className={sectionHeaderStyle}>Transaction Settings</div>
                        <div className="p-4 space-y-3 bg-gray-50 dark:bg-gray-900/50 h-full">
                            <div>
                                <label className={labelStyle}>Transaction Type</label>
                                <select name="transactionType" value={invoiceData.transactionType} onChange={handleHeaderChange} className={inputStyle}>
                                    <option className="bg-white dark:bg-gray-800">Regular</option>
                                    <option className="bg-white dark:bg-gray-800">Bill To - Ship To</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelStyle}>Place of Supply</label>
                                <input name="placeOfSupply" value={invoiceData.placeOfSupply} onChange={handleHeaderChange} className={inputStyle} />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-[#2D89C8] text-white px-4 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                    <div className="flex items-center gap-4">
