                    <td className="px-6 py-4"><div className="font-bold text-gray-900 dark:text-white">{t.profileNameOverride || getProfileName(t.profileId)}</div><div className="text-[10px] text-gray-500 font-mono">{t.profileSkuOverride || getProfile(t.profileId)?.sku}</div></td>
                    <td className={`px-6 py-4 text-right font-black ${type === 'PRODUCTION' ? 'text-green-600' : 'text-red-600'}`}>{t.quantity}</td>
                    {type === 'DISPATCH' && <td className="px-6 py-4 text-xs max-w-[150px] truncate">{t.customer}</td>}
                    <td className="px-6 py-4 text-right space-x-3 no-print whitespace-nowrap">{type === 'DISPATCH' && <button onClick={() => onPrint(t)} className="text-gray-500 hover:text-gray-900 dark:hover:text-white transition-colors" title="Print Dispatch Note">🖨️</button>}<button onClick={() => onEdit(t)} className="text-blue-500 hover:text-blue-700 transition-colors">Edit</button><button onClick={() => onDelete(t.id)} className="text-red-500 hover:text-red-700 transition-colors">Del</button></td>
                </tr>
            ))}
        </tbody>
    </table>
);

const QuotationTable: React.FC<any> = ({ groupedQuotations, onAction, onEdit, onDelete, onPrint, getBrandBadge }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">Date</th><th className="px-6 py-3">Name</th><th className="px-6 py-3 text-right">Total Amount</th><th className="px-6 py-3 text-center">Action</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-right">Actions</th></tr>
