        <tbody>
            {groupedQuotations.map((group: any) => (
                <tr key={group.refNo} className={`border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors ${group.status === 'CANCELLED' ? 'opacity-50' : ''}`}>
                    <td className="px-6 py-4">{getBrandBadge(group.brand)}</td><td className="px-6 py-4 whitespace-nowrap text-xs font-mono">{new Date(group.date).toLocaleDateString()}</td>
                    <td className="px-6 py-4"><span className="font-bold block text-xs">{group.customer}</span><div className="text-[10px] text-gray-500 font-mono">{group.refNo}</div></td>
                    <td className="px-6 py-4 text-right font-black text-gray-900 dark:text-white text-xs">₹ {group.totalAmount.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</td>
                    <td className="px-6 py-4 text-center">
