        if (logoRight) try { doc.addImage(logoRight, 'JPEG', 165, 10, 30, 15); } catch (e) {}

        doc.setFontSize(22); doc.setTextColor(165, 42, 42); doc.text("RAVIRAJA", 195, 20, { align: 'right' });
        doc.setFontSize(10); doc.setTextColor(0, 0, 0); doc.text("Industries Pvt. Ltd.", 195, 25, { align: 'right' });
        doc.setFontSize(14); doc.setFont("helvetica", "bold"); doc.text(isQuotation ? "QUOTATION" : "DISPATCH NOTE", 105, 35, { align: 'center' });

        doc.autoTable({
            startY: 40, theme: 'grid', styles: { fontSize: 8 },
            body: [
                [ { content: 'Supplier Registered Address', styles: { fontStyle: 'bold', fillColor: [240,240,240] } }, { content: 'Factory Address', styles: { fontStyle: 'bold', fillColor: [240,240,240] } } ],
