// --- DASHBOARD LIST MODAL ---
const DashboardListModal: React.FC<{ isOpen: boolean; onClose: () => void; items: any[]; title: string; type?: 'value' | 'lowstock' | 'list' }> = ({ isOpen, onClose, items, title, type = 'list' }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const sortedItems = useMemo(() => {
        let sorted = [...items];
        if (type === 'value') sorted.sort((a, b) => (b.currentStock * (b.price || 0)) - (a.currentStock * (a.price || 0)));
        else if (type === 'lowstock') sorted.sort((a, b) => (a.currentStock - a.reservedStock) - (b.currentStock - b.reservedStock));
        else sorted.sort((a, b) => a.name.localeCompare(b.name));
        return sorted;
    }, [items, type]);

    const filtered = useMemo(() => sortedItems.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [sortedItems, searchTerm]);
    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[150] flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl p-6 w-full max-w-3xl flex flex-col h-[80vh]" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">{title}</h2>
                    <div className="relative">
                        <input autoFocus type="text" placeholder="Search..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md focus:ring-blue-500 focus:border-blue-500 w-64 dark:text-white" />
                        <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    </div>
                </div>
                <div className="overflow-y-auto flex-1 bg-gray-50 dark:bg-gray-900/50 rounded border dark:border-gray-700">
                    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="bg-gray-100 dark:bg-gray-700 text-xs uppercase text-gray-700 dark:text-gray-300 sticky top-0">
                            <tr>
                                <th className="px-6 py-3">SKU</th><th className="px-6 py-3">Name</th><th className="px-6 py-3 text-right">Available</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filtered.map(p => (
                                <tr key={p.id} className="border-b dark:border-gray-700 hover:bg-white dark:hover:bg-gray-800 transition-colors">
                                    <td className="px-6 py-4 font-medium">{p.sku}</td><td className="px-6 py-4">{p.name}</td>
                                    <td className="px-6 py-4 text-right font-bold">{p.currentStock - p.reservedStock}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                <div className="mt-4 flex justify-end">
                    <button onClick={onClose} className="px-5 py-2 bg-gray-200 text-gray-800 dark:bg-gray-700 dark:text-white rounded-md hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors font-bold">Close</button>
                </div>
            </div>
        </div>
    );
};

// --- DASHBOARD COMPONENT ---
const ProfileDashboard: React.FC<any> = ({ profiles, transactions, stockData }) => {
    const chartRef = useRef<HTMLCanvasElement>(null);
    const chartInstance = useRef<any>(null);
    const [isListOpen, setIsListOpen] = useState(false);
    const [isLowStockOpen, setIsLowStockOpen] = useState(false);
    const [isValueOpen, setIsValueOpen] = useState(false);

    useEffect(() => {
        if (!chartRef.current || typeof Chart === 'undefined') return;
        const ctx = chartRef.current.getContext('2d');
        if (!ctx) return;
        if (chartInstance.current) chartInstance.current.destroy();
        const sorted = [...stockData].sort((a,b) => (b.currentStock - b.reservedStock) - (a.currentStock - a.reservedStock)).slice(0, 5);
        chartInstance.current = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: sorted.map(p => p.sku),
                datasets: [{ label: 'Available Stock', data: sorted.map(p => p.currentStock - p.reservedStock), backgroundColor: '#3B82F6' }]
            },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } } }
        });
        return () => { if (chartInstance.current) chartInstance.current.destroy(); };
    }, [stockData]);

    const totalValue = stockData.reduce((sum: number, p: any) => sum + (p.currentStock * (p.price || 0)), 0);
    const lowStockItems = stockData.filter((p: any) => (p.currentStock - p.reservedStock) < (p.reorderPoint || 0));

    return (
        <div className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <button onClick={() => setIsListOpen(true)} className="text-left focus:outline-none hover:scale-[1.02] transition-transform">
                    <Card className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-800">
                        <h3 className="text-xs font-bold text-blue-800 dark:text-blue-300 uppercase tracking-wider">Total Profiles</h3>
                        <p className="text-3xl font-black mt-2 text-blue-900 dark:text-white">{profiles.length}</p>
                    </Card>
                </button>
                <button onClick={() => setIsLowStockOpen(true)} className="text-left focus:outline-none hover:scale-[1.02] transition-transform">
                    <Card className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800">
                        <h3 className="text-xs font-bold text-red-800 dark:text-red-300 uppercase tracking-wider">Low Stock Alerts</h3>
                        <p className="text-3xl font-black mt-2 text-red-900 dark:text-white">{lowStockItems.length}</p>
                    </Card>
                </button>
                <button onClick={() => setIsValueOpen(true)} className="text-left focus:outline-none hover:scale-[1.02] transition-transform">
                    <Card className="bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800">
                        <h3 className="text-xs font-bold text-green-800 dark:text-green-300 uppercase tracking-wider">Stock Value</h3>
                        <p className="text-2xl font-black mt-2 text-green-900 dark:text-white font-mono">₹ {totalValue.toLocaleString('en-IN')}</p>
                    </Card>
                </button>
                <Card className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800">
                    <h3 className="text-xs font-bold text-indigo-800 dark:text-indigo-300 uppercase tracking-wider">Total Available</h3>
                    <p className="text-xl font-black mt-2 text-indigo-900 dark:text-white">{stockData.reduce((s:number,p:any)=>s+(p.currentStock-p.reservedStock), 0)}</p>
                </Card>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <Card className="h-80"><h3 className="font-bold mb-4 uppercase text-[10px] text-gray-500 tracking-widest">Top 5 Stock Distribution</h3><div className="h-60"><canvas ref={chartRef}></canvas></div></Card>
                <Card className="h-80 overflow-y-auto"><h3 className="font-bold mb-4 uppercase text-[10px] text-gray-500 tracking-widest">Recent Logs</h3>
                    <div className="space-y-3">
                        {transactions.slice(0, 10).map((t: any) => (
                            <div key={t.id} className="flex justify-between items-center text-xs border-b dark:border-gray-700 pb-2">
                                <div><span className={`font-black ${t.type === 'PRODUCTION' ? 'text-green-600' : 'text-red-600'}`}>{t.type}</span><span className="ml-2 text-gray-400 font-mono">{t.refNo}</span></div>
                                <div className="text-right font-mono"><div className="font-bold text-gray-900 dark:text-white">{t.quantity} Pcs</div></div>
                            </div>
                        ))}
                    </div>
                </Card>
            </div>
            <Portal><DashboardListModal isOpen={isListOpen} onClose={() => setIsListOpen(false)} items={stockData} title="All Profiles" type="list" /></Portal>
            <Portal><DashboardListModal isOpen={isLowStockOpen} onClose={() => setIsLowStockOpen(false)} items={lowStockItems} title="Low Stock Alerts" type="lowstock" /></Portal>
            <Portal><DashboardListModal isOpen={isValueOpen} onClose={() => setIsValueOpen(false)} items={stockData} title="Stock Value Breakdown" type="value" /></Portal>
        </div>
    );
};

// --- MAIN PROFILE SECTION ---
const ProfileSection: React.FC<ProfileSectionProps> = ({ addToast }) => {
    const [activeTab, setActiveTab] = useState<Tab>('Dashboard');
    const savedFilters = useStore(state => state.uiState.profileFilters);
    const setSavedFilters = useStore(state => state.setProfileFilters);
    const [searchTerm, setSearchTerm] = useState(savedFilters.searchTerm || '');
    const [brandFilter, setBrandFilter] = useState(savedFilters.brand || 'All');

    useEffect(() => { setSavedFilters({ searchTerm, brand: brandFilter }); }, [searchTerm, brandFilter, setSavedFilters]);

    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [transactionType, setTransactionType] = useState<'PRODUCTION' | 'DISPATCH' | 'SCRAP'>('PRODUCTION');
    const [editingTransaction, setEditingTransaction] = useState<ProfileTransaction | null>(null);
    const [isQuotationModalOpen, setIsQuotationModalOpen] = useState(false);
    const [editingQuotation, setEditingQuotation] = useState<ProfileTransaction[] | null>(null);
    const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);

    const allProfiles = useStore(state => state.profiles);
    const allTransactions = useStore(state => state.profileTransactions);
    const allCustomers = useStore(state => state.customers);
    const brands = useStore(state => state.brands);
    const companySettings = useStore(state => state.companySettings);

    const { addProfile, updateProfile, deleteProfile, addProfileTransaction, updateProfileTransaction, deleteProfileTransaction, resolveQuotation, addCustomer, updateCustomer, deleteCustomer, addBrand, updateBrand, deleteBrand, updateCompanySettings } = useStore();

    const getProfile = useCallback((id: string) => allProfiles.find(p => p.id === id), [allProfiles]);
    const getProfileName = useCallback((id: string) => getProfile(id)?.name || 'Unknown Profile', [getProfile]);
    const getBrandBadge = useCallback((brand?: string) => (<span className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300 uppercase tracking-tighter border border-gray-200 dark:border-gray-600">{brand || 'NO BRAND'}</span>), []);

    const generateInvoicePDF = useCallback((data: any) => {
        const { jsPDF } = jspdf;
        const doc = new jsPDF({ orientation: 'portrait' });
        const isQuotation = !!data.items;
        const txData = isQuotation ? data.items : [data];
        const refTx = txData[0];
        const profile = getProfile(refTx.profileId);
        const brandName = refTx.brand || profile?.brand || 'Smart';

        let logoLeft = companySettings.logoUrl;
        let logoRight = companySettings.logoRightUrl;
        const brandLogoEntry = companySettings.brandLogos?.find(bl => bl.brand === brandName);
        if (brandLogoEntry) {
            if (brandLogoEntry.logoUrl) logoLeft = brandLogoEntry.logoUrl;
            if (brandLogoEntry.logoRightUrl) logoRight = brandLogoEntry.logoRightUrl;
        }

        if (logoLeft) try { doc.addImage(logoLeft, 'JPEG', 14, 10, 30, 15); } catch (e) {}
        if (logoRight) try { doc.addImage(logoRight, 'JPEG', 165, 10, 30, 15); } catch (e) {}

        doc.setFontSize(22); doc.setTextColor(165, 42, 42); doc.text(companySettings.name.split(' ')[0] || "COMPANY", 105, 20, { align: 'center' });
        doc.setFontSize(10); doc.setTextColor(0, 0, 0); doc.text(companySettings.name, 105, 25, { align: 'center' });
        doc.setFontSize(14); doc.setFont("helvetica", "bold"); doc.text(isQuotation ? "QUOTATION" : "DISPATCH NOTE", 105, 35, { align: 'center' });

        doc.autoTable({
            startY: 40, theme: 'grid', styles: { fontSize: 8 },
            body: [[ { content: 'Company Address', styles: { fontStyle: 'bold', fillColor: [240,240,240] } }, { content: `${companySettings.addressLine1}\n${companySettings.cityStateZip}` } ]],
            margin: { left: 10, right: 10 }
        });

        let totalTaxable = 0;
        const tableBody = txData.map((t: any, i: number) => {
            const p = getProfile(t.profileId);
            const qty = Number(t.quantity || 0); 
            const price = Number(t.unitPrice ?? p?.price ?? 0);
            const amt = qty * price;
            totalTaxable += amt;
            return [ i + 1, t.profileNameOverride || p?.name || 'Unknown', t.hsnCode || p?.hsnCode || '39252000', t.profileSkuOverride || p?.sku || '', qty, amt.toLocaleString('en-IN') ];
        });

        doc.autoTable({
            startY: (doc as any).lastAutoTable.finalY + 5, theme: 'grid', styles: { fontSize: 7, halign: 'center' },
            head: [['S.N', 'Description', 'HSN', 'Code', 'Total L', 'Amount Rs']],
            body: tableBody, margin: { left: 10, right: 10 }
        });

        const finalY = (doc as any).lastAutoTable.finalY;
        const tax = totalTaxable * (companySettings.cgstRate || 9) * 2 / 100;
        doc.autoTable({
            startY: finalY, theme: 'grid', styles: { fontSize: 8 },
            body: [
                [ { content: 'Total Taxable', colSpan: 5, styles: { halign: 'right', fontStyle: 'bold' } }, { content: totalTaxable.toLocaleString('en-IN'), styles: { halign: 'right' } } ],
                [ { content: 'Total Amount (incl Tax)', colSpan: 5, styles: { halign: 'right', fontStyle: 'bold' } }, { content: Math.round(totalTaxable + tax).toLocaleString('en-IN'), styles: { halign: 'right', fontStyle: 'bold' } } ]
            ], margin: { left: 10, right: 10 }
        });
        doc.save(`${brandName}_${refTx.refNo}.pdf`);
    }, [getProfile, companySettings]);

    const stockData = useMemo(() => {
        const filtered = brandFilter === 'All' ? allProfiles : allProfiles.filter(p => p.brand === brandFilter);
        return filtered.map(p => {
            const relevantTxns = allTransactions.filter(t => t.profileId === p.id && !t.deletedAt);
            const production = relevantTxns.filter(t => t.type === 'PRODUCTION' || t.type === 'RETURN').reduce((sum, t) => sum + Number(t.quantity || 0), 0);
            const dispatch = relevantTxns.filter(t => t.type === 'DISPATCH' || t.type === 'SCRAP').reduce((sum, t) => sum + Number(t.quantity || 0), 0);
            const reserved = relevantTxns.filter(t => t.type === 'QUOTATION' && t.status === 'PEND').reduce((sum, t) => sum + Number(t.quantity || 0), 0);
            return { ...p, currentStock: production - dispatch, reservedStock: reserved };
        });
    }, [allProfiles, allTransactions, brandFilter]);

    const filteredProfiles = useMemo(() => searchTerm ? stockData.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())) : stockData, [stockData, searchTerm]);
    const productionTransactions = useFilteredTransactions(allTransactions, searchTerm, getProfile, 'PRODUCTION', brandFilter);
    const dispatchTransactions = useFilteredTransactions(allTransactions, searchTerm, getProfile, 'DISPATCH', brandFilter);
    const scrapTransactions = useFilteredTransactions(allTransactions, searchTerm, getProfile, 'SCRAP', brandFilter);

    const groupedQuotations = useMemo(() => {
        const groups: Record<string, any> = {};
        allTransactions.filter(t => (t.type === 'QUOTATION' || t.status === 'COMPLETED') && !t.deletedAt).forEach(t => {
            const p = getProfile(t.profileId);
            const brand = t.brand || p?.brand;
            if (brandFilter !== 'All' && brand !== brandFilter) return;
            if (!groups[t.refNo]) groups[t.refNo] = { refNo: t.refNo, date: t.date, customer: t.customer, status: t.status, totalAmount: 0, items: [], brand: brand };
            groups[t.refNo].totalAmount += (Number(t.quantity || 0) * (t.unitPrice || p?.price || 0));
            groups[t.refNo].items.push(t);
        });
        let result = Object.values(groups).sort((a:any, b:any) => new Date(b.date).getTime() - new Date(a.date).getTime());
        if (searchTerm) result = result.filter((g:any) => g.refNo.toLowerCase().includes(searchTerm.toLowerCase()) || g.customer?.toLowerCase().includes(searchTerm.toLowerCase()));
        return result;
    }, [allTransactions, searchTerm, getProfile, brandFilter]);

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white tracking-tight">Profile Inventory</h1>
                <div className="flex flex-col sm:flex-row gap-3 items-center">
                    <div className="flex items-center gap-2 bg-white dark:bg-gray-800 p-1 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm">
                        {activeTab !== 'Dashboard' && (
                            <div className="relative"><input type="text" placeholder="Search..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="pl-7 pr-2 py-1 border-none bg-transparent focus:ring-0 w-32 sm:w-48 text-sm dark:text-white" /><SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" /></div>
                        )}
                        <select value={brandFilter} onChange={(e) => setBrandFilter(e.target.value)} className="bg-transparent text-gray-900 dark:text-white border-none text-sm font-black focus:ring-0 cursor-pointer pr-8">
                            <option value="All">All Brands</option>
                            {brands.map(b => <option key={b} value={b}>{b}</option>)}
                        </select>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => setIsSettingsModalOpen(true)} className="p-2 text-gray-500 hover:text-gray-800 dark:hover:text-white bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-lg shadow-sm">⚙️</button>
                        <button onClick={() => {
                            if (activeTab === 'Production') { setTransactionType('PRODUCTION'); setIsTransactionModalOpen(true); }
                            else if (activeTab === 'Dispatch') { setTransactionType('DISPATCH'); setIsTransactionModalOpen(true); }
                            else if (activeTab === 'Scrap') { setTransactionType('SCRAP'); setIsTransactionModalOpen(true); }
                            else if (activeTab === 'Profiles') setIsProfileModalOpen(true);
                            else if (activeTab === 'Customers') setIsCustomerModalOpen(true);
                            else setIsQuotationModalOpen(true);
                        }} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md hover:bg-blue-700">+ Add Entry</button>
                    </div>
                </div>
            </div>

            <div className="border-b border-gray-200 dark:border-gray-700 no-print">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {(['Dashboard', 'Stock', 'Production', 'Dispatch', 'Scrap', 'Quotations', 'Profiles', 'Customers'] as Tab[]).map(tab => (
                        <button key={tab} onClick={() => setActiveTab(tab)} className={`${activeTab === tab ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'} whitespace-nowrap py-3 px-1 border-b-2 font-bold text-sm transition-all`}>{tab}</button>
                    ))}
                </nav>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-md shadow min-h-[400px]">
                {activeTab === 'Dashboard' && <ProfileDashboard profiles={filteredProfiles} transactions={allTransactions} stockData={stockData} />}
                {activeTab === 'Stock' && <StockTable stockData={filteredProfiles} onEditProfile={(p:Profile) => {setEditingProfile(p); setIsProfileModalOpen(true);}} getBrandBadge={getBrandBadge} />}
                {activeTab === 'Production' && <TransactionTable transactions={productionTransactions} getProfileName={getProfileName} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={deleteProfileTransaction} type="PRODUCTION" getBrandBadge={getBrandBadge} getProfile={getProfile} />}
                {activeTab === 'Dispatch' && <TransactionTable transactions={dispatchTransactions} getProfileName={getProfileName} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={deleteProfileTransaction} onPrint={generateInvoicePDF} type="DISPATCH" getBrandBadge={getBrandBadge} getProfile={getProfile} />}
                {activeTab === 'Scrap' && <TransactionTable transactions={scrapTransactions} getProfileName={getProfileName} onEdit={(tx:any) => { setEditingTransaction(tx); setIsTransactionModalOpen(true); }} onDelete={deleteProfileTransaction} type="SCRAP" getBrandBadge={getBrandBadge} getProfile={getProfile} />}
                {activeTab === 'Quotations' && <QuotationTable groupedQuotations={groupedQuotations} onAction={(refNo:string, action:any) => { allTransactions.filter(t=>t.refNo===refNo).forEach(t=>resolveQuotation(t.id, action)); addToast('Quotation updated','success'); }} onEdit={(refNo:string) => { setEditingQuotation(allTransactions.filter(t => t.refNo === refNo)); setIsQuotationModalOpen(true); }} onDelete={(refNo:any) => { if(confirm('Delete entire quotation?')) allTransactions.filter(t => t.refNo === refNo).forEach(t => deleteProfileTransaction(t.id)); }} onPrint={generateInvoicePDF} getBrandBadge={getBrandBadge} />}
                {activeTab === 'Profiles' && <ProfileListTable profiles={filteredProfiles} onEdit={(p:Profile) => { setEditingProfile(p); setIsProfileModalOpen(true); }} onDelete={deleteProfile} getBrandBadge={getBrandBadge} />}
                {activeTab === 'Customers' && <CustomerTable customers={allCustomers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()))} onEdit={(c:Customer) => { setEditingCustomer(c); setIsCustomerModalOpen(true); }} onDelete={deleteCustomer} />}
            </div>

            <Portal><AddProfileModal isOpen={isProfileModalOpen} onClose={() => {setIsProfileModalOpen(false); setEditingProfile(null);}} onAdd={editingProfile ? (data) => { updateProfile({...editingProfile, ...data}); return {...editingProfile, ...data}; } : addProfile} brands={brands} addToast={addToast} initialData={editingProfile} /></Portal>
            <Portal><CustomerModal isOpen={isCustomerModalOpen} onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} onSave={editingCustomer ? (data) => updateCustomer({...editingCustomer, ...data}) : addCustomer} customer={editingCustomer} addToast={addToast} /></Portal>
            <Portal><TransactionModal isOpen={isTransactionModalOpen} onClose={() => { setIsTransactionModalOpen(false); setEditingTransaction(null); }} type={transactionType} profiles={allProfiles} brands={brands} onAdd={addProfileTransaction} addToast={addToast} customers={allCustomers} /></Portal>
            <Portal><EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} onUpdate={updateProfileTransaction} /></Portal>
            <Portal><CreateQuotationModal isOpen={isQuotationModalOpen} onClose={() => {setIsQuotationModalOpen(false); setEditingQuotation(null);}} profiles={allProfiles} customers={allCustomers} onAddMultiple={(txs) => txs.forEach(addProfileTransaction)} addCustomer={addCustomer} addToast={addToast} existingTransactions={editingQuotation ? editingQuotation : undefined} brands={brands} addBrand={addBrand} deleteBrand={deleteBrand} /></Portal>
            <Portal><CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} brands={brands} updateBrand={updateBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
        </div>
    );
};

