const TransactionModal: React.FC<any> = ({ isOpen, onClose, type, profiles, brands, onAdd, addToast, customers }) => {
    const [form, setForm] = useState({ profileId: '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' });
    const [modalBrandFilter, setModalBrandFilter] = useState('All');
    const filteredProfiles = useMemo(() => modalBrandFilter === 'All' ? profiles : profiles.filter((p: any) => p.brand === modalBrandFilter), [profiles, modalBrandFilter]);
