// --- DASHBOARD LIST MODAL ---
const DashboardListModal: React.FC<{ isOpen: boolean; onClose: () => void; items: any[]; title: string; type?: 'value' | 'lowstock' | 'list' }> = ({ isOpen, onClose, items, title, type = 'list' }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const sortedItems = useMemo(() => {
        let sorted = [...items];
        if (type === 'value') sorted.sort((a, b) => (b.currentStock * (b.price || 0)) - (a.currentStock * (a.price || 0)));
        else if (type === 'lowstock') sorted.sort((a, b) => (a.currentStock - a.reservedStock) - (b.currentStock - b.reservedStock));
        else sorted.sort((a, b) => a.name.localeCompare(b.name));
        return sorted;
    }, [items, type]);

    const filtered = useMemo(() => sortedItems.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [sortedItems, searchTerm]);
