                else currentLogos.push({ brand, logoUrl: type === 'logo' ? base64 : '', logoRightUrl: type === 'logoRight' ? base64 : '' });
                setForm({ ...form, brandLogos: currentLogos });
            } else {
                setForm({ ...form, [type === 'logo' ? 'logoUrl' : 'logoRightUrl']: base64 });
            }
        };
        reader.readAsDataURL(file);
    };

