    const [modalBrandFilter, setModalBrandFilter] = useState('All');
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);

    const filteredProfiles = useMemo(() => modalBrandFilter === 'All' ? profiles : profiles.filter((p: any) => p.brand === modalBrandFilter), [profiles, modalBrandFilter]);
    useEffect(() => { if(isOpen) setForm({ profileId: filteredProfiles[0]?.id || '', quantity: '', uom: 'Pcs', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' }); }, [isOpen, filteredProfiles]);
    if(!isOpen) return null;
    const filteredCustomers = customers.filter((c:any) => c.name.toLowerCase().includes(customerSearch.toLowerCase()) && !c.deletedAt);
    const selectCustomer = (c: any) => { setForm(prev => ({ ...prev, customer: c.name, customerAddress: c.address || '', customerGST: c.gstin || '', customerPhone: c.phone || '' })); setCustomerSearch(c.name); setShowSuggestions(false); };
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); if (!form.profileId) { addToast('Select a profile', 'error'); return; } onAdd({ ...form, quantity: parseFloat(form.quantity), type }); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";
    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[160] flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
                <div className="px-6 py-4 bg-gray-900 text-white flex justify-between items-center"><h2 className="text-xl font-bold uppercase">{type} Entry</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl">&times;</button></div>
                <div className="p-6 overflow-y-auto"><form onSubmit={handleSubmit} className="space-y-4">
                    <div><label className="text-xs font-bold uppercase text-gray-500 mb-1 block">Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required /></div>
                    <div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded-lg border dark:border-gray-700 space-y-3">
                        <select value={modalBrandFilter} onChange={(e) => setModalBrandFilter(e.target.value)} className={inputClass}><option value="All">All Brands</option>{brands.map((b:string) => <option key={b} value={b}>{b}</option>)}</select>
                        <select value={form.profileId} onChange={e => setForm({...form, profileId: e.target.value})} className={inputClass} required><option value="">-- Choose Profile --</option>{filteredProfiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select>
                    </div>
                    <div><label className="text-xs font-bold uppercase text-gray-500 mb-1 block">Ref No</label><input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} required /></div>
                    <div><label className="text-xs font-bold uppercase text-gray-500 mb-1 block">Quantity</label><input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} required /></div>
                    {type === 'DISPATCH' && <div className="relative"><label className="text-xs font-bold uppercase text-gray-500 mb-1 block">Customer</label><input value={form.customer} onChange={e => { setForm({...form, customer: e.target.value}); setCustomerSearch(e.target.value); setShowSuggestions(true); }} className={inputClass} required placeholder="Search customer..." />{showSuggestions && customerSearch && filteredCustomers.length > 0 && (<div className="absolute z-20 w-full bg-white dark:bg-gray-700 border dark:border-gray-600 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">{filteredCustomers.map((c:any) => (<div key={c.id} onClick={() => selectCustomer(c)} className="px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-600 cursor-pointer text-sm font-bold border-b last:border-0 dark:border-gray-600">{c.name}</div>))}</div>)}</div>}
                    <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded">Cancel</button><button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded font-bold shadow hover:bg-blue-700 uppercase text-xs">Save</button></div>
                </form></div>
            </div>
        </div>
    );
};

