                                    {currentBrandLogo?.logoUrl || form.logoUrl ? (
                                        <img src={currentBrandLogo?.logoUrl || form.logoUrl} style={{ height: `${logoScale}%`, objectFit: 'contain' }} className="max-h-full max-w-full" />
